#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecoverMode {
  None,
  Lazy,
  Eager,
}

impl RecoverMode {
  pub fn parse(value: &str) -> Result<Self> {
    match value.trim().to_ascii_lowercase().as_str() {
      "none" => Ok(Self::None),
      "lazy" => Ok(Self::Lazy),
      "eager" => Ok(Self::Eager),
      other => anyhow::bail!("invalid recover mode: {} (expected none|lazy|eager)", other),
    }
  }
}

#[derive(Debug, Clone)]
pub struct RuntimeConfig {
  pub state_dir: PathBuf,
  pub log_dir: PathBuf,
  pub bootstrap_file: Option<PathBuf>,
  pub cgroup_root: Option<PathBuf>,
  pub cgroup_require: bool,
  pub recover_mode: RecoverMode,
  pub token_file: Option<PathBuf>,
  pub policy_reload_ms: u64,
  pub audit_enabled: bool,
  pub audit: AuditConfig,
  pub reconcile_tick_ms: u64,
  pub event_buffer_capacity: usize,
  pub job_workers: usize,
  pub job_lease_ms: u64,
  pub job_poll_ms: u64,
  pub housekeeping_interval_ms: u64,
  pub retention_bundle_days: u64,
}

impl Default for RuntimeConfig {
  fn default() -> Self {
    let state_dir = PathBuf::from("/tmp/pnix-supervisor-state");
    let audit_dir = state_dir.join("audit");
    Self {
      log_dir: state_dir.join("logs"),
      state_dir,
      bootstrap_file: None,
      cgroup_root: None,
      cgroup_require: false,
      recover_mode: RecoverMode::Lazy,
      token_file: None,
      policy_reload_ms: 1_000,
      audit_enabled: true,
      audit: AuditConfig::with_dir(audit_dir),
      reconcile_tick_ms: 1_000,
      event_buffer_capacity: 10_000,
      job_workers: 2,
      job_lease_ms: 60_000,
      job_poll_ms: 200,
      housekeeping_interval_ms: 60_000,
      retention_bundle_days: 30,
    }
  }
}

