#[derive(Debug, Clone)]
pub struct TlsServerConfig {
  pub cert_path: PathBuf,
  pub key_path: PathBuf,
  pub client_ca_path: Option<PathBuf>,
  pub require_client_auth: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ListenEndpoint {
  Uds(PathBuf),
  Tls(String),
}

impl ListenEndpoint {
  fn parse(raw: &str) -> Result<Self> {
    let value = raw.trim();
    if let Some(path) = value.strip_prefix("uds:") {
      let trimmed = path.trim();
      if trimmed.is_empty() {
        anyhow::bail!("invalid uds endpoint `{}`: missing path", value);
      }
      return Ok(Self::Uds(PathBuf::from(trimmed)));
    }

    if let Some(addr) = value.strip_prefix("tls://") {
      let trimmed = addr.trim();
      if trimmed.is_empty() {
        anyhow::bail!("invalid tls endpoint `{}`: missing host:port", value);
      }
      return Ok(Self::Tls(trimmed.to_string()));
    }

    if let Some(addr) = value.strip_prefix("tls:") {
      let trimmed = addr.trim();
      if trimmed.is_empty() {
        anyhow::bail!("invalid tls endpoint `{}`: missing host:port", value);
      }
      return Ok(Self::Tls(trimmed.to_string()));
    }

    Ok(Self::Uds(PathBuf::from(value)))
  }
}

