#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum DriftPolicy {
  #[serde(rename = "restart")]
  Restart,
  #[serde(rename = "replace")]
  Replace,
  #[serde(rename = "rolling")]
  Rolling,
  #[serde(rename = "ignore")]
  Ignore,
  #[serde(rename = "error")]
  Error,
}

fn default_drift_policy() -> DriftPolicy {
  DriftPolicy::Restart
}

fn drift_restart_tag(policy: &DriftPolicy) -> Option<&'static str> {
  match policy {
    DriftPolicy::Restart => Some("restarted"),
    DriftPolicy::Replace => Some("replaced"),
    DriftPolicy::Rolling => Some("rolling_restarted"),
    DriftPolicy::Ignore | DriftPolicy::Error => None,
  }
}

