#[derive(Debug, Clone, Serialize)]
struct LogLine {
  ts_ms: u128,
  stream: &'static str,
  line: String,
}

#[derive(Debug)]
struct LogBuffer {
  max_lines: usize,
  lines: VecDeque<LogLine>,
}

impl LogBuffer {
  fn new(max_lines: usize) -> Self {
    Self {
      max_lines: max_lines.max(1),
      lines: VecDeque::new(),
    }
  }

  fn push(&mut self, stream: &'static str, line: String) {
    self.lines.push_back(LogLine {
      ts_ms: now_ms(),
      stream,
      line,
    });
    while self.lines.len() > self.max_lines {
      let _ = self.lines.pop_front();
    }
  }

  fn tail(&self, n: usize, stream: Option<&str>) -> Vec<LogLine> {
    let mut out = Vec::new();
    for line in self.lines.iter().rev() {
      if let Some(s) = stream {
        if s != "all" && line.stream != s {
          continue;
        }
      }
      out.push(line.clone());
      if out.len() >= n {
        break;
      }
    }
    out.reverse();
    out
  }
}

