fn normalize_risk(value: Option<&str>, default: &str) -> String {
  let normalized = value
    .map(str::trim)
    .filter(|v| !v.is_empty())
    .unwrap_or(default)
    .to_ascii_lowercase();
  match normalized.as_str() {
    "low" | "medium" | "high" => normalized,
    _ => default.to_string(),
  }
}

fn normalize_plan_status(value: Option<&str>, default: &str) -> String {
  value
    .map(str::trim)
    .filter(|v| !v.is_empty())
    .unwrap_or(default)
    .to_ascii_lowercase()
}

fn plan_step_view(step: &PlanStepEntry) -> Value {
  json!({
    "step_no": step.step_no,
    "kind": step.kind,
    "spec": redact_value(&step.spec_json),
    "status": step.status,
    "started_ms": step.started_ms,
    "finished_ms": step.finished_ms,
    "last_error": step.last_error,
  })
}

fn remediation_plan_view(plan: &RemediationPlanEntry) -> Value {
  json!({
    "ns": plan.ns,
    "plan_id": plan.plan_id,
    "created_ms": plan.created_ms,
    "updated_ms": plan.updated_ms,
    "risk": plan.risk,
    "status": plan.status,
    "summary": plan.summary,
    "trigger": redact_value(&plan.trigger_json),
    "invocation_id": plan.invocation_id,
    "session_id": plan.session_id,
    "change_id": plan.change_id,
    "steps": plan.steps.iter().map(plan_step_view).collect::<Vec<_>>(),
  })
}

fn change_request_view(change: &ChangeRequestEntry) -> Value {
  json!({
    "ns": change.ns,
    "change_id": change.change_id,
    "created_ms": change.created_ms,
    "updated_ms": change.updated_ms,
    "title": change.title,
    "reason": change.reason,
    "source": change.source,
    "risk": change.risk,
    "status": change.status,
    "policy_id": change.policy_id,
    "invocation_id": change.invocation_id,
    "session_id": change.session_id,
    "plan_id": change.plan_id,
    "scheduled_start_ms": change.scheduled_start_ms,
    "scheduled_end_ms": change.scheduled_end_ms,
    "last_error": change.last_error,
    "approvals": change.approvals,
    "steps": change.steps.iter().map(plan_step_view).collect::<Vec<_>>(),
  })
}

fn load_remediation_plan_store(runtime: &RuntimeConfig) -> Result<RemediationPlanStore> {
  let path = runtime.remediation_plan_file();
  if !path.exists() {
    return Ok(RemediationPlanStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read remediation plan index {}", path.display()))?;
  let persisted: PersistedRemediationPlanIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse remediation plan index {}", path.display()))?;
  if persisted.version != REMEDIATION_PLAN_INDEX_VERSION {
    anyhow::bail!(
      "unsupported remediation plan index version `{}` (expected `{}`)",
      persisted.version,
      REMEDIATION_PLAN_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.plans {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.plan_id = row.plan_id.trim().to_string();
    if row.plan_id.is_empty() {
      continue;
    }
    row.risk = normalize_risk(Some(row.risk.as_str()), "medium");
    row.status = normalize_plan_status(Some(row.status.as_str()), "proposed");
    for (idx, step) in row.steps.iter_mut().enumerate() {
      step.step_no = (idx as u32) + 1;
      step.kind = step.kind.trim().to_string();
      if step.status.trim().is_empty() {
        step.status = "pending".to_string();
      }
    }
    by_key.insert(
      remediation_plan_key(row.ns.as_str(), row.plan_id.as_str()),
      row,
    );
  }
  Ok(RemediationPlanStore { by_key })
}

fn save_remediation_plan_store(
  plans: &Arc<RwLock<RemediationPlanStore>>,
  runtime: &RuntimeConfig,
) -> Result<()> {
  let mut rows: Vec<RemediationPlanEntry> = {
    let guard = plans.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.values().cloned().collect()
  };
  rows.sort_by(|a, b| {
    a.ns
      .cmp(&b.ns)
      .then_with(|| b.created_ms.cmp(&a.created_ms))
      .then_with(|| a.plan_id.cmp(&b.plan_id))
  });
  write_json_atomic(
    runtime.remediation_plan_file().as_path(),
    &PersistedRemediationPlanIndex {
      version: REMEDIATION_PLAN_INDEX_VERSION.to_string(),
      updated_ms: now_ms(),
      plans: rows,
    },
  )
}

