fn load_blueprint_bundle_store(runtime: &RuntimeConfig) -> Result<BlueprintBundleStore> {
  let path = runtime.blueprint_bundle_file();
  if !path.exists() {
    return Ok(BlueprintBundleStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read blueprint bundle index {}", path.display()))?;
  let persisted: PersistedBlueprintBundleIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse blueprint bundle index {}", path.display()))?;
  if persisted.version != BLUEPRINT_BUNDLE_INDEX_VERSION {
    anyhow::bail!(
      "unsupported blueprint bundle index version `{}` (expected `{}`)",
      persisted.version,
      BLUEPRINT_BUNDLE_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.entries {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.bundle_id = row.bundle_id.trim().to_string();
    row.name = row.name.trim().to_string();
    row.version = row.version.trim().to_string();
    row.bundle_ref_id = row.bundle_ref_id.trim().to_string();
    row.sha256 = row
      .sha256
      .trim()
      .trim_start_matches("sha256:")
      .to_ascii_lowercase();
    row.status = normalize_blueprint_bundle_status(Some(row.status));
    row.attestation_ref_id = row
      .attestation_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    if row.bundle_id.is_empty()
      || row.name.is_empty()
      || row.version.is_empty()
      || row.bundle_ref_id.is_empty()
      || row.sha256.is_empty()
    {
      continue;
    }
    by_key.insert(
      blueprint_bundle_key(row.ns.as_str(), row.bundle_id.as_str()),
      row,
    );
  }
  Ok(BlueprintBundleStore { by_key })
}

