fn normalize_indicator_state(raw: Option<String>, indicator_required: bool) -> String {
  let state = raw
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  match state.as_deref() {
    Some("alive") => "alive".to_string(),
    Some("lost") => "lost".to_string(),
    Some("unknown") => "unknown".to_string(),
    Some("disabled") => "disabled".to_string(),
    _ => {
      if indicator_required {
        "unknown".to_string()
      } else {
        "disabled".to_string()
      }
    }
  }
}

fn normalize_indicator_grace_ms(raw: Option<u64>) -> u64 {
  raw.unwrap_or(BREAKGLASS_INDICATOR_GRACE_MS_DEFAULT).clamp(
    BREAKGLASS_INDICATOR_GRACE_MS_MIN,
    BREAKGLASS_INDICATOR_GRACE_MS_MAX,
  )
}

