fn load_pki_cert_store(runtime: &RuntimeConfig) -> Result<PkiCertStore> {
  let path = runtime.pki_cert_file();
  if !path.exists() {
    return Ok(PkiCertStore::default());
  }
  let bytes = fs::read(&path).with_context(|| format!("read pki cert index {}", path.display()))?;
  let persisted: PersistedPkiCertIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse pki cert index {}", path.display()))?;
  if persisted.version != PKI_CERT_INDEX_VERSION {
    anyhow::bail!(
      "unsupported pki cert index version `{}` (expected `{}`)",
      persisted.version,
      PKI_CERT_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.entries {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.cert_id = row.cert_id.trim().to_string();
    row.kind = row.kind.trim().to_ascii_lowercase();
    row.subject = row.subject.trim().to_string();
    row.issuer = row.issuer.trim().to_ascii_lowercase();
    row.status = normalize_pki_cert_status(Some(row.status));
    row.issuer_ref = row
      .issuer_ref
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.cert_ref_id = row
      .cert_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.key_secret_ref = row
      .key_secret_ref
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.replaced_by_cert_id = row
      .replaced_by_cert_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    if !row.san_dns_json.is_array() {
      row.san_dns_json = json!([]);
    }
    if !row.san_uri_json.is_array() {
      row.san_uri_json = json!([]);
    }
    if row.cert_id.is_empty() || row.kind.is_empty() || row.subject.is_empty() {
      continue;
    }
    by_key.insert(pki_cert_key(row.ns.as_str(), row.cert_id.as_str()), row);
  }
  Ok(PkiCertStore { by_key })
}

