    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.source_id = row.source_id.trim().to_string();
    row.last_seen_commit = row
      .last_seen_commit
      .as_deref()
      .map(str::trim)
