fn load_policy_eval_log_store(runtime: &RuntimeConfig) -> Result<PolicyEvalLogStore> {
  let path = runtime.policy_eval_log_file();
  if !path.exists() {
    return Ok(PolicyEvalLogStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read policy eval log index {}", path.display()))?;
  let persisted: PersistedPolicyEvalLogIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse policy eval log index {}", path.display()))?;
  if persisted.version != POLICY_EVAL_LOG_INDEX_VERSION {
    anyhow::bail!(
      "unsupported policy eval log index version `{}` (expected `{}`)",
      persisted.version,
      POLICY_EVAL_LOG_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.entries {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.eval_id = row.eval_id.trim().to_string();
    row.target = row.target.trim().to_string();
    row.decision = row.decision.trim().to_ascii_lowercase();
    row.channel = row
      .channel
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_ascii_lowercase);
    row.release_id = row
      .release_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.subject_kind = row
      .subject_kind
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.subject_id = row
      .subject_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.invocation_id = row
      .invocation_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.change_id = row
      .change_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.git_commit = row
      .git_commit
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    if !row.reasons_json.is_array() {
      row.reasons_json = json!([]);
    }
    if !row.warnings_json.is_array() {
      row.warnings_json = json!([]);
    }
    if row.eval_id.is_empty() || row.target.is_empty() || row.decision.is_empty() {
      continue;
    }
    by_key.insert(
      policy_eval_log_key(row.ns.as_str(), row.eval_id.as_str()),
      row,
    );
  }
  Ok(PolicyEvalLogStore { by_key })
}

