fn load_alert_rule_store(runtime: &RuntimeConfig) -> Result<AlertRuleStore> {
  let path = runtime.alert_rule_file();
  if !path.exists() {
    return Ok(AlertRuleStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read alert rule index {}", path.display()))?;
  let persisted: PersistedAlertRuleIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse alert rule index {}", path.display()))?;
  if persisted.version != ALERT_RULE_INDEX_VERSION {
    anyhow::bail!(
      "unsupported alert rule index version `{}` (expected `{}`)",
      persisted.version,
      ALERT_RULE_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.entries {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.rule_id = row.rule_id.trim().to_string();
    row.name = row.name.trim().to_string();
    row.source_kind = row.source_kind.trim().to_ascii_lowercase();
    if !row.selector_json.is_object() {
      row.selector_json = json!({});
    }
    row.window_ms = row.window_ms.clamp(1_000, 7 * 24 * 60 * 60 * 1000);
    row.eval_every_ms = row.eval_every_ms.clamp(1_000, row.window_ms);
    if !row.condition_json.is_object() {
      row.condition_json = json!({});
    }
    row.severity = normalize_incident_severity(Some(row.severity));
    row.dedupe_key_template = row.dedupe_key_template.trim().to_string();
    if row.dedupe_key_template.is_empty() {
      row.dedupe_key_template = format!("rule:{}:scope:{}", row.rule_id, row.source_kind);
    }
    if !row.labels_json.is_object() {
      row.labels_json = json!({});
    }
    if !row.autopilot_json.is_object() {
      row.autopilot_json = json!({});
    }
    row.status = normalize_alert_rule_status(Some(row.status));
    if row.rule_id.is_empty() || row.name.is_empty() || row.source_kind.is_empty() {
      continue;
    }
    by_key.insert(alert_rule_key(row.ns.as_str(), row.rule_id.as_str()), row);
  }
  Ok(AlertRuleStore { by_key })
}

