fn load_incident_store(runtime: &RuntimeConfig) -> Result<IncidentStore> {
  let path = runtime.incident_file();
  if !path.exists() {
    return Ok(IncidentStore::default());
  }
  let bytes = fs::read(&path).with_context(|| format!("read incident index {}", path.display()))?;
  let persisted: PersistedIncidentIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse incident index {}", path.display()))?;
  if persisted.version != INCIDENT_INDEX_VERSION {
    anyhow::bail!(
      "unsupported incident index version `{}` (expected `{}`)",
      persisted.version,
      INCIDENT_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.entries {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.incident_id = row.incident_id.trim().to_string();
    row.severity = normalize_incident_severity(Some(row.severity));
    row.status = normalize_incident_status(Some(row.status));
    row.title = row.title.trim().to_string();
    row.primary_object_kind = row.primary_object_kind.trim().to_ascii_lowercase();
    row.primary_object_id = row.primary_object_id.trim().to_string();
    if !row.affected_json.is_object() {
      row.affected_json = json!({});
    }
    if !row.owner_json.is_object() {
      row.owner_json = json!({});
    }
    if !row.suspected_causes_json.is_array() {
      row.suspected_causes_json = json!([]);
    }
    if !row.related_change_ids_json.is_array() {
      row.related_change_ids_json = json!([]);
    }
    if !row.related_release_ids_json.is_array() {
      row.related_release_ids_json = json!([]);
    }
    if !row.related_git_commits_json.is_array() {
      row.related_git_commits_json = json!([]);
    }
    if !row.resolution_json.is_object() {
      row.resolution_json = json!({});
    }
    if row.incident_id.is_empty() || row.title.is_empty() {
      continue;
    }
    by_key.insert(incident_key(row.ns.as_str(), row.incident_id.as_str()), row);
  }
  Ok(IncidentStore { by_key })
}

fn save_incident_store(store: &Arc<RwLock<IncidentStore>>, runtime: &RuntimeConfig) -> Result<()> {
  let mut rows: Vec<IncidentEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.values().cloned().collect()
  };
  rows.sort_by(|a, b| {
    a.ns
      .cmp(&b.ns)
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
      .then_with(|| a.incident_id.cmp(&b.incident_id))
  });
  write_json_atomic(
    runtime.incident_file().as_path(),
    &PersistedIncidentIndex {
      version: INCIDENT_INDEX_VERSION.to_string(),
      updated_ms: now_ms(),
      entries: rows,
    },
  )
}

