fn find_exec_cache_entry(
  namespace: &str,
  exec_ref_id: &str,
  exec_cache: &Arc<RwLock<ExecCacheStore>>,
) -> Option<ExecCacheEntry> {
  let host = current_host_id();
  let key = exec_cache_key(host.as_str(), namespace, exec_ref_id);
  let guard = exec_cache.read().unwrap_or_else(|e| e.into_inner());
  if let Some(entry) = guard.by_key.get(&key) {
    return Some(entry.clone());
  }
  guard
    .by_key
    .values()
    .find(|entry| {
      entry.ns == namespace
        && entry.exec_ref_id == exec_ref_id
        && entry.status.eq_ignore_ascii_case("ready")
    })
    .cloned()
}

fn exec_cache_upsert_impl(
  request: ExecCacheUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let exec_ref_id = request.exec_ref_id.trim();
  if exec_ref_id.is_empty() {
    anyhow::bail!("exec.cache.upsert requires exec_ref_id");
  }
  let path = PathBuf::from(request.path.trim());
  if !path.is_absolute() {
    anyhow::bail!("exec.cache.upsert requires absolute path");
  }
  if !path.exists() {
    anyhow::bail!("exec.cache.upsert path does not exist: {}", path.display());
  }
  let entrypoint = request.entrypoint.trim();
  if entrypoint.is_empty() {
    anyhow::bail!("exec.cache.upsert requires entrypoint");
  }
  if Path::new(entrypoint).is_absolute() {
    anyhow::bail!("exec.cache.upsert entrypoint must be a relative path");
  }
  let status = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .unwrap_or("ready")
    .to_ascii_lowercase();
  let host = current_host_id();
  let key = exec_cache_key(host.as_str(), namespace.as_str(), exec_ref_id);
  let exec_cache = get_exec_cache_global()?;
  {
    let mut guard = exec_cache.write().unwrap_or_else(|e| e.into_inner());
    let now = now_ms();
    let existing_created = guard.by_key.get(&key).map(|entry| entry.created_ms);
    guard.by_key.insert(
      key,
      ExecCacheEntry {
        host: host.clone(),
        ns: namespace.clone(),
        exec_ref_id: exec_ref_id.to_string(),
        path: path.display().to_string(),
        entrypoint: entrypoint.to_string(),
        status: status.clone(),
        created_ms: existing_created.unwrap_or(now),
        updated_ms: now,
        size_bytes: request
          .size_bytes
          .or_else(|| fs::metadata(&path).ok().map(|meta| meta.len())),
        last_error: None,
        pinned: request.pinned.unwrap_or(false),
        last_access_ms: Some(now),
      },
    );
  }
  save_exec_cache_store(&exec_cache, runtime)?;
  publish_supervisor_event(
    events,
    "exec.cache.upserted",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__exec_cache__")),
    None,
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "host": host,
      "exec_ref_id": exec_ref_id,
      "path": path.display().to_string(),
      "entrypoint": entrypoint,
      "status": status,
      "pinned": request.pinned.unwrap_or(false),
    }),
  );
  Ok(json!({
    "ns": namespace,
    "host": host,
    "exec_ref_id": exec_ref_id,
    "path": path.display().to_string(),
    "entrypoint": entrypoint,
    "status": status,
  }))
}

fn exec_cache_list_impl(request: ExecCacheListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase());
  let limit = request.limit.unwrap_or(200).clamp(1, 5_000);
  let exec_cache = get_exec_cache_global()?;
  let mut rows: Vec<ExecCacheEntry> = {
    let guard = exec_cache.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|status| entry.status == status)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.updated_ms
      .cmp(&a.updated_ms)
      .then_with(|| a.exec_ref_id.cmp(&b.exec_ref_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows,
  }))
}

fn normalize_channel(channel: String) -> Result<String> {
  let trimmed = channel.trim();
  if trimmed.is_empty() {
    anyhow::bail!("channel cannot be empty");
  }
  if trimmed.len() > 64 {
    anyhow::bail!("channel is too long (max 64 chars)");
  }
  if !trimmed
    .chars()
    .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
  {
    anyhow::bail!("channel contains unsupported characters (allowed: [A-Za-z0-9._-])");
  }
  Ok(trimmed.to_ascii_lowercase())
}

