fn compliance_mode(policy_json: &Value) -> String {
  policy_json
    .get("mode")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase())
    .filter(|value| matches!(value.as_str(), "permissive" | "enforcing" | "locked"))
    .unwrap_or_else(|| "permissive".to_string())
}

fn compliance_is_enforcing(policy_json: &Value) -> bool {
  matches!(
    compliance_mode(policy_json).as_str(),
    "enforcing" | "locked"
  )
}

fn load_compliance_policy_store(runtime: &RuntimeConfig) -> Result<CompliancePolicyStore> {
  let path = runtime.compliance_policy_file();
  if !path.exists() {
    return Ok(CompliancePolicyStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read compliance policy index {}", path.display()))?;
  let persisted: PersistedCompliancePolicyIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse compliance policy index {}", path.display()))?;
  if persisted.version != COMPLIANCE_POLICY_INDEX_VERSION {
    anyhow::bail!(
      "unsupported compliance policy index version `{}` (expected `{}`)",
      persisted.version,
      COMPLIANCE_POLICY_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.policies {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.channel = normalize_channel(row.channel).unwrap_or_else(|_| "prod".to_string());
    by_key.insert(
      compliance_policy_key(row.ns.as_str(), row.channel.as_str()),
      row,
    );
  }
  Ok(CompliancePolicyStore { by_key })
}

fn save_compliance_policy_store(
  policies: &Arc<RwLock<CompliancePolicyStore>>,
  runtime: &RuntimeConfig,
) -> Result<()> {
  let mut rows: Vec<CompliancePolicyEntry> = {
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.values().cloned().collect()
  };
  rows.sort_by(|a, b| {
    a.ns
      .cmp(&b.ns)
      .then_with(|| a.channel.cmp(&b.channel))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  write_json_atomic(
    runtime.compliance_policy_file().as_path(),
    &PersistedCompliancePolicyIndex {
      version: COMPLIANCE_POLICY_INDEX_VERSION.to_string(),
      updated_ms: now_ms(),
      policies: rows,
    },
  )
}

fn load_compliance_exception_store(runtime: &RuntimeConfig) -> Result<ComplianceExceptionStore> {
  let path = runtime.compliance_exception_file();
  if !path.exists() {
    return Ok(ComplianceExceptionStore::default());
  }
  let bytes = fs::read(&path)
    .with_context(|| format!("read compliance exception index {}", path.display()))?;
  let persisted: PersistedComplianceExceptionIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse compliance exception index {}", path.display()))?;
  if persisted.version != COMPLIANCE_EXCEPTION_INDEX_VERSION {
    anyhow::bail!(
      "unsupported compliance exception index version `{}` (expected `{}`)",
      persisted.version,
      COMPLIANCE_EXCEPTION_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.exceptions {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.channel = normalize_channel(row.channel).unwrap_or_else(|_| "prod".to_string());
    row.exc_id = row.exc_id.trim().to_string();
    row.target = row.target.trim().to_ascii_lowercase();
    row.status = row.status.trim().to_ascii_lowercase();
    if row.exc_id.is_empty() || row.target.is_empty() {
      continue;
    }
    if row.status.is_empty() {
      row.status = "pending".to_string();
    }
    if row.approvals_required == 0 {
      row.approvals_required = 1;
    }
    by_key.insert(
      compliance_exception_key(row.ns.as_str(), row.exc_id.as_str()),
      row,
    );
  }
  Ok(ComplianceExceptionStore { by_key })
}

fn save_compliance_exception_store(
  exceptions: &Arc<RwLock<ComplianceExceptionStore>>,
  runtime: &RuntimeConfig,
) -> Result<()> {
  let mut rows: Vec<ComplianceExceptionEntry> = {
    let guard = exceptions.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.values().cloned().collect()
  };
  rows.sort_by(|a, b| {
    a.ns
      .cmp(&b.ns)
      .then_with(|| b.created_ms.cmp(&a.created_ms))
      .then_with(|| a.exc_id.cmp(&b.exc_id))
  });
  write_json_atomic(
    runtime.compliance_exception_file().as_path(),
    &PersistedComplianceExceptionIndex {
      version: COMPLIANCE_EXCEPTION_INDEX_VERSION.to_string(),
      updated_ms: now_ms(),
      exceptions: rows,
    },
  )
}

fn load_compliance_report_store(runtime: &RuntimeConfig) -> Result<ComplianceReportStore> {
  let path = runtime.compliance_report_file();
  if !path.exists() {
    return Ok(ComplianceReportStore::default());
  }
  let bytes =
    fs::read(&path).with_context(|| format!("read compliance report index {}", path.display()))?;
  let persisted: PersistedComplianceReportIndex = serde_json::from_slice(&bytes)
    .with_context(|| format!("parse compliance report index {}", path.display()))?;
  if persisted.version != COMPLIANCE_REPORT_INDEX_VERSION {
    anyhow::bail!(
      "unsupported compliance report index version `{}` (expected `{}`)",
      persisted.version,
      COMPLIANCE_REPORT_INDEX_VERSION
    );
  }
  let mut by_key = HashMap::new();
  for mut row in persisted.reports {
    row.ns = normalize_namespace(row.ns).unwrap_or_else(|_| DEFAULT_NAMESPACE.to_string());
    row.channel = normalize_channel(row.channel).unwrap_or_else(|_| "prod".to_string());
    row.report_id = row.report_id.trim().to_string();
    if row.report_id.is_empty() {
      continue;
    }
    by_key.insert(
      compliance_report_key(
        row.ns.as_str(),
        row.channel.as_str(),
        row.report_id.as_str(),
      ),
      row,
    );
  }
  Ok(ComplianceReportStore { by_key })
}

fn save_compliance_report_store(
  reports: &Arc<RwLock<ComplianceReportStore>>,
  runtime: &RuntimeConfig,
) -> Result<()> {
  let mut rows: Vec<ComplianceReportEntry> = {
    let guard = reports.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.values().cloned().collect()
  };
  rows.sort_by(|a, b| {
    a.ns
      .cmp(&b.ns)
      .then_with(|| a.channel.cmp(&b.channel))
      .then_with(|| b.created_ms.cmp(&a.created_ms))
  });
  write_json_atomic(
    runtime.compliance_report_file().as_path(),
    &PersistedComplianceReportIndex {
      version: COMPLIANCE_REPORT_INDEX_VERSION.to_string(),
      updated_ms: now_ms(),
      reports: rows,
    },
  )
}

fn compliance_exception_is_active(entry: &ComplianceExceptionEntry, now: u128) -> bool {
  if entry.status != "active" {
    return false;
  }
  if now >= entry.expires_ms {
    return false;
  }
  entry.approved_by.len() >= entry.approvals_required as usize
}

fn has_active_compliance_exception(
  namespace: &str,
  channel: &str,
  target: &str,
  subject: Option<&str>,
) -> bool {
  let Ok(exceptions) = get_compliance_exception_global() else {
    return false;
  };
  let now = now_ms();
  let target = target.trim().to_ascii_lowercase();
  let subject = subject.map(str::trim).filter(|value| !value.is_empty());
  let guard = exceptions.read().unwrap_or_else(|e| e.into_inner());
  guard.by_key.values().any(|entry| {
    if entry.ns != namespace || entry.channel != channel || entry.target != target {
      return false;
    }
    if !compliance_exception_is_active(entry, now) {
      return false;
    }
    match (entry.subject_id.as_deref(), subject) {
      (None, _) => true,
      (Some("*"), _) => true,
      (Some(expected), Some(actual)) => expected == actual,
      (Some(_), None) => false,
    }
  })
}

fn normalize_sha_ref(raw: &str) -> Option<String> {
  let normalized = raw
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if normalized.is_empty() {
    None
  } else {
    Some(normalized)
  }
}

fn normalize_runtime_catalog_status(raw: Option<String>) -> String {
  let status = raw
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase())
    .unwrap_or_else(|| "candidate".to_string());
  match status.as_str() {
    "candidate" | "active" | "deprecated" | "revoked" => status,
    _ => "candidate".to_string(),
  }
}

fn runtime_catalog_upsert_impl(
  request: RuntimeCatalogUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let family = request.family.trim().to_ascii_lowercase();
  let version = request.version.trim().to_string();
  let platform_os = request
    .platform_os
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
    .unwrap_or_else(|| "linux".to_string());
  let platform_arch = request
    .platform_arch
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
    .unwrap_or_else(|| "x86_64".to_string());
  let exec_ref_id = request.exec_ref_id.trim().to_string();
  let sha256 =
    normalize_sha_ref(request.sha256.as_str()).context("runtime.catalog.upsert requires sha256")?;
  if family.is_empty() {
    anyhow::bail!("runtime.catalog.upsert requires family");
  }
  if version.is_empty() {
    anyhow::bail!("runtime.catalog.upsert requires version");
  }
  if exec_ref_id.is_empty() {
    anyhow::bail!("runtime.catalog.upsert requires exec_ref_id");
  }
  let status = normalize_runtime_catalog_status(request.status);
  let catalog = get_runtime_catalog_global()?;
  let key = runtime_catalog_key(
    namespace.as_str(),
    family.as_str(),
    version.as_str(),
    platform_os.as_str(),
    platform_arch.as_str(),
  );
  let created_ms = {
    let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&key)
      .map(|entry| entry.created_ms)
      .unwrap_or_else(now_ms)
  };
  let entry = RuntimeCatalogEntry {
    ns: namespace.clone(),
    family: family.clone(),
    name: request
      .name
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    version: version.clone(),
    platform_os: platform_os.clone(),
    platform_arch: platform_arch.clone(),
    exec_ref_id: exec_ref_id.clone(),
    sha256: sha256.clone(),
    sbom_ref_id: request
      .sbom_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    vuln_report_id: request
      .vuln_report_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    attestation_ref_id: request
      .attestation_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    status: status.clone(),
    created_ms,
    updated_ms: now_ms(),
  };
  {
    let mut guard = catalog.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(key, entry.clone());
  }
  save_runtime_catalog_store(&catalog, runtime)?;
  publish_supervisor_event(
    events,
    "runtime.catalog.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__runtime_catalog__")),
    Some(family.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "family": family,
      "version": version,
      "platform_os": platform_os,
      "platform_arch": platform_arch,
      "exec_ref_id": exec_ref_id,
      "sha256": sha256,
      "status": status,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "entry": entry,
  }))
}

fn runtime_catalog_list_impl(request: RuntimeCatalogListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let family_filter = request
    .family
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let os_filter = request
    .platform_os
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let arch_filter = request
    .platform_arch
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let limit = request.limit.unwrap_or(200).clamp(1, 2_000);
  let catalog = get_runtime_catalog_global()?;
  let mut rows: Vec<RuntimeCatalogEntry> = {
    let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        family_filter
          .as_deref()
          .map(|family| entry.family == family)
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|status| entry.status == status)
          .unwrap_or(true)
      })
      .filter(|entry| {
        os_filter
          .as_deref()
          .map(|platform_os| entry.platform_os == platform_os)
          .unwrap_or(true)
      })
      .filter(|entry| {
        arch_filter
          .as_deref()
          .map(|platform_arch| entry.platform_arch == platform_arch)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.family
      .cmp(&b.family)
      .then_with(|| a.version.cmp(&b.version))
      .then_with(|| a.platform_os.cmp(&b.platform_os))
      .then_with(|| a.platform_arch.cmp(&b.platform_arch))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows,
  }))
}

fn runtime_alias_set_impl(
  request: RuntimeAliasSetRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let family = request.family.trim().to_ascii_lowercase();
  let alias = request.alias.trim().to_ascii_lowercase();
  let version = request.version.trim().to_string();
  if family.is_empty() {
    anyhow::bail!("runtime.alias.set requires family");
  }
  if alias.is_empty() {
    anyhow::bail!("runtime.alias.set requires alias");
  }
  if version.is_empty() {
    anyhow::bail!("runtime.alias.set requires version");
  }
  let catalog = get_runtime_catalog_global()?;
  {
    let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
    let exists = guard
      .by_key
      .values()
      .any(|entry| entry.ns == namespace && entry.family == family && entry.version == version);
    if !exists {
      anyhow::bail!(
        "runtime.alias.set requires existing runtime catalog entry ns={} family={} version={}",
        namespace,
        family,
        version
      );
    }
  }
  let aliases = get_runtime_alias_global()?;
  let alias_key = runtime_alias_key(namespace.as_str(), family.as_str(), alias.as_str());
  let entry = RuntimeAliasEntry {
    ns: namespace.clone(),
    family: family.clone(),
    alias: alias.clone(),
    version: version.clone(),
    updated_ms: now_ms(),
  };
  {
    let mut guard = aliases.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(alias_key, entry.clone());
  }
  save_runtime_alias_store(&aliases, runtime)?;
  publish_supervisor_event(
    events,
    "runtime.alias.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__runtime_alias__")),
    Some(format!("{}:{}", family, alias)),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "family": family,
      "alias": alias,
      "version": version,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "alias": entry,
  }))
}

fn runtime_alias_list_impl(request: RuntimeAliasListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let family_filter = request
    .family
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let aliases = get_runtime_alias_global()?;
  let mut rows: Vec<RuntimeAliasEntry> = {
    let guard = aliases.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        family_filter
          .as_deref()
          .map(|family| entry.family == family)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.family
      .cmp(&b.family)
      .then_with(|| a.alias.cmp(&b.alias))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows,
  }))
}

fn runtime_alias_resolve_impl(
  request: RuntimeAliasResolveRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let family = request.family.trim().to_ascii_lowercase();
  let alias = request.alias.trim().to_ascii_lowercase();
  if family.is_empty() || alias.is_empty() {
    anyhow::bail!("runtime.alias.resolve requires family and alias");
  }
  let os_filter = request
    .platform_os
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let arch_filter = request
    .platform_arch
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);

  let aliases = get_runtime_alias_global()?;
  let alias_key = runtime_alias_key(namespace.as_str(), family.as_str(), alias.as_str());
  let alias_entry = {
    let guard = aliases.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.get(&alias_key).cloned().with_context(|| {
      format!(
        "runtime alias not found ns={} family={} alias={}",
        namespace, family, alias
      )
    })?
  };

  let catalog = get_runtime_catalog_global()?;
  let runtime_entry = {
    let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
    let mut candidates: Vec<RuntimeCatalogEntry> = guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace && entry.family == family && entry.version == alias_entry.version
      })
      .filter(|entry| {
        os_filter
          .as_deref()
          .map(|platform_os| entry.platform_os == platform_os)
          .unwrap_or(true)
      })
      .filter(|entry| {
        arch_filter
          .as_deref()
          .map(|platform_arch| entry.platform_arch == platform_arch)
          .unwrap_or(true)
      })
      .cloned()
      .collect();
    candidates.sort_by(|a, b| {
      b.status
        .eq("active")
        .cmp(&a.status.eq("active"))
        .then_with(|| b.updated_ms.cmp(&a.updated_ms))
    });
    candidates.into_iter().next().with_context(|| {
      format!(
        "runtime catalog entry not found for ns={} family={} version={}",
        namespace, family, alias_entry.version
      )
    })?
  };
  Ok(json!({
    "ns": namespace,
    "alias": alias_entry,
    "runtime": runtime_entry,
  }))
}

fn resolve_runtime_sha(namespace: &str, runtime_ref_or_sha: &str) -> Option<String> {
  let runtime_ref_or_sha = runtime_ref_or_sha.trim();
  if runtime_ref_or_sha.is_empty() {
    return None;
  }
  let normalized = normalize_sha_ref(runtime_ref_or_sha);
  let Ok(catalog) = get_runtime_catalog_global() else {
    return normalized;
  };
  let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
  guard
    .by_key
    .values()
    .find(|entry| {
      entry.ns == namespace
        && (entry.exec_ref_id == runtime_ref_or_sha
          || normalized
            .as_deref()
            .map(|sha| entry.sha256 == sha)
            .unwrap_or(false))
    })
    .map(|entry| entry.sha256.clone())
    .or(normalized)
}

fn normalize_input_ref_ids(inputs: &[String]) -> Vec<String> {
  let mut normalized = inputs
    .iter()
    .filter_map(|value| normalize_sha_ref(value))
    .collect::<Vec<_>>();
  normalized.sort();
  normalized.dedup();
  normalized
}

fn security_compose_verdict_impl(
  request: SecurityComposeVerdictRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let runtime_ref_id = request.runtime_ref_id.trim();
  if runtime_ref_id.is_empty() {
    anyhow::bail!("security.compose_verdict requires runtime_ref_id");
  }
  let inputs = normalize_input_ref_ids(&request.inputs);
  let app_sha256 = inputs
    .first()
    .cloned()
    .context("security.compose_verdict requires at least one input artifact")?;
  let runtime_sha256 =
    resolve_runtime_sha(namespace.as_str(), runtime_ref_id).with_context(|| {
      format!(
        "security.compose_verdict cannot resolve runtime sha from runtime_ref_id={}",
        runtime_ref_id
      )
    })?;
  let runtime_attested = has_valid_exec_attestation(namespace.as_str(), runtime_ref_id);
  let status = if runtime_attested { "pass" } else { "fail" }.to_string();
  let verdict = ComposedVerdictEntry {
    ns: namespace.clone(),
    verdict_id: next_composed_verdict_id(),
    created_ms: now_ms(),
    runtime_sha256: runtime_sha256.clone(),
    app_sha256: app_sha256.clone(),
    inputs_sha256s: inputs.clone(),
    policy_id: request
      .policy_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .unwrap_or("default")
      .to_string(),
    status: status.clone(),
    summary_json: json!({
      "runtime_attested": runtime_attested,
      "runtime_sha256": runtime_sha256,
      "app_sha256": app_sha256,
      "inputs_count": inputs.len(),
    }),
    report_json: json!({
      "runtime_ref_id": runtime_ref_id,
      "runtime_attested": runtime_attested,
      "inputs_sha256s": inputs,
    }),
  };
  let verdicts = get_composed_verdict_global()?;
  {
    let mut guard = verdicts.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      composed_verdict_key(namespace.as_str(), verdict.verdict_id.as_str()),
      verdict.clone(),
    );
  }
  save_composed_verdict_store(&verdicts, runtime)?;
  publish_supervisor_event(
    events,
    "security.compose_verdict.completed",
    if status == "pass" { "info" } else { "warn" },
    Some(scoped_logical_id(namespace.as_str(), "__security__")),
    Some(verdict.verdict_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "status": status,
      "runtime_sha256": verdict.runtime_sha256,
      "app_sha256": verdict.app_sha256,
      "inputs_count": verdict.inputs_sha256s.len(),
    }),
  );
  Ok(json!({
    "ns": namespace,
    "verdict": verdict,
  }))
}

fn security_verdict_get_impl(request: SecurityVerdictGetRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let verdict_id = request.verdict_id.trim();
  if verdict_id.is_empty() {
    anyhow::bail!("security.verdict.get requires verdict_id");
  }
  let verdicts = get_composed_verdict_global()?;
  let key = composed_verdict_key(namespace.as_str(), verdict_id);
  let guard = verdicts.read().unwrap_or_else(|e| e.into_inner());
  let verdict = guard.by_key.get(&key).cloned();
  Ok(json!({
    "ns": namespace,
    "verdict": verdict,
    "exists": verdict.is_some(),
  }))
}

fn security_verdict_lookup_impl(
  request: SecurityVerdictLookupRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let runtime_sha = normalize_sha_ref(request.runtime_sha256.as_str())
    .context("security.verdict.lookup requires runtime_sha256")?;
  let app_sha = normalize_sha_ref(request.app_sha256.as_str())
    .context("security.verdict.lookup requires app_sha256")?;
  let limit = request.limit.unwrap_or(20).clamp(1, 200);
  let verdicts = get_composed_verdict_global()?;
  let mut rows: Vec<ComposedVerdictEntry> = {
    let guard = verdicts.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace && entry.runtime_sha256 == runtime_sha && entry.app_sha256 == app_sha
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| b.created_ms.cmp(&a.created_ms));
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "runtime_sha256": runtime_sha,
    "app_sha256": app_sha,
    "count": rows.len(),
    "items": rows,
  }))
}

fn normalize_service_name(raw: String) -> Result<String> {
  let trimmed = raw.trim();
  if trimmed.is_empty() {
    anyhow::bail!("service_name cannot be empty");
  }
  if trimmed.len() > 128 {
    anyhow::bail!("service_name is too long (max 128 chars)");
  }
  if !trimmed
    .chars()
    .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
  {
    anyhow::bail!("service_name contains unsupported characters");
  }
  Ok(trimmed.to_string())
}

