fn validate_params_schema(params_schema: Option<&Value>, params: &Value) -> Result<Vec<Value>> {
  let mut diagnostics: Vec<Value> = Vec::new();
  let Some(schema_obj) = params_schema.and_then(Value::as_object) else {
    return Ok(diagnostics);
  };
  let params_obj = params
    .as_object()
    .context("service params must be a JSON object")?;

  let required: Vec<String> = schema_obj
    .get("required")
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter_map(Value::as_str)
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  for key in required {
    if !params_obj.contains_key(key.as_str()) {
      diagnostics.push(json!({
        "level": "error",
        "code": "PARAM_REQUIRED_MISSING",
        "path": format!("params.{}", key),
        "message": format!("required param `{}` is missing", key),
      }));
    }
  }

  let properties = schema_obj
    .get("properties")
    .and_then(Value::as_object)
    .cloned()
    .unwrap_or_default();
  for (key, value) in params_obj {
    let Some(prop_schema) = properties.get(key) else {
      continue;
    };
    if let Some(expected_type) = prop_schema.get("type").and_then(Value::as_str) {
      let type_ok = match expected_type {
        "string" => value.is_string(),
        "integer" => value.as_i64().is_some() || value.as_u64().is_some(),
        "number" => value.is_number(),
        "boolean" => value.is_boolean(),
        "object" => value.is_object(),
        "array" => value.is_array(),
        _ => true,
      };
      if !type_ok {
        diagnostics.push(json!({
          "level": "error",
          "code": "PARAM_TYPE_MISMATCH",
          "path": format!("params.{}", key),
          "message": format!("param `{}` must be `{}`", key, expected_type),
        }));
      }
    }
    if let Some(allowed) = prop_schema.get("enum").and_then(Value::as_array) {
      if !allowed.iter().any(|candidate| candidate == value) {
        diagnostics.push(json!({
          "level": "error",
          "code": "PARAM_ENUM_MISMATCH",
          "path": format!("params.{}", key),
          "message": format!("param `{}` is not in enum", key),
        }));
      }
    }
  }
  Ok(diagnostics)
}

fn resolve_runtime_catalog_entry(
  namespace: &str,
  family: &str,
  alias: &str,
) -> Option<RuntimeCatalogEntry> {
  let aliases = get_runtime_alias_global().ok()?;
  let alias_key = runtime_alias_key(namespace, family, alias);
  let alias_entry = {
    let guard = aliases.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.get(&alias_key).cloned()?
  };
  let catalog = get_runtime_catalog_global().ok()?;
  let mut rows: Vec<RuntimeCatalogEntry> = {
    let guard = catalog.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace
          && entry.family == family
          && entry.version == alias_entry.version
          && matches!(entry.status.as_str(), "active" | "candidate" | "approved")
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| b.updated_ms.cmp(&a.updated_ms));
  rows.into_iter().next()
}

fn merge_patch(base: &Value, patch: &Value) -> Value {
  match (base, patch) {
    (Value::Object(base_obj), Value::Object(patch_obj)) => {
      let mut merged = base_obj.clone();
      for (key, value) in patch_obj {
        let next = if let Some(existing) = merged.get(key) {
          merge_patch(existing, value)
        } else {
          value.clone()
        };
        merged.insert(key.clone(), next);
      }
      Value::Object(merged)
    }
    (_, value) => value.clone(),
  }
}

fn build_render_result(
  namespace: &str,
  service_name: &str,
  channel: &str,
  blueprint: &BlueprintBundleEntry,
  params: &Value,
) -> Result<(Value, DesiredApplyRequest, Vec<Value>, String)> {
  let params_obj = params
    .as_object()
    .context("service render requires params object")?;
  let replicas = params_obj
    .get("replicas")
    .and_then(Value::as_u64)
    .unwrap_or(1)
    .clamp(1, 64);
  let base_port = params_obj.get("port").and_then(Value::as_u64).unwrap_or(0);
  let runtime_family = params_obj
    .get("runtime_family")
    .and_then(Value::as_str)
    .unwrap_or("jvm")
    .trim()
    .to_ascii_lowercase();
  let runtime_alias = params_obj
    .get("runtime_alias")
    .and_then(Value::as_str)
    .unwrap_or("stable")
    .trim()
    .to_ascii_lowercase();
  let app_ref_id = params_obj
    .get("app_ref_id")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let mut diagnostics =
    validate_params_schema(blueprint.manifest_json.get("params_schema"), params)?;
  let runtime_entry =
    resolve_runtime_catalog_entry(namespace, runtime_family.as_str(), runtime_alias.as_str());
  if runtime_entry.is_none() {
    diagnostics.push(json!({
      "level": "warn",
      "code": "RUNTIME_ALIAS_UNRESOLVED",
      "path": "params.runtime_alias",
      "message": format!(
        "runtime alias `{}` for family `{}` was not resolved in namespace `{}`",
        runtime_alias, runtime_family, namespace
      ),
    }));
  }
  let runtime_exec_ref = runtime_entry
    .as_ref()
    .map(|entry| entry.exec_ref_id.clone())
    .or_else(|| {
      params_obj
        .get("runtime_exec_ref_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
    })
    .context("service render requires resolvable runtime exec_ref_id")?;
  if app_ref_id.is_none() {
    diagnostics.push(json!({
      "level": "warn",
      "code": "APP_REF_MISSING",
      "path": "params.app_ref_id",
      "message": "app_ref_id is not provided; process will start without app input mount",
    }));
  }

  let mut desired: Vec<DesiredProcess> = Vec::new();
  for idx in 0..replicas {
    let local_id = if replicas == 1 {
      service_name.to_string()
    } else {
      format!("{}-{}", service_name, idx + 1)
    };
    let port = if base_port == 0 {
      0
    } else {
      base_port.saturating_add(idx)
    };
    let mut exec = json!({
      "kind": "artifact",
      "exec_ref_id": runtime_exec_ref,
      "args": ["-jar", "/inputs/app/app.jar", "--port", "${PORT}"],
    });
    if let Some(ref_id) = app_ref_id.as_ref() {
      exec["inputs"] = json!([
        {
          "ref_id": ref_id,
          "mount": "/inputs/app/app.jar",
          "mode": "file",
          "readonly": true
        }
      ]);
    }
    let spec = json!({
      "id": local_id,
      "exec": exec,
      "http": {
        "host": "127.0.0.1",
        "port": port,
        "argv_flag": "--port"
      },
      "logs": {"capture": true},
      "reconcile": {"drift":"restart","grace_ms":1500},
      "env": {
        "PORT": if port == 0 { "0".to_string() } else { port.to_string() }
      },
    });
    let mut labels = HashMap::new();
    labels.insert("service".to_string(), service_name.to_string());
    labels.insert("channel".to_string(), channel.to_string());
    labels.insert("blueprint".to_string(), blueprint.name.clone());
    desired.push(DesiredProcess {
      id: local_id,
      present: true,
      spec,
      policy: DesiredPolicy::default(),
      owner: None,
      depends_on: Vec::new(),
      labels,
    });
  }

  let desired_patch = json!({
    "ns": namespace,
    "apply_mode": "merge",
    "desired": desired,
  });
  let params_hash = sha256_hex(params).trim_start_matches("sha256:").to_string();
  let render_rev = sha256_hex(&json!({
    "blueprint_bundle_id": blueprint.bundle_id,
    "service_name": service_name,
    "channel": channel,
    "params": params,
  }));
  let result = json!({
    "schema": "pnix-render-result@0.1",
    "ns": namespace,
    "service_name": service_name,
    "channel": channel,
    "blueprint": {
      "name": blueprint.name,
      "bundle_id": blueprint.bundle_id,
      "version": blueprint.version,
    },
    "desired_patch": desired_patch,
    "meta": {
      "render_rev": render_rev,
      "runtime_alias_used": runtime_alias,
      "inputs": app_ref_id.clone().map(|value| vec![value]).unwrap_or_default(),
    },
    "diagnostics": diagnostics,
  });
  let apply_request: DesiredApplyRequest = serde_json::from_value(
    result
      .get("desired_patch")
      .cloned()
      .unwrap_or_else(|| json!({ "desired": [] })),
  )?;
  Ok((result, apply_request, diagnostics, params_hash))
}

fn desired_preview_impl(
  mut request: DesiredApplyRequest,
  default_namespace: &str,
  reconciler: &ReconcilerHandle,
  breakglass: bool,
) -> Result<Value> {
  let namespace = normalize_namespace(
    request
      .ns
      .take()
      .unwrap_or_else(|| default_namespace.to_string()),
  )?;
  let owner_default = request.owner.clone();
  let mode = request
    .apply_mode
    .unwrap_or_else(|| "merge".to_string())
    .trim()
    .to_ascii_lowercase();
  if mode != "merge" && mode != "replace" {
    anyhow::bail!("desired.apply apply_mode must be `merge` or `replace`");
  }

  let desired_guard = reconciler.desired.read().unwrap_or_else(|e| e.into_inner());
  let mut applied: Vec<String> = Vec::new();
  let mut changed: Vec<String> = Vec::new();
  let mut removed: Vec<String> = Vec::new();
  let mut action_plan: Vec<Value> = Vec::new();
  let mut incoming_ids: HashSet<String> = HashSet::new();
  let mut diagnostics: Vec<Value> = Vec::new();

  for process in request.desired.iter_mut() {
    let local_id = process.id.trim().to_string();
    if local_id.is_empty() {
      anyhow::bail!("desired.apply includes empty id");
    }
    let scoped_id = scoped_id_for_request(namespace.as_str(), local_id.as_str());
    process.id = scoped_id.clone();
    process.spec = ensure_spec_id(process.spec.clone(), scoped_id.as_str())?;
    let parsed_spec = parse_spec(&process.spec)
      .with_context(|| format!("desired.apply invalid spec for id `{}`", process.id))?;
    if let Err(error) = enforce_exec_compliance(&parsed_spec, breakglass) {
      diagnostics.push(json!({
        "level": "error",
        "code": "COMPLIANCE_DENY",
        "id": local_id,
        "message": error.to_string(),
      }));
    }
    if process.owner.is_none() {
      process.owner = owner_default.clone();
    }
    incoming_ids.insert(scoped_id.clone());
    applied.push(local_id.clone());
    let changed_now = desired_guard
      .by_id
      .get(&scoped_id)
      .map(|existing| existing.spec != process.spec || existing.present != process.present)
      .unwrap_or(true);
    if changed_now {
      changed.push(local_id.clone());
      action_plan.push(json!({
        "id": local_id,
        "action": "ensure",
        "reason": if desired_guard.by_id.contains_key(&scoped_id) { "spec_changed" } else { "new_desired" },
      }));
    }
  }

  if mode == "replace" {
    let namespace_prefix = scoped_prefix(namespace.as_str(), "");
    for stale_id in desired_guard
      .by_id
      .keys()
      .filter(|id| id.starts_with(namespace_prefix.as_str()))
      .filter(|id| !incoming_ids.contains(*id))
    {
      let (_, local_id) = split_scoped_logical_id(stale_id.as_str());
      removed.push(local_id.clone());
      action_plan.push(json!({
        "id": local_id,
        "action": "delete",
        "reason": "replace_mode_removed",
      }));
    }
  }

  Ok(json!({
    "ns": namespace,
    "apply_mode": mode,
    "applied": applied,
    "changed": changed,
    "removed": removed,
    "diagnostics": diagnostics,
    "action_plan": action_plan,
    "conflicts": [],
  }))
}

fn blueprint_bundle_publish_impl(
  request: BlueprintBundlePublishRequest,
  namespace: &str,
  _token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let name = request.name.trim().to_string();
  let version = request.version.trim().to_string();
  let bundle_ref_id = request.bundle_ref_id.trim().to_string();
  let sha256 = normalize_sha_ref(request.sha256.as_str())
    .context("blueprint.bundle.publish requires sha256")?;
  if name.is_empty() {
    anyhow::bail!("blueprint.bundle.publish requires name");
  }
  if version.is_empty() {
    anyhow::bail!("blueprint.bundle.publish requires version");
  }
  if bundle_ref_id.is_empty() {
    anyhow::bail!("blueprint.bundle.publish requires bundle_ref_id");
  }
  let status = normalize_blueprint_bundle_status(request.status);
  let entry = BlueprintBundleEntry {
    ns: namespace.clone(),
    bundle_id: next_blueprint_bundle_id(),
    name: name.clone(),
    version: version.clone(),
    created_ms: now_ms(),
    bundle_ref_id: bundle_ref_id.clone(),
    sha256: sha256.trim_start_matches("sha256:").to_string(),
    attestation_ref_id: request
      .attestation_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    status: status.clone(),
    manifest_json: request.manifest_json.unwrap_or_else(|| json!({})),
  };
  let bundles = get_blueprint_bundle_global()?;
  {
    let mut guard = bundles.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      blueprint_bundle_key(namespace.as_str(), entry.bundle_id.as_str()),
      entry.clone(),
    );
  }
  save_blueprint_bundle_store(&bundles, runtime)?;
  publish_supervisor_event(
    events,
    "blueprint.bundle.published",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__blueprint__")),
    Some(entry.bundle_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "name": name,
      "version": version,
      "bundle_id": entry.bundle_id,
      "status": status,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "bundle": blueprint_bundle_view(&entry),
  }))
}

fn blueprint_bundle_list_impl(
  request: BlueprintBundleListRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let limit = request.limit.unwrap_or(200).clamp(1, 2_000);
  let bundles = get_blueprint_bundle_global()?;
  let mut rows: Vec<BlueprintBundleEntry> = {
    let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|value| entry.name == value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|value| entry.status == value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| b.created_ms.cmp(&a.created_ms))
      .then_with(|| a.version.cmp(&b.version))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(blueprint_bundle_view).collect::<Vec<_>>(),
  }))
}

fn blueprint_bundle_get_impl(
  request: BlueprintBundleByIdRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let bundle_id = request.bundle_id.trim();
  if bundle_id.is_empty() {
    anyhow::bail!("blueprint.bundle.get requires bundle_id");
  }
  let bundles = get_blueprint_bundle_global()?;
  let key = blueprint_bundle_key(namespace.as_str(), bundle_id);
  let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
  let bundle = guard.by_key.get(&key).cloned();
  Ok(json!({
    "ns": namespace,
    "bundle_id": bundle_id,
    "exists": bundle.is_some(),
    "bundle": bundle.as_ref().map(blueprint_bundle_view),
  }))
}

fn blueprint_bundle_set_status_impl(
  request: BlueprintBundleByIdRequest,
  namespace: &str,
  status: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let bundle_id = request.bundle_id.trim();
  if bundle_id.is_empty() {
    anyhow::bail!("blueprint bundle id is required");
  }
  let bundles = get_blueprint_bundle_global()?;
  let key = blueprint_bundle_key(namespace.as_str(), bundle_id);
  let updated = {
    let mut guard = bundles.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("blueprint bundle `{}` not found", bundle_id))?;
    entry.status = status.to_string();
    entry.clone()
  };
  save_blueprint_bundle_store(&bundles, runtime)?;
  publish_supervisor_event(
    events,
    if status == "revoked" {
      "blueprint.bundle.revoked"
    } else {
      "blueprint.bundle.approved"
    },
    if status == "revoked" { "warn" } else { "info" },
    Some(scoped_logical_id(namespace.as_str(), "__blueprint__")),
    Some(updated.bundle_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "bundle_id": updated.bundle_id,
      "status": status,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "bundle": blueprint_bundle_view(&updated),
  }))
}

fn blueprint_bundle_approve_impl(
  request: BlueprintBundleByIdRequest,
  namespace: &str,
  _token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  blueprint_bundle_set_status_impl(request, namespace, "approved", runtime, events)
}

fn blueprint_bundle_revoke_impl(
  request: BlueprintBundleByIdRequest,
  namespace: &str,
  _token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  blueprint_bundle_set_status_impl(request, namespace, "revoked", runtime, events)
}

fn latest_blueprint_bundle_for_name(
  namespace: &str,
  blueprint_name: &str,
) -> Result<BlueprintBundleEntry> {
  let bundles = get_blueprint_bundle_global()?;
  let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
  guard
    .by_key
    .values()
    .filter(|entry| entry.ns == namespace && entry.name == blueprint_name)
    .filter(|entry| entry.status != "revoked")
    .max_by(|a, b| a.created_ms.cmp(&b.created_ms))
    .cloned()
    .with_context(|| {
      format!(
        "blueprint bundle not found for ns={} blueprint_name={}",
        namespace, blueprint_name
      )
    })
}

fn resolve_service_blueprint_bundle(
  namespace: &str,
  service: &ServiceInstanceEntry,
  preferred_bundle_id: Option<&str>,
) -> Result<BlueprintBundleEntry> {
  if let Some(bundle_id) = preferred_bundle_id {
    let bundles = get_blueprint_bundle_global()?;
    let key = blueprint_bundle_key(namespace, bundle_id);
    let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
    return guard
      .by_key
      .get(&key)
      .cloned()
      .with_context(|| format!("blueprint bundle `{}` not found", bundle_id));
  }
  if let Some(release_id) = service.active_release_id.as_deref() {
    let releases = get_service_release_global()?;
    let release = {
      let guard = releases.read().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .get(&service_release_key(namespace, release_id))
        .cloned()
    };
    if let Some(release) = release {
      let bundles = get_blueprint_bundle_global()?;
      let key = blueprint_bundle_key(namespace, release.blueprint_bundle_id.as_str());
      let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
      if let Some(bundle) = guard.by_key.get(&key) {
        return Ok(bundle.clone());
      }
    }
  }
  latest_blueprint_bundle_for_name(namespace, service.blueprint_name.as_str())
}

fn persist_rendered_result(
  namespace: &str,
  service_name: &str,
  channel: &str,
  blueprint_bundle_id: &str,
  params_hash: &str,
  render_json: Value,
  diagnostics: Value,
  runtime: &RuntimeConfig,
) -> Result<RenderedDesiredEntry> {
  let render_id = next_render_id();
  let entry = RenderedDesiredEntry {
    ns: namespace.to_string(),
    render_id: render_id.clone(),
    service_name: service_name.to_string(),
    channel: channel.to_string(),
    blueprint_bundle_id: blueprint_bundle_id.to_string(),
    params_hash: params_hash.to_string(),
    render_ref_id: format!("inline:{}", render_id),
    created_ms: now_ms(),
    status: "ok".to_string(),
    render_json,
    diagnostics_json: diagnostics,
  };
  let rendered = get_rendered_desired_global()?;
  {
    let mut guard = rendered.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      rendered_desired_key(namespace, entry.render_id.as_str()),
      entry.clone(),
    );
  }
  save_rendered_desired_store(&rendered, runtime)?;
  Ok(entry)
}

fn service_create_impl(
  request: ServiceCreateRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let blueprint_name = request.blueprint_name.trim().to_string();
  if blueprint_name.is_empty() {
    anyhow::bail!("service.create requires blueprint_name");
  }
  if !request.params.is_object() {
    anyhow::bail!("service.create requires params object");
  }
  let _bundle = latest_blueprint_bundle_for_name(namespace.as_str(), blueprint_name.as_str())?;
  let key = service_instance_key(namespace.as_str(), service_name.as_str(), channel.as_str());
  let services = get_service_instance_global()?;
  {
    let mut guard = services.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.contains_key(&key) {
      anyhow::bail!(
        "service instance already exists ns={} service_name={} channel={}",
        namespace,
        service_name,
        channel
      );
    }
    guard.by_key.insert(
      key,
      ServiceInstanceEntry {
        ns: namespace.clone(),
        service_id: next_service_id(),
        service_name: service_name.clone(),
        channel: channel.clone(),
        blueprint_name: blueprint_name.clone(),
        active_release_id: None,
        params_json: request.params.clone(),
        overrides_json: request.overrides.clone(),
        created_ms: now_ms(),
        updated_ms: now_ms(),
        status: "active".to_string(),
        last_error: None,
      },
    );
  }
  save_service_instance_store(&services, runtime)?;
  publish_supervisor_event(
    events,
    "service.created",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__service__")),
    Some(service_name.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "service_name": service_name,
      "channel": channel,
      "blueprint_name": blueprint_name,
    }),
  );
  service_get_impl(
    ServiceGetRequest {
      ns: Some(namespace),
      service_name,
      channel: Some(channel),
    },
    DEFAULT_NAMESPACE,
  )
}

fn service_update_params_impl(
  request: ServiceUpdateParamsRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let services = get_service_instance_global()?;
  let key = service_instance_key(namespace.as_str(), service_name.as_str(), channel.as_str());
  let updated = {
    let mut guard = services.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("service `{}` not found", service_name))?;
    let next_params = if let Some(params) = request.params {
      if !params.is_object() {
        anyhow::bail!("service.update_params params must be object");
      }
      params
    } else if let Some(patch) = request.params_patch {
      if !patch.is_object() {
        anyhow::bail!("service.update_params params_patch must be object");
      }
      merge_patch(&entry.params_json, &patch)
    } else {
      anyhow::bail!("service.update_params requires params or params_patch");
    };
    entry.params_json = next_params;
    entry.updated_ms = now_ms();
    entry.status = "updating".to_string();
    entry.last_error = None;
    entry.clone()
  };
  save_service_instance_store(&services, runtime)?;
  publish_supervisor_event(
    events,
    "service.params.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__service__")),
    Some(service_name.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "service_name": service_name,
      "channel": channel,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "service": service_instance_view(&updated),
  }))
}

fn service_get_impl(request: ServiceGetRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let key = service_instance_key(namespace.as_str(), service_name.as_str(), channel.as_str());
  let services = get_service_instance_global()?;
  let service = {
    let guard = services.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.get(&key).cloned()
  };
  let releases = get_service_release_global()?;
  let active_release = service
    .as_ref()
    .and_then(|entry| entry.active_release_id.as_ref())
    .and_then(|release_id| {
      let guard = releases.read().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .get(&service_release_key(
          namespace.as_str(),
          release_id.as_str(),
        ))
        .cloned()
    });
  let rendered = get_rendered_desired_global()?;
  let latest_render = {
    let guard = rendered.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace && entry.service_name == service_name && entry.channel == channel
      })
      .max_by(|a, b| a.created_ms.cmp(&b.created_ms))
      .cloned()
  };
  Ok(json!({
    "ns": namespace,
    "service_name": service_name,
    "channel": channel,
    "exists": service.is_some(),
    "service": service.as_ref().map(service_instance_view),
    "active_release": active_release.as_ref().map(service_release_view),
    "latest_render": latest_render.as_ref().map(rendered_desired_view),
  }))
}

fn service_list_impl(request: ServiceListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let channel_filter = request.channel.map(normalize_channel).transpose()?;
  let blueprint_filter = request
    .blueprint_name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let limit = request.limit.unwrap_or(200).clamp(1, 2_000);
  let services = get_service_instance_global()?;
  let mut rows: Vec<ServiceInstanceEntry> = {
    let guard = services.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        channel_filter
          .as_deref()
          .map(|value| &entry.channel == value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        blueprint_filter
          .as_deref()
          .map(|value| &entry.blueprint_name == value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|value| &entry.status == value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.service_name
      .cmp(&b.service_name)
      .then_with(|| a.channel.cmp(&b.channel))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(service_instance_view).collect::<Vec<_>>(),
  }))
}

fn service_release_create_impl(
  request: ServiceReleaseCreateRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let blueprint_bundle_id = request.blueprint_bundle_id.trim().to_string();
  if blueprint_bundle_id.is_empty() {
    anyhow::bail!("service.release.create requires blueprint_bundle_id");
  }
  let bundles = get_blueprint_bundle_global()?;
  {
    let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
    let key = blueprint_bundle_key(namespace.as_str(), blueprint_bundle_id.as_str());
    let Some(bundle) = guard.by_key.get(&key) else {
      anyhow::bail!("blueprint bundle `{}` not found", blueprint_bundle_id);
    };
    if bundle.status == "revoked" {
      anyhow::bail!("blueprint bundle `{}` is revoked", blueprint_bundle_id);
    }
  }
  let services = get_service_instance_global()?;
  {
    let guard = services.read().unwrap_or_else(|e| e.into_inner());
    let key = service_instance_key(namespace.as_str(), service_name.as_str(), channel.as_str());
    if !guard.by_key.contains_key(&key) {
      anyhow::bail!(
        "service.release.create requires existing service ns={} service_name={} channel={}",
        namespace,
        service_name,
        channel
      );
    }
  }
  let mut approved_by = Vec::new();
  if !token_id.trim().is_empty() {
    approved_by.push(token_id.to_string());
  }
  let release = ServiceReleaseEntry {
    ns: namespace.clone(),
    release_id: next_service_release_id(),
    service_name: service_name.clone(),
    channel: channel.clone(),
    blueprint_bundle_id: blueprint_bundle_id.clone(),
    created_ms: now_ms(),
    status: "candidate".to_string(),
    created_by_token_id: Some(token_id.to_string()),
    approved_by,
    notes: request.notes,
  };
  let releases = get_service_release_global()?;
  {
    let mut guard = releases.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      service_release_key(namespace.as_str(), release.release_id.as_str()),
      release.clone(),
    );
  }
  save_service_release_store(&releases, runtime)?;
  publish_supervisor_event(
    events,
    "service.release.created",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__service_release__")),
    Some(release.release_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "service_name": service_name,
      "channel": channel,
      "release_id": release.release_id,
      "blueprint_bundle_id": blueprint_bundle_id,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "release": service_release_view(&release),
  }))
}

fn service_release_approve_impl(
  request: ServiceReleaseByIdRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let release_id = request.release_id.trim();
  if release_id.is_empty() {
    anyhow::bail!("service.release.approve requires release_id");
  }
  let releases = get_service_release_global()?;
  let key = service_release_key(namespace.as_str(), release_id);
  let updated = {
    let mut guard = releases.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("release `{}` not found", release_id))?;
    if !entry.approved_by.iter().any(|who| who == token_id) {
      entry.approved_by.push(token_id.to_string());
    }
    entry.status = normalize_service_release_status(Some("approved".to_string()));
    entry.clone()
  };
  save_service_release_store(&releases, runtime)?;
  publish_supervisor_event(
    events,
    "service.release.approved",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__service_release__")),
    Some(updated.release_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "release_id": updated.release_id,
      "approved_by_count": updated.approved_by.len(),
    }),
  );
  Ok(json!({
    "ns": namespace,
    "release": service_release_view(&updated),
  }))
}

fn activate_service_release_internal(
  namespace: &str,
  release_id: &str,
  runtime: &RuntimeConfig,
  reconciler: &ReconcilerHandle,
  events: &Arc<SharedEvents>,
  breakglass: bool,
  rollback_from: Option<&str>,
) -> Result<Value> {
  let releases = get_service_release_global()?;
  let release_key = service_release_key(namespace, release_id);
  let release = {
    let guard = releases.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&release_key)
      .cloned()
      .with_context(|| format!("release `{}` not found", release_id))?
  };
  if !breakglass && !matches!(release.status.as_str(), "approved" | "active") {
    anyhow::bail!(
      "release `{}` is not approved (status={})",
      release.release_id,
      release.status
    );
  }
  let bundles = get_blueprint_bundle_global()?;
  let bundle = {
    let guard = bundles.read().unwrap_or_else(|e| e.into_inner());
    let key = blueprint_bundle_key(namespace, release.blueprint_bundle_id.as_str());
    guard.by_key.get(&key).cloned().with_context(|| {
      format!(
        "blueprint bundle `{}` not found",
        release.blueprint_bundle_id
      )
    })?
  };
  if bundle.status == "revoked" {
    anyhow::bail!(
      "cannot activate revoked blueprint bundle `{}`",
      bundle.bundle_id
    );
  }
  if release.channel == "prod"
    && !breakglass
    && !matches!(bundle.status.as_str(), "approved" | "active")
  {
    anyhow::bail!(
      "prod activation requires approved blueprint bundle (bundle_status={})",
      bundle.status
    );
  }
  let services = get_service_instance_global()?;
  let service_key = service_instance_key(
    namespace,
    release.service_name.as_str(),
    release.channel.as_str(),
  );
  let service = {
    let guard = services.read().unwrap_or_else(|e| e.into_inner());
    guard.by_key.get(&service_key).cloned().with_context(|| {
      format!(
        "service instance not found ns={} service_name={} channel={}",
        namespace, release.service_name, release.channel
      )
    })?
  };

  let (render_json, apply_request, diagnostics, params_hash) = build_render_result(
    namespace,
    service.service_name.as_str(),
    service.channel.as_str(),
    &bundle,
    &service.params_json,
  )?;
  let preview = desired_preview_impl(apply_request.clone(), namespace, reconciler, breakglass)?;
  let apply = desired_apply_impl(
    apply_request,
    namespace,
    reconciler,
    runtime,
    events,
    breakglass,
  )?;
  let render_entry = persist_rendered_result(
    namespace,
    service.service_name.as_str(),
    service.channel.as_str(),
    bundle.bundle_id.as_str(),
    params_hash.as_str(),
    render_json,
    json!(diagnostics),
    runtime,
  )?;

  let updated_release = {
    let mut guard = releases.write().unwrap_or_else(|e| e.into_inner());
    for item in guard.by_key.values_mut() {
      if item.ns == namespace
        && item.service_name == release.service_name
        && item.channel == release.channel
        && item.release_id != release.release_id
        && item.status == "active"
      {
        item.status = "rolled_back".to_string();
      }
    }
    if let Some(rollback_from) = rollback_from {
      let rollback_key = service_release_key(namespace, rollback_from);
      if let Some(item) = guard.by_key.get_mut(&rollback_key) {
        item.status = "rolled_back".to_string();
      }
    }
    let entry = guard.by_key.get_mut(&release_key).with_context(|| {
      format!(
        "release `{}` not found during activation",
        release.release_id
      )
    })?;
    entry.status = "active".to_string();
    entry.clone()
  };
  save_service_release_store(&releases, runtime)?;

  let updated_service = {
    let mut guard = services.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard.by_key.get_mut(&service_key).with_context(|| {
      format!(
        "service `{}` not found during activation",
        service.service_name
      )
    })?;
    entry.active_release_id = Some(updated_release.release_id.clone());
    entry.blueprint_name = bundle.name.clone();
    entry.updated_ms = now_ms();
    entry.status = "active".to_string();
    entry.last_error = None;
    entry.clone()
  };
  save_service_instance_store(&services, runtime)?;
  publish_supervisor_event(
    events,
    if rollback_from.is_some() {
      "service.release.rolled_back"
    } else {
      "service.release.activated"
    },
    "info",
    Some(scoped_logical_id(namespace, "__service_release__")),
    Some(updated_release.release_id.clone()),
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "service_name": updated_release.service_name,
      "channel": updated_release.channel,
      "release_id": updated_release.release_id,
      "blueprint_bundle_id": updated_release.blueprint_bundle_id,
      "rollback_from": rollback_from,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "release": service_release_view(&updated_release),
    "service": service_instance_view(&updated_service),
    "preview": preview,
    "apply": apply,
    "render": rendered_desired_view(&render_entry),
  }))
}

fn service_release_activate_impl(
  request: ServiceReleaseByIdRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  reconciler: &ReconcilerHandle,
  events: &Arc<SharedEvents>,
  breakglass: bool,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let release_id = request.release_id.trim().to_string();
  if release_id.is_empty() {
    anyhow::bail!("service.release.activate requires release_id");
  }
  activate_service_release_internal(
    namespace.as_str(),
    release_id.as_str(),
    runtime,
    reconciler,
    events,
    breakglass,
    None,
  )
}

fn service_release_rollback_impl(
  request: ServiceReleaseByIdRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  reconciler: &ReconcilerHandle,
  events: &Arc<SharedEvents>,
  breakglass: bool,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let current_release_id = request.release_id.trim().to_string();
  if current_release_id.is_empty() {
    anyhow::bail!("service.release.rollback requires release_id");
  }
  let releases = get_service_release_global()?;
  let current_key = service_release_key(namespace.as_str(), current_release_id.as_str());
  let current = {
    let guard = releases.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&current_key)
      .cloned()
      .with_context(|| format!("release `{}` not found", current_release_id))?
  };
  let target_release_id = {
    let guard = releases.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace
          && entry.service_name == current.service_name
          && entry.channel == current.channel
          && entry.release_id != current.release_id
          && entry.status != "rejected"
      })
      .max_by(|a, b| a.created_ms.cmp(&b.created_ms))
      .map(|entry| entry.release_id.clone())
      .with_context(|| {
        format!(
          "no rollback target release found for service={} channel={}",
          current.service_name, current.channel
        )
      })?
  };
  activate_service_release_internal(
    namespace.as_str(),
    target_release_id.as_str(),
    runtime,
    reconciler,
    events,
    breakglass,
    Some(current_release_id.as_str()),
  )
}

fn service_render_preview_impl(
  request: ServiceRenderPreviewRequest,
  namespace: &str,
  reconciler: &ReconcilerHandle,
  runtime: &RuntimeConfig,
  _events: &Arc<SharedEvents>,
  breakglass: bool,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let services = get_service_instance_global()?;
  let service_key =
    service_instance_key(namespace.as_str(), service_name.as_str(), channel.as_str());
  let service = {
    let guard = services.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&service_key)
      .cloned()
      .with_context(|| format!("service `{}` not found", service_name))?
  };
  let bundle = resolve_service_blueprint_bundle(
    namespace.as_str(),
    &service,
    request
      .blueprint_bundle_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty()),
  )?;
  let params = request
    .params
    .unwrap_or_else(|| service.params_json.clone());
  if !params.is_object() {
    anyhow::bail!("service.render.preview requires params object");
  }
  let (render_json, apply_request, diagnostics, params_hash) = build_render_result(
    namespace.as_str(),
    service_name.as_str(),
    channel.as_str(),
    &bundle,
    &params,
  )?;
  let preview = desired_preview_impl(apply_request, namespace.as_str(), reconciler, breakglass)?;
  let render_entry = persist_rendered_result(
    namespace.as_str(),
    service_name.as_str(),
    channel.as_str(),
    bundle.bundle_id.as_str(),
    params_hash.as_str(),
    render_json,
    json!(diagnostics),
    runtime,
  )?;
  let validate_only = request.validate_only.unwrap_or(true);
  let dry_run = request.dry_run.unwrap_or(true);
  let mut out = json!({
    "ns": namespace,
    "service_name": service_name,
    "channel": channel,
    "render": rendered_desired_view(&render_entry),
    "validate_only": validate_only,
    "dry_run": dry_run,
  });
  if let Some(obj) = out.as_object_mut() {
    if validate_only {
      obj.insert("validate".to_string(), preview.clone());
    }
    if dry_run {
      obj.insert("dry_run_result".to_string(), preview.clone());
    }
    if !validate_only && !dry_run {
      obj.insert("preview".to_string(), preview.clone());
    }
  }
  Ok(out)
}

fn service_render_get_latest_impl(
  request: ServiceRenderLatestRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = normalize_service_name(request.service_name)?;
  let channel = normalize_channel(request.channel.unwrap_or_else(|| "dev".to_string()))?;
  let rendered = get_rendered_desired_global()?;
  let latest = {
    let guard = rendered.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| {
        entry.ns == namespace && entry.service_name == service_name && entry.channel == channel
      })
      .max_by(|a, b| a.created_ms.cmp(&b.created_ms))
      .cloned()
  };
  Ok(json!({
    "ns": namespace,
    "service_name": service_name,
    "channel": channel,
    "exists": latest.is_some(),
    "render": latest.as_ref().map(rendered_desired_view),
  }))
}

