fn normalize_caps(caps: Option<Vec<String>>) -> Vec<String> {
  let mut normalized = caps
    .unwrap_or_default()
    .into_iter()
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty())
    .collect::<Vec<_>>();
  normalized.sort();
  normalized.dedup();
  normalized
}

fn node_hello_impl(
  request: NodeHelloRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let node_id = request.node_id.trim().to_string();
  if node_id.is_empty() {
    anyhow::bail!("node.hello requires node_id");
  }
  let now = now_ms();
  let lease_ms = request
    .lease_ms
    .unwrap_or(30_000)
    .clamp(1_000, 24 * 60 * 60 * 1000);
  let labels_json = request.labels_json.unwrap_or_else(|| json!({}));
  if !labels_json.is_object() {
    anyhow::bail!("node.hello labels_json must be an object");
  }
  let capacity_json = request.capacity_json.unwrap_or_else(|| json!({}));
  if !capacity_json.is_object() {
    anyhow::bail!("node.hello capacity_json must be an object");
  }
  let caps = normalize_caps(request.caps);
  let mut entry = NodeRegistryEntry {
    node_id: node_id.clone(),
    zone: request
      .zone
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    region: request
      .region
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    host: request
      .host
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    endpoint: request
      .endpoint
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    labels_json,
    caps,
    status: "ready".to_string(),
    last_seen_ms: now,
    lease_until_ms: now.saturating_add(lease_ms as u128),
    capacity_json,
    updated_ms: now,
  };
  if entry.host.is_none() {
    entry.host = Some(current_host_id());
  }
  let nodes = get_node_registry_global()?;
  {
    let mut guard = nodes.write().unwrap_or_else(|e| e.into_inner());
    if let Some(existing) = guard.by_id.get(node_id.as_str()) {
      if entry.zone.is_none() {
        entry.zone = existing.zone.clone();
      }
      if entry.region.is_none() {
        entry.region = existing.region.clone();
      }
      if entry.endpoint.is_none() {
        entry.endpoint = existing.endpoint.clone();
      }
      if entry.host.is_none() {
        entry.host = existing.host.clone();
      }
    }
    guard.by_id.insert(node_id.clone(), entry.clone());
  }
  save_node_registry_store(&nodes, runtime)?;
  publish_supervisor_event(
    events,
    "node.hello",
    "info",
    None,
    Some(node_id.clone()),
    None,
    None,
    None,
    json!({
      "node": node_view(&entry),
      "lease_ms": lease_ms,
    }),
  );
  Ok(json!({
    "node": node_view(&entry),
    "lease_ms": lease_ms,
  }))
}

fn node_heartbeat_impl(
  request: NodeHeartbeatRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let node_id = request.node_id.trim().to_string();
  if node_id.is_empty() {
    anyhow::bail!("node.heartbeat requires node_id");
  }
  let now = now_ms();
  let lease_ms = request
    .lease_ms
    .unwrap_or(30_000)
    .clamp(1_000, 24 * 60 * 60 * 1000);
  let nodes = get_node_registry_global()?;
  let updated = {
    let mut guard = nodes.write().unwrap_or_else(|e| e.into_inner());
    let mut entry = guard
      .by_id
      .get(node_id.as_str())
      .cloned()
      .unwrap_or(NodeRegistryEntry {
        node_id: node_id.clone(),
        zone: None,
        region: None,
        host: Some(current_host_id()),
        endpoint: None,
        labels_json: json!({}),
        caps: Vec::new(),
        status: "ready".to_string(),
        last_seen_ms: now,
        lease_until_ms: now.saturating_add(lease_ms as u128),
        capacity_json: json!({}),
        updated_ms: now,
      });
    if let Some(status) = request.status {
      entry.status = normalize_node_status(Some(status));
    }
    if let Some(zone) = request
      .zone
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      entry.zone = Some(zone);
    }
    if let Some(region) = request
      .region
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      entry.region = Some(region);
    }
    if let Some(host) = request
      .host
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      entry.host = Some(host);
    }
    if let Some(endpoint) = request
      .endpoint
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      entry.endpoint = Some(endpoint);
    }
    if let Some(labels_json) = request.labels_json {
      if !labels_json.is_object() {
        anyhow::bail!("node.heartbeat labels_json must be an object");
      }
      entry.labels_json = labels_json;
    }
    if let Some(capacity_json) = request.capacity_json {
      if !capacity_json.is_object() {
        anyhow::bail!("node.heartbeat capacity_json must be an object");
      }
      entry.capacity_json = capacity_json;
    }
    if request.caps.is_some() {
      entry.caps = normalize_caps(request.caps);
    }
    entry.last_seen_ms = now;
    entry.lease_until_ms = now.saturating_add(lease_ms as u128);
    entry.updated_ms = now;
    guard.by_id.insert(node_id.clone(), entry.clone());
    entry
  };
  save_node_registry_store(&nodes, runtime)?;
  publish_supervisor_event(
    events,
    "node.heartbeat",
    "info",
    None,
    Some(node_id),
    None,
    None,
    None,
    json!({
      "node": node_view(&updated),
      "lease_ms": lease_ms,
    }),
  );
  Ok(json!({
    "node": node_view(&updated),
    "lease_ms": lease_ms,
  }))
}

fn node_set_status_impl(
  request: NodeSetStatusRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let node_id = request.node_id.trim();
  if node_id.is_empty() {
    anyhow::bail!("node.set_status requires node_id");
  }
  let nodes = get_node_registry_global()?;
  let updated = {
    let mut guard = nodes.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_id
      .get_mut(node_id)
      .with_context(|| format!("node `{}` not found", node_id))?;
    entry.status = normalize_node_status(Some(request.status));
    entry.updated_ms = now_ms();
    entry.clone()
  };
  save_node_registry_store(&nodes, runtime)?;
  publish_supervisor_event(
    events,
    "node.status.changed",
    "warn",
    None,
    Some(node_id.to_string()),
    None,
    None,
    None,
    json!({
      "node": node_view(&updated),
    }),
  );
  Ok(json!({
    "node": node_view(&updated),
  }))
}

fn node_list_impl(request: NodeListRequest) -> Result<Value> {
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_node_status(Some(value.to_string())));
  let zone_filter = request
    .zone
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let nodes = get_node_registry_global()?;
  let mut rows: Vec<NodeRegistryEntry> = {
    let guard = nodes.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_id
      .values()
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|status| entry.status == status)
          .unwrap_or(true)
      })
      .filter(|entry| {
        zone_filter
          .as_deref()
          .map(|zone| entry.zone.as_deref() == Some(zone))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.last_seen_ms
      .cmp(&a.last_seen_ms)
      .then_with(|| a.node_id.cmp(&b.node_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "count": rows.len(),
    "items": rows.iter().map(node_view).collect::<Vec<_>>(),
  }))
}

fn normalize_fed_caps_json(raw: Option<Value>) -> Value {
  let mut caps = raw.unwrap_or_else(|| json!([]));
  if !caps.is_array() {
    return json!([]);
  }
  let mut values = caps
    .as_array_mut()
    .map(|items| {
      items
        .iter()
        .filter_map(|item| item.as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  values.sort();
  values.dedup();
  json!(values)
}

fn fed_spoke_register_impl(
  request: FedSpokeRegisterRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spoke_id = request.spoke_id.trim().to_string();
  if spoke_id.is_empty() {
    anyhow::bail!("federation.spoke.register requires spoke_id");
  }
  let region = request.region.trim().to_string();
  if region.is_empty() {
    anyhow::bail!("federation.spoke.register requires region");
  }
  let zone = request
    .zone
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let endpoint = request
    .endpoint
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let labels_json = request.labels_json.unwrap_or_else(|| json!({}));
  if !labels_json.is_object() {
    anyhow::bail!("federation.spoke.register labels_json must be an object");
  }
  let lease_ms = request
    .lease_ms
    .unwrap_or(30_000)
    .clamp(1_000, 24 * 60 * 60 * 1000);
  let now = now_ms();
  let entry = FedSpokeRegistryEntry {
    org: org.clone(),
    spoke_id: spoke_id.clone(),
    region,
    zone,
    endpoint,
    caps_json: normalize_fed_caps_json(request.caps_json),
    labels_json,
    status: normalize_fed_spoke_status(request.status),
    last_seen_ms: now,
    lease_until_ms: now.saturating_add(lease_ms as u128),
    updated_ms: now,
  };
  let store = get_fed_spoke_registry_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      fed_spoke_registry_key(org.as_str(), spoke_id.as_str()),
      entry.clone(),
    );
  }
  save_fed_spoke_registry_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "federation.spoke.registered",
    "info",
    None,
    Some(spoke_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "lease_ms": lease_ms,
      "spoke": fed_spoke_registry_view(&entry),
    }),
  );
  Ok(json!({
    "spoke": fed_spoke_registry_view(&entry),
    "lease_ms": lease_ms,
  }))
}

fn fed_spoke_heartbeat_impl(
  request: FedSpokeHeartbeatRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spoke_id = request.spoke_id.trim().to_string();
  if spoke_id.is_empty() {
    anyhow::bail!("federation.spoke.heartbeat requires spoke_id");
  }
  let lease_ms = request
    .lease_ms
    .unwrap_or(30_000)
    .clamp(1_000, 24 * 60 * 60 * 1000);
  let now = now_ms();
  let store = get_fed_spoke_registry_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let key = fed_spoke_registry_key(org.as_str(), spoke_id.as_str());
    let mut row = guard
      .by_key
      .get(&key)
      .cloned()
      .unwrap_or(FedSpokeRegistryEntry {
        org: org.clone(),
        spoke_id: spoke_id.clone(),
        region: request
          .region
          .as_deref()
          .map(str::trim)
          .filter(|value| !value.is_empty())
          .unwrap_or("unknown")
          .to_string(),
        zone: None,
        endpoint: None,
        caps_json: json!([]),
        labels_json: json!({}),
        status: "ready".to_string(),
        last_seen_ms: now,
        lease_until_ms: now.saturating_add(lease_ms as u128),
        updated_ms: now,
      });
    if let Some(region) = request
      .region
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      row.region = region;
    }
    if let Some(zone) = request
      .zone
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      row.zone = Some(zone);
    }
    if let Some(endpoint) = request
      .endpoint
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
    {
      row.endpoint = Some(endpoint);
    }
    if let Some(labels_json) = request.labels_json {
      if !labels_json.is_object() {
        anyhow::bail!("federation.spoke.heartbeat labels_json must be an object");
      }
      row.labels_json = labels_json;
    }
    if request.caps_json.is_some() {
      row.caps_json = normalize_fed_caps_json(request.caps_json);
    }
    if let Some(status) = request.status {
      row.status = normalize_fed_spoke_status(Some(status));
    }
    row.last_seen_ms = now;
    row.lease_until_ms = now.saturating_add(lease_ms as u128);
    row.updated_ms = now;
    guard.by_key.insert(key, row.clone());
    row
  };
  save_fed_spoke_registry_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "federation.spoke.heartbeat",
    "info",
    None,
    Some(spoke_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "lease_ms": lease_ms,
      "spoke": fed_spoke_registry_view(&entry),
    }),
  );
  Ok(json!({
    "spoke": fed_spoke_registry_view(&entry),
    "lease_ms": lease_ms,
  }))
}

