fn plugin_release_set_status_impl(
  request: PluginReleaseByIdRequest,
  status: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let plugin_id = request.plugin_id.trim().to_string();
  let release_id = request.release_id.trim().to_string();
  if plugin_id.is_empty() || release_id.is_empty() {
    anyhow::bail!("plugin.release operation requires plugin_id and release_id");
  }
  let store = get_plugin_release_global()?;
  let key = plugin_release_key(org.as_str(), plugin_id.as_str(), release_id.as_str());
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if status == "active" {
      for row in guard.by_key.values_mut() {
        if row.org == org && row.plugin_id == plugin_id && row.status == "active" {
          row.status = "approved".to_string();
          row.updated_ms = now_ms();
        }
      }
    }
    let row = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("plugin release `{}` not found", release_id))?;
    row.status = normalize_plugin_release_status(Some(status.to_string()));
    row.updated_ms = now_ms();
    row.clone()
  };
  save_plugin_release_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    if status == "active" {
      "plugin.release.activated"
    } else {
      "plugin.release.approved"
    },
    "info",
    None,
    Some(release_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "plugin_id": plugin_id,
      "release": plugin_release_view(&updated),
    }),
  );
  Ok(json!({
    "org": org,
    "release": plugin_release_view(&updated),
  }))
}

fn plugin_session_upsert_impl(
  request: PluginSessionUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let plugin_id = request.plugin_id.trim().to_string();
  let endpoint = request.endpoint.trim().to_string();
  if plugin_id.is_empty() || endpoint.is_empty() {
    anyhow::bail!("plugin.session.upsert requires plugin_id and endpoint");
  }
  let session_id = request
    .session_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_plugin_session_id);
  let metadata_json = request.metadata_json.unwrap_or_else(|| json!({}));
  if !metadata_json.is_object() {
    anyhow::bail!("plugin.session.upsert metadata_json must be an object");
  }
  let now = now_ms();
  let store = get_plugin_session_global()?;
  let row = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let mut row = guard
      .by_key
      .get(&plugin_session_key(org.as_str(), session_id.as_str()))
      .cloned()
      .unwrap_or(PluginSessionEntry {
        org: org.clone(),
        session_id: session_id.clone(),
        plugin_id: plugin_id.clone(),
        mode: normalize_plugin_mode(request.mode.clone()),
        endpoint: endpoint.clone(),
        status: normalize_plugin_session_status(request.status.clone()),
        last_seen_ms: now,
        last_error: None,
        metadata_json: json!({}),
      });
    row.plugin_id = plugin_id;
    row.mode = normalize_plugin_mode(request.mode);
    row.endpoint = endpoint;
    row.status = normalize_plugin_session_status(request.status);
    row.last_seen_ms = now;
    row.last_error = request
      .last_error
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    row.metadata_json = metadata_json;
    guard.by_key.insert(
      plugin_session_key(org.as_str(), session_id.as_str()),
      row.clone(),
    );
    row
  };
  save_plugin_session_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "plugin.session.upserted",
    "info",
    None,
    Some(session_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "session": plugin_session_view(&row),
    }),
  );
  Ok(json!({
    "org": org,
    "session": plugin_session_view(&row),
  }))
}

