fn plugin_plan_submit_impl(
  request: PluginPlanSubmitRequest,
  default_namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let plugin_name = request.plugin_name.trim().to_string();
  let plugin_version = request.plugin_version.trim().to_string();
  if plugin_name.is_empty() || plugin_version.is_empty() {
    anyhow::bail!("plugin.plan.submit requires plugin_name and plugin_version");
  }
  if !request.plan_json.is_object() {
    anyhow::bail!("plugin.plan.submit plan_json must be an object");
  }
  let namespace = request
    .ns
    .map(normalize_namespace)
    .transpose()?
    .unwrap_or_else(|| default_namespace.to_string());
  let channel = request
    .channel
    .map(normalize_channel)
    .transpose()?
    .map(|value| value.to_ascii_lowercase());
  let idempotency_key = request
    .idempotency_key
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let store = get_plugin_plan_global()?;
  if let Some(key) = idempotency_key.as_deref() {
    let existing = {
      let guard = store.read().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .values()
        .find(|entry| entry.org == org && entry.idempotency_key.as_deref() == Some(key))
        .cloned()
    };
    if let Some(existing) = existing {
      return Ok(json!({
        "org": org,
        "deduped": true,
        "plan": plugin_plan_view(&existing),
      }));
    }
  }
  let now = now_ms();
  let plan_id = request
    .plan_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_plugin_plan_id);
  let summary_json = request.summary_json.unwrap_or_else(|| json!({}));
  if !summary_json.is_object() {
    anyhow::bail!("plugin.plan.submit summary_json must be an object");
  }
  let sha256 = request
    .sha256
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.trim_start_matches("sha256:").to_ascii_lowercase())
    .unwrap_or_else(|| {
      sha256_hex(&request.plan_json)
        .trim_start_matches("sha256:")
        .to_string()
    });
  let plan_ref_id = request
    .plan_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "inline".to_string());
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let key = plugin_plan_key(org.as_str(), plan_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = PluginPlanEntry {
      org: org.clone(),
      plan_id: plan_id.clone(),
      plugin_name,
      plugin_version,
      created_ms,
      invocation_id: request
        .invocation_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      ns: Some(namespace),
      channel,
      plan_ref_id,
      sha256,
      idempotency_key,
      summary_json,
      plan_json: request.plan_json,
      status: normalize_plugin_plan_status(request.status),
      change_id: None,
      last_error: None,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_plugin_plan_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "plugin.plan.submitted",
    "info",
    None,
    Some(plan_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "plan": plugin_plan_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "deduped": false,
    "plan": plugin_plan_view(&entry),
  }))
}

