fn plugin_plan_list_impl(request: PluginPlanListRequest, default_namespace: &str) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let namespace = request
    .ns
    .map(normalize_namespace)
    .transpose()?
    .unwrap_or_else(|| default_namespace.to_string());
  let plugin_name_filter = request
    .plugin_name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let channel_filter = request
    .channel
    .map(normalize_channel)
    .transpose()?
    .map(|value| value.to_ascii_lowercase());
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_plugin_plan_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_plugin_plan_global()?;
  let mut rows: Vec<PluginPlanEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.org == org)
      .filter(|entry| entry.ns.as_deref() == Some(namespace.as_str()))
      .filter(|entry| {
        plugin_name_filter
          .as_deref()
          .map(|value| entry.plugin_name.to_ascii_lowercase().contains(value))
          .unwrap_or(true)
      })
      .filter(|entry| {
        channel_filter
          .as_deref()
          .map(|value| entry.channel.as_deref() == Some(value))
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.created_ms
      .cmp(&a.created_ms)
      .then_with(|| a.plan_id.cmp(&b.plan_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(plugin_plan_view).collect::<Vec<_>>(),
  }))
}

fn plugin_plan_effects_to_steps(plan_json: &Value, namespace: &str) -> Result<Vec<PlanStepEntry>> {
  let effects = plan_json
    .get("effects")
    .and_then(Value::as_array)
    .with_context(|| "plugin plan must contain effects[]")?;
  if effects.is_empty() {
    return Ok(vec![PlanStepEntry {
      step_no: 1,
      kind: "noop".to_string(),
      spec_json: json!({}),
      status: "pending".to_string(),
      started_ms: None,
      finished_ms: None,
      last_error: None,
    }]);
  }
  let mut steps = Vec::with_capacity(effects.len());
  for (idx, effect) in effects.iter().enumerate() {
    let effect_obj = effect
      .as_object()
      .with_context(|| format!("effect #{} must be object", idx + 1))?;
    let kind = effect_obj
      .get("kind")
      .and_then(Value::as_str)
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .with_context(|| format!("effect #{} missing kind", idx + 1))?
      .to_string();
    let params = effect_obj
      .get("params")
      .cloned()
      .unwrap_or_else(|| json!({}));
    let (step_kind, mut step_spec) = match kind.as_str() {
      "noop" => ("noop".to_string(), json!({})),
      "wait" | "builtin.wait" => {
        let ms = params
          .get("ms")
          .or_else(|| params.get("timeout_ms"))
          .and_then(Value::as_u64)
          .unwrap_or(1_000)
          .clamp(1, 300_000);
        ("wait".to_string(), json!({ "ms": ms }))
      }
      "reconcile.kick" => ("reconcile.kick".to_string(), params),
      "desired.apply" => ("desired.apply".to_string(), params),
      other => anyhow::bail!("unsupported effect kind `{}`", other),
    };
    if step_kind == "desired.apply" {
      if let Some(obj) = step_spec.as_object_mut() {
        if !obj.contains_key("ns") {
          obj.insert("ns".to_string(), json!(namespace));
        }
      }
    }
    steps.push(PlanStepEntry {
      step_no: (idx + 1) as u32,
      kind: step_kind,
      spec_json: step_spec,
      status: "pending".to_string(),
      started_ms: None,
      finished_ms: None,
      last_error: None,
    });
  }
  Ok(steps)
}

fn plugin_plan_execute_impl(
  request: PluginPlanExecuteRequest,
  default_namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  changes: &Arc<RwLock<ChangeRequestStore>>,
  job_store: &Arc<RwLock<JobStore>>,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let plan_id = request.plan_id.trim().to_string();
  if plan_id.is_empty() {
    anyhow::bail!("plugin.plan.execute requires plan_id");
  }
  let namespace = request
    .ns
    .map(normalize_namespace)
    .transpose()?
    .unwrap_or_else(|| default_namespace.to_string());
  let plan_store = get_plugin_plan_global()?;
  let mut plan = {
    let guard = plan_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&plugin_plan_key(org.as_str(), plan_id.as_str()))
      .cloned()
      .with_context(|| format!("plugin plan `{}` not found", plan_id))?
  };

  let channel = normalize_channel(plan.channel.clone().unwrap_or_else(|| "prod".to_string()))?;
  let validation = validate_effect_plan_json(&plan.plan_json);
  let analysis = analyze_effect_plan_json(&validation, channel.as_str());
  let analysis_entry = persist_plan_analysis(org.as_str(), plan_id.as_str(), &analysis, runtime)?;
  let analysis_denied = !validation.valid
    || analysis
      .get("status")
      .and_then(Value::as_str)
      .map(|value| value.eq_ignore_ascii_case("deny"))
      .unwrap_or(false);
  if analysis_denied {
    {
      let mut guard = plan_store.write().unwrap_or_else(|e| e.into_inner());
      if let Some(row) = guard
        .by_key
        .get_mut(&plugin_plan_key(org.as_str(), plan_id.as_str()))
      {
        row.status = "rejected".to_string();
        row.last_error = Some("plan analysis denied execution".to_string());
        row.updated_ms = now_ms();
        plan = row.clone();
      }
    }
    save_plugin_plan_store(&plan_store, runtime)?;
    return Ok(json!({
      "org": org,
      "admission": {
        "decision": "deny",
        "reasons": [{
          "code": "PLAN_ANALYSIS_DENY",
          "msg": "plan failed static analysis",
          "meta": {
            "status": analysis.get("status").cloned().unwrap_or(Value::Null)
          }
        }],
      },
      "analysis": analysis,
      "analysis_index": plan_analysis_view(&analysis_entry),
      "plan": plugin_plan_view(&plan),
      "executed": false,
    }));
  }
  let admission_out = admission_check_impl(
    AdmissionCheckRequest {
      ns: Some(namespace.clone()),
      channel: Some(channel),
      target: "plan.execute".to_string(),
      subject_kind: Some("plugin_plan".to_string()),
      subject_id: Some(plan.plan_id.clone()),
      subject: json!({
        "kind": "plugin_plan",
        "id": plan.plan_id,
        "plugin_name": plan.plugin_name,
        "plugin_version": plan.plugin_version,
      }),
      actor: json!({
        "token_id": token_id,
      }),
      desired: plan.summary_json.clone(),
      system: json!({
        "org": org,
      }),
      evidence: json!({
        "plan_sha256": plan.sha256,
        "plan_analysis": analysis.clone(),
      }),
      links: json!({
        "invocation_id": plan.invocation_id,
      }),
      policy_release_id: None,
      breakglass: None,
      process_spec: None,
    },
    namespace.as_str(),
    runtime,
  )?;
  let denied = admission_out
    .get("decision")
    .and_then(Value::as_str)
    .map(|value| value.eq_ignore_ascii_case("deny"))
    .unwrap_or(false);
  if denied {
    let reasons = admission_out
      .get("reasons")
      .cloned()
      .unwrap_or_else(|| json!([]));
    {
      let mut guard = plan_store.write().unwrap_or_else(|e| e.into_inner());
      if let Some(row) = guard
        .by_key
        .get_mut(&plugin_plan_key(org.as_str(), plan_id.as_str()))
      {
        row.status = "rejected".to_string();
        row.last_error = Some(format!("admission denied: {}", reasons));
        row.updated_ms = now_ms();
        plan = row.clone();
      }
    }
    save_plugin_plan_store(&plan_store, runtime)?;
    return Ok(json!({
      "org": org,
      "admission": admission_out,
      "analysis": analysis,
      "analysis_index": plan_analysis_view(&analysis_entry),
      "plan": plugin_plan_view(&plan),
      "executed": false,
    }));
  }

  let steps = plugin_plan_effects_to_steps(&plan.plan_json, namespace.as_str())?;
  let now = now_ms();
  let change_id = next_change_id();
  let change = ChangeRequestEntry {
    ns: namespace.clone(),
    change_id: change_id.clone(),
    created_ms: now,
    updated_ms: now,
    title: format!("Execute plugin plan {}", plan_id),
    reason: Some("plugin.plan.execute".to_string()),
    source: "plugin_plan".to_string(),
    risk: normalize_risk(request.risk.as_deref(), "medium"),
    status: "proposed".to_string(),
    policy_id: None,
    invocation_id: plan.invocation_id.clone(),
    session_id: None,
    plan_id: Some(plan_id.clone()),
    scheduled_start_ms: None,
    scheduled_end_ms: None,
    steps,
    approvals: Vec::new(),
    last_error: None,
  };
  {
    let mut guard = changes.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      change_request_key(namespace.as_str(), change_id.as_str()),
      change.clone(),
    );
  }
  save_change_request_store(changes, runtime)?;
  {
    let mut guard = plan_store.write().unwrap_or_else(|e| e.into_inner());
    if let Some(row) = guard
      .by_key
      .get_mut(&plugin_plan_key(org.as_str(), plan_id.as_str()))
    {
      row.status = "submitted".to_string();
      row.change_id = Some(change_id.clone());
      row.last_error = None;
      row.updated_ms = now_ms();
      plan = row.clone();
    }
  }
  save_plugin_plan_store(&plan_store, runtime)?;

  let run_result = if request.auto_run.unwrap_or(false) {
    Some(change_run_impl(
      ChangeByIdRequest {
        ns: Some(namespace.clone()),
        change_id: change_id.clone(),
      },
      namespace.as_str(),
      token_id,
      runtime,
      changes,
      job_store,
      events,
    )?)
  } else {
    None
  };
  if run_result.is_some() {
    let mut guard = plan_store.write().unwrap_or_else(|e| e.into_inner());
    if let Some(row) = guard
      .by_key
      .get_mut(&plugin_plan_key(org.as_str(), plan_id.as_str()))
    {
      row.status = "executed".to_string();
      row.updated_ms = now_ms();
      plan = row.clone();
    }
    drop(guard);
    save_plugin_plan_store(&plan_store, runtime)?;
  }
  publish_supervisor_event(
    events,
    "plugin.plan.executed",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__plugin_plan__")),
    Some(plan_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "change_id": change_id,
      "auto_run": request.auto_run.unwrap_or(false),
    }),
  );
  Ok(json!({
    "org": org,
    "admission": admission_out,
    "analysis": analysis,
    "analysis_index": plan_analysis_view(&analysis_entry),
    "plan": plugin_plan_view(&plan),
    "change": change_request_view(&change),
    "run": run_result,
    "executed": true,
  }))
}

fn contract_registry_upsert_impl(
  request: ContractRegistryUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let contract_id = request
    .contract_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_contract_id);
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let service_name = request.service_name.trim().to_string();
  if service_name.is_empty() {
    anyhow::bail!("contract.registry.upsert requires service_name");
  }
  let channel =
    normalize_channel(request.channel.unwrap_or_else(|| "prod".to_string()))?.to_ascii_lowercase();
  let kind = normalize_contract_kind(Some(request.kind));
  let version = request.version.trim().to_string();
  let ref_id = request.ref_id.trim().to_string();
  let sha256 = request
    .sha256
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if version.is_empty() || ref_id.is_empty() || sha256.is_empty() {
    anyhow::bail!("contract.registry.upsert requires version, ref_id, and sha256");
  }
  let contract_json = request.contract_json.unwrap_or_else(|| json!({}));
  if !contract_json.is_object() {
    anyhow::bail!("contract.registry.upsert contract_json must be an object");
  }
  let now = now_ms();
  let store = get_contract_registry_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let key = contract_registry_key(org.as_str(), contract_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = ContractRegistryEntry {
      org: org.clone(),
      contract_id: contract_id.clone(),
      ns: namespace.clone(),
      service_name,
      channel,
      kind,
      version,
      ref_id,
      sha256,
      contract_json,
      created_ms,
      updated_ms: now,
      status: normalize_contract_status(request.status),
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_contract_registry_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "contract.registry.upserted",
    "info",
    Some(scoped_logical_id(
      namespace.as_str(),
      entry.service_name.as_str(),
    )),
    Some(contract_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "contract": contract_registry_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "contract": contract_registry_view(&entry),
  }))
}

