fn contract_registry_list_impl(
  request: ContractRegistryListRequest,
  namespace: &str,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let namespace = request
    .ns
    .map(normalize_namespace)
    .transpose()?
    .unwrap_or_else(|| namespace.to_string());
  let service_name_filter = request
    .service_name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let channel_filter = request
    .channel
    .map(normalize_channel)
    .transpose()?
    .map(|value| value.to_ascii_lowercase());
  let kind_filter = request
    .kind
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_contract_kind(Some(value.to_string())));
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_contract_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_contract_registry_global()?;
  let mut rows: Vec<ContractRegistryEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.org == org)
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        service_name_filter
          .as_deref()
          .map(|value| entry.service_name == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        channel_filter
          .as_deref()
          .map(|value| entry.channel == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        kind_filter
          .as_deref()
          .map(|value| entry.kind == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.service_name
      .cmp(&b.service_name)
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
      .then_with(|| a.contract_id.cmp(&b.contract_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(contract_registry_view).collect::<Vec<_>>(),
  }))
}

fn sanitize_link_methods(methods_json: Option<Value>, contract_json: &Value) -> Vec<String> {
  let mut values: Vec<String> = methods_json
    .as_ref()
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_uppercase)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  if values.is_empty() {
    if let Some(paths) = contract_json.get("paths").and_then(Value::as_object) {
      for methods in paths.values() {
        if let Some(method_map) = methods.as_object() {
          for method in method_map.keys() {
            let trimmed = method.trim();
            if !trimmed.is_empty() {
              values.push(trimmed.to_ascii_uppercase());
            }
          }
        }
      }
    } else if let Some(items) = contract_json.get("methods").and_then(Value::as_array) {
      for method in items.iter().filter_map(Value::as_str) {
        let trimmed = method.trim();
        if !trimmed.is_empty() {
          values.push(trimmed.to_ascii_uppercase());
        }
      }
    }
  }
  values.sort();
  values.dedup();
  values
}

fn sanitize_link_path_prefixes(
  path_prefixes_json: Option<Value>,
  contract_json: &Value,
) -> Vec<String> {
  let mut values: Vec<String> = path_prefixes_json
    .as_ref()
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  if values.is_empty() {
    if let Some(paths) = contract_json.get("paths").and_then(Value::as_object) {
      for path in paths.keys() {
        let trimmed = path.trim();
        if !trimmed.is_empty() {
          values.push(trimmed.to_string());
        }
      }
    }
  }
  values.sort();
  values.dedup();
  values
}

fn service_link_generate_candidate(
  request: &ServiceLinkGenerateRequest,
) -> Result<(ContractRegistryEntry, ServiceLinkPolicyEntry)> {
  let org = normalize_fed_org(request.org.clone());
  let source_ns = normalize_namespace(request.source_ns.clone())?;
  let source_service = request.source_service.trim().to_string();
  if source_service.is_empty() {
    anyhow::bail!("service.link.generate requires source_service");
  }
  let source_channel = normalize_channel(
    request
      .source_channel
      .clone()
      .unwrap_or_else(|| "prod".to_string()),
  )?
  .to_ascii_lowercase();
  let dest_contract_id = request.dest_contract_id.trim().to_string();
  if dest_contract_id.is_empty() {
    anyhow::bail!("service.link.generate requires dest_contract_id");
  }
  let contract_store = get_contract_registry_global()?;
  let contract = {
    let guard = contract_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&contract_registry_key(
        org.as_str(),
        dest_contract_id.as_str(),
      ))
      .cloned()
      .with_context(|| format!("contract `{}` not found", dest_contract_id))?
  };
  let methods = sanitize_link_methods(request.methods_json.clone(), &contract.contract_json);
  let path_prefixes =
    sanitize_link_path_prefixes(request.path_prefixes_json.clone(), &contract.contract_json);
  let source_ns_for_allow = source_ns.clone();
  let source_service_for_allow = source_service.clone();
  let source_channel_for_allow = source_channel.clone();
  let dest_ns = contract.ns.clone();
  let dest_service = contract.service_name.clone();
  let dest_channel = contract.channel.clone();
  let contract_kind = contract.kind.clone();
  let contract_version = contract.version.clone();
  let contract_id = contract.contract_id.clone();
  let link_id = request
    .link_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_service_link_id);
  let name = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| {
      format!(
        "{}-to-{}-{}",
        source_service, contract.service_name, contract.channel
      )
    });
  let now = now_ms();
  let mut allow_when = json!({
    "claim.ns": source_ns_for_allow,
    "claim.service": source_service_for_allow,
    "claim.channel": source_channel_for_allow,
  });
  if let Some(object) = allow_when.as_object_mut() {
    if !methods.is_empty() {
      object.insert("method_in".to_string(), json!(methods));
    }
    if !path_prefixes.is_empty() {
      object.insert("path_prefix_in".to_string(), json!(path_prefixes));
    }
  }
  let policy = ServiceLinkPolicyEntry {
    org,
    link_id,
    name,
    source_selector_json: json!({
      "ns": source_ns,
      "service": source_service,
      "channel": source_channel,
    }),
    dest_selector_json: json!({
      "ns": dest_ns,
      "service": dest_service,
      "channel": dest_channel,
    }),
    authz_json: json!({
      "default": "deny",
      "allow": [{"when": allow_when}],
      "deny": [],
    }),
    ratelimit_ref_id: request
      .ratelimit_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    egress_constraints_json: json!({
      "allowed_protocols": [
        if contract_kind == "proto" { "grpc" } else { "http" }
      ]
    }),
    enforcement: normalize_service_link_enforcement(request.enforcement.clone()),
    status: normalize_service_link_status(request.status.clone()),
    metadata_json: json!({
      "generated_from_contract_id": contract_id,
      "contract_kind": contract_kind,
      "contract_version": contract_version,
    }),
    created_ms: now,
    updated_ms: now,
  };
  Ok((contract, policy))
}

fn service_link_policy_upsert_impl(
  request: ServiceLinkPolicyUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let link_id = request
    .link_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_service_link_id);
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("service.link.upsert requires name");
  }
  let source_selector_json = request.source_selector_json.unwrap_or_else(|| json!({}));
  let dest_selector_json = request.dest_selector_json.unwrap_or_else(|| json!({}));
  let authz_json = request.authz_json.unwrap_or_else(|| json!({}));
  let egress_constraints_json = request.egress_constraints_json.unwrap_or_else(|| json!({}));
  let metadata_json = request.metadata_json.unwrap_or_else(|| json!({}));
  if !source_selector_json.is_object()
    || !dest_selector_json.is_object()
    || !authz_json.is_object()
    || !egress_constraints_json.is_object()
    || !metadata_json.is_object()
  {
    anyhow::bail!("service.link.upsert selector/authz/constraints/metadata must be objects");
  }
  let now = now_ms();
  let store = get_service_link_policy_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let key = service_link_policy_key(org.as_str(), link_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = ServiceLinkPolicyEntry {
      org: org.clone(),
      link_id: link_id.clone(),
      name,
      source_selector_json,
      dest_selector_json,
      authz_json,
      ratelimit_ref_id: request
        .ratelimit_ref_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      egress_constraints_json,
      enforcement: normalize_service_link_enforcement(request.enforcement),
      status: normalize_service_link_status(request.status),
      metadata_json,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_service_link_policy_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "service.link.upserted",
    "info",
    None,
    Some(link_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "link": service_link_policy_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "link": service_link_policy_view(&entry),
  }))
}

