fn service_link_policy_list_impl(request: ServiceLinkPolicyListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_service_link_status(Some(value.to_string())));
  let source_ns = request
    .source_ns
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let source_service = request
    .source_service
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let dest_ns = request
    .dest_ns
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let dest_service = request
    .dest_service
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_service_link_policy_global()?;
  let mut rows: Vec<ServiceLinkPolicyEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.org == org)
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|value| entry.name.to_ascii_lowercase().contains(value))
          .unwrap_or(true)
      })
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        source_ns
          .as_deref()
          .map(|value| {
            entry
              .source_selector_json
              .get("ns")
              .and_then(Value::as_str)
              .map(|candidate| candidate == value)
              .unwrap_or(false)
          })
          .unwrap_or(true)
      })
      .filter(|entry| {
        source_service
          .as_deref()
          .map(|value| {
            entry
              .source_selector_json
              .get("service")
              .and_then(Value::as_str)
              .map(|candidate| candidate == value)
              .unwrap_or(false)
          })
          .unwrap_or(true)
      })
      .filter(|entry| {
        dest_ns
          .as_deref()
          .map(|value| {
            entry
              .dest_selector_json
              .get("ns")
              .and_then(Value::as_str)
              .map(|candidate| candidate == value)
              .unwrap_or(false)
          })
          .unwrap_or(true)
      })
      .filter(|entry| {
        dest_service
          .as_deref()
          .map(|value| {
            entry
              .dest_selector_json
              .get("service")
              .and_then(Value::as_str)
              .map(|candidate| candidate == value)
              .unwrap_or(false)
          })
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
      .then_with(|| a.link_id.cmp(&b.link_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(service_link_policy_view).collect::<Vec<_>>(),
  }))
}

fn service_link_generate_impl(
  request: ServiceLinkGenerateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let (contract, mut generated) = service_link_generate_candidate(&request)?;
  let org = generated.org.clone();
  let save = request.save.unwrap_or(true);
  if save {
    let store = get_service_link_policy_global()?;
    {
      let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
      let key = service_link_policy_key(org.as_str(), generated.link_id.as_str());
      if let Some(existing) = guard.by_key.get(&key) {
        generated.created_ms = existing.created_ms;
      }
      generated.updated_ms = now_ms();
      guard.by_key.insert(key, generated.clone());
    }
    save_service_link_policy_store(&store, runtime)?;
    publish_supervisor_event(
      events,
      "service.link.generated",
      "info",
      None,
      Some(generated.link_id.clone()),
      None,
      None,
      None,
      json!({
        "org": org,
        "contract_id": contract.contract_id,
        "link": service_link_policy_view(&generated),
      }),
    );
  }
  Ok(json!({
    "org": org,
    "saved": save,
    "contract": contract_registry_view(&contract),
    "link": service_link_policy_view(&generated),
  }))
}

fn portal_devex_request_create_impl(
  request: PortalDevexRequestCreateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
  default_requester: Option<String>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let req_id = request
    .req_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_portal_request_id);
  let kind = request.kind.trim().to_ascii_lowercase();
  if kind.is_empty() {
    anyhow::bail!("portal.request.create requires kind");
  }
  let target_json = request.target_json.unwrap_or_else(|| json!({}));
  let input_json = request.input_json.unwrap_or_else(|| json!({}));
  if !target_json.is_object() || !input_json.is_object() {
    anyhow::bail!("portal.request.create target_json and input_json must be objects");
  }
  let requester = request
    .requester
    .or(default_requester)
    .unwrap_or_else(|| "system".to_string());
  let now = now_ms();
  let store = get_portal_devex_request_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let key = portal_devex_request_key(org.as_str(), req_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = PortalDevexRequestEntry {
      org: org.clone(),
      req_id: req_id.clone(),
      project_id: request
        .project_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      requester,
      kind,
      target_json,
      input_json,
      status: "draft".to_string(),
      generated_patch_json: json!({}),
      pr_json: json!({}),
      last_error: None,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_portal_devex_request_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "portal.request.created",
    "info",
    None,
    Some(req_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "request": portal_devex_request_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "request": portal_devex_request_view(&entry),
  }))
}

