fn portal_devex_request_generate_patch_impl(
  request: PortalDevexRequestGeneratePatchRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let req_id = request.req_id.trim().to_string();
  if req_id.is_empty() {
    anyhow::bail!("portal.request.generate_patch requires req_id");
  }
  let dry_run = request.dry_run.unwrap_or(false);
  let store = get_portal_devex_request_global()?;
  let mut entry = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&portal_devex_request_key(org.as_str(), req_id.as_str()))
      .cloned()
      .with_context(|| format!("portal request `{}` not found", req_id))?
  };

  let mut generated_link = None;
  if entry.kind == "service.link.add_dependency" || entry.kind == "dependency.add" {
    let source_ns = entry
      .input_json
      .get("source_ns")
      .and_then(Value::as_str)
      .unwrap_or(DEFAULT_NAMESPACE)
      .to_string();
    let source_service = entry
      .input_json
      .get("source_service")
      .and_then(Value::as_str)
      .unwrap_or("")
      .to_string();
    let source_channel = entry
      .input_json
      .get("source_channel")
      .and_then(Value::as_str)
      .map(str::to_string);
    let dest_contract_id = entry
      .input_json
      .get("dest_contract_id")
      .and_then(Value::as_str)
      .unwrap_or("")
      .to_string();
    if !source_service.trim().is_empty() && !dest_contract_id.trim().is_empty() {
      let generated_request = ServiceLinkGenerateRequest {
        org: Some(org.clone()),
        source_ns,
        source_service,
        source_channel,
        dest_contract_id,
        link_id: None,
        name: entry
          .input_json
          .get("link_name")
          .and_then(Value::as_str)
          .map(str::to_string),
        methods_json: entry.input_json.get("methods_json").cloned(),
        path_prefixes_json: entry.input_json.get("path_prefixes_json").cloned(),
        ratelimit_ref_id: entry
          .input_json
          .get("ratelimit_ref_id")
          .and_then(Value::as_str)
          .map(str::to_string),
        enforcement: entry
          .input_json
          .get("enforcement")
          .and_then(Value::as_str)
          .map(str::to_string),
        status: Some("active".to_string()),
        save: Some(false),
      };
      let (_, generated) = service_link_generate_candidate(&generated_request)?;
      generated_link = Some(generated);
    }
  }

  let patch_json = json!({
    "schema": "pnix-generated-patch@0.1",
    "req_id": entry.req_id,
    "kind": entry.kind,
    "objects": generated_link
      .as_ref()
      .map(|link| vec![json!({
        "kind": "service_link_policy",
        "link_id": link.link_id,
        "name": link.name,
        "source": link.source_selector_json,
        "dest": link.dest_selector_json,
      })])
      .unwrap_or_else(Vec::new),
    "summary": {
      "object_count": if generated_link.is_some() { 1 } else { 0 },
      "dry_run": dry_run,
    },
  });

  if !dry_run {
    entry.generated_patch_json = patch_json.clone();
    entry.status = "generated".to_string();
    entry.updated_ms = now_ms();
    entry.last_error = None;
    {
      let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        portal_devex_request_key(org.as_str(), req_id.as_str()),
        entry.clone(),
      );
    }
    save_portal_devex_request_store(&store, runtime)?;
    publish_supervisor_event(
      events,
      "portal.request.generated_patch",
      "info",
      None,
      Some(req_id.clone()),
      None,
      None,
      None,
      json!({
        "org": org,
        "request": portal_devex_request_view(&entry),
      }),
    );
  }

  Ok(json!({
    "org": org,
    "request": portal_devex_request_view(&entry),
    "patch": patch_json,
    "generated_link": generated_link.as_ref().map(service_link_policy_view),
    "dry_run": dry_run,
  }))
}

fn codegen_registry_upsert_impl(
  request: CodegenRegistryUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let gen_id = request
    .gen_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_codegen_registry_id);
  let name = request.name.trim().to_string();
  let version = request.version.trim().to_string();
  let bundle_ref_id = request.bundle_ref_id.trim().to_string();
  let sha256 = request
    .sha256
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if name.is_empty() || version.is_empty() || bundle_ref_id.is_empty() || sha256.is_empty() {
    anyhow::bail!("codegen.registry.upsert requires name, version, bundle_ref_id, and sha256");
  }
  let store = get_codegen_registry_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org
        && row.gen_id != gen_id
        && row.name.eq_ignore_ascii_case(name.as_str())
        && row.version == version
    }) {
      anyhow::bail!(
        "codegen registry `{}` version `{}` already exists in org `{}`",
        name,
        version,
        org
      );
    }
    let key = codegen_registry_key(org.as_str(), gen_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or_else(now_ms);
    let row = CodegenRegistryEntry {
      org: org.clone(),
      gen_id: gen_id.clone(),
      name,
      version,
      bundle_ref_id,
      sha256,
      attestation_ref_id: request
        .attestation_ref_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      status: normalize_codegen_registry_status(request.status),
      created_ms,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_codegen_registry_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "codegen.registry.upserted",
    "info",
    None,
    Some(gen_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "generator": codegen_registry_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "generator": codegen_registry_view(&entry),
  }))
}

