fn codegen_registry_list_impl(request: CodegenRegistryListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_codegen_registry_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_codegen_registry_global()?;
  let mut rows: Vec<CodegenRegistryEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        name_filter
          .as_deref()
          .map(|value| {
            row.name.to_ascii_lowercase().contains(value)
              || row.version.to_ascii_lowercase().contains(value)
          })
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| a.version.cmp(&b.version))
      .then_with(|| a.gen_id.cmp(&b.gen_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(codegen_registry_view).collect::<Vec<_>>(),
  }))
}

fn codegen_run_start_impl(
  request: CodegenRunStartRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request
    .run_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_codegen_run_id);
  let name = request.name.trim().to_string();
  let version = request
    .version
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "0.1.0".to_string());
  let source_kind = normalize_codegen_source_kind(Some(request.source_kind));
  let source_id = request.source_id.trim().to_string();
  if name.is_empty() || source_id.is_empty() {
    anyhow::bail!("codegen.run.start requires name and source_id");
  }
  let input_json = request.input_json.unwrap_or_else(|| json!({}));
  if !input_json.is_object() {
    anyhow::bail!("codegen.run.start input_json must be an object");
  }
  let options_json = request.options_json.unwrap_or_else(|| json!({}));
  if !options_json.is_object() {
    anyhow::bail!("codegen.run.start options_json must be an object");
  }
  let dry_run = request.dry_run.unwrap_or(false);
  let mut patch_json = json!({});
  let mut plan_json = json!({});
  let mut outputs = Vec::new();

  if source_kind == "contract" {
    let source_ns = input_json
      .get("source_ns")
      .and_then(Value::as_str)
      .unwrap_or(DEFAULT_NAMESPACE)
      .to_string();
    let source_service = input_json
      .get("source_service")
      .and_then(Value::as_str)
      .unwrap_or("")
      .to_string();
    if source_service.trim().is_empty() {
      anyhow::bail!("codegen.run.start(contract) requires input_json.source_service");
    }
    let generated_request = ServiceLinkGenerateRequest {
      org: Some(org.clone()),
      source_ns: source_ns.clone(),
      source_service: source_service.clone(),
      source_channel: input_json
        .get("source_channel")
        .and_then(Value::as_str)
        .map(str::to_string),
      dest_contract_id: source_id.clone(),
      link_id: None,
      name: input_json
        .get("link_name")
        .and_then(Value::as_str)
        .map(str::to_string),
      methods_json: input_json.get("methods_json").cloned(),
      path_prefixes_json: input_json.get("path_prefixes_json").cloned(),
      ratelimit_ref_id: input_json
        .get("ratelimit_ref_id")
        .and_then(Value::as_str)
        .map(str::to_string),
      enforcement: input_json
        .get("enforcement")
        .and_then(Value::as_str)
        .map(str::to_string),
      status: Some("active".to_string()),
      save: Some(false),
    };
    let (contract, generated_link) = service_link_generate_candidate(&generated_request)?;
    patch_json = json!({
      "schema": "pnix-generated-patch@0.1",
      "generator": "contract-to-link",
      "objects": [
        {
          "kind": "service_link_policy",
          "link": service_link_policy_view(&generated_link),
        },
        {
          "kind": "verification_corpus",
          "name": format!("eastwest-authz-{}-to-{}", source_service, contract.service_name),
          "cases": [
            {
              "from": generated_link.source_selector_json,
              "to": generated_link.dest_selector_json,
              "expect": "allow"
            },
            {
              "from": { "ns": source_ns, "service": source_service, "tier": "standard" },
              "to": generated_link.dest_selector_json,
              "method": "POST",
              "path": "/admin",
              "expect": "deny"
            }
          ]
        }
      ],
      "summary": {
        "object_count": 2,
        "dry_run": dry_run,
      }
    });
    outputs.push(json!({
      "kind": "seto_rulepack",
      "path": format!("pnix/seto/service_links/{}.seto.toml", generated_link.link_id),
    }));
    outputs.push(json!({
      "kind": "verification_corpus",
      "path": format!("pnix/verification/corpus/eastwest_authz_matrix_{}.json", generated_link.link_id),
    }));
  } else if source_kind == "incident" {
    let route_id = input_json
      .get("route_id")
      .and_then(Value::as_str)
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    let effects = if let Some(route_id) = route_id {
      let splits = input_json
        .get("splits")
        .cloned()
        .filter(|value| value.is_array())
        .unwrap_or_else(|| {
          json!([
            {"slice_kind":"release","slice_id":"old","weight":10000},
            {"slice_kind":"release","slice_id":"new","weight":0}
          ])
        });
      vec![json!({
        "id": "e1",
        "kind": "route.traffic.set",
        "params": {
          "route_id": route_id,
          "splits": splits
        }
      })]
    } else {
      vec![json!({
        "id": "e1",
        "kind": "noop",
        "params": {
          "reason": "incident-plan-skeleton"
        }
      })]
    };
    plan_json = json!({
      "schema": "pnix-effect-plan@0.1",
      "meta": {
        "planner": {"plugin": "codegen-incident", "version": version},
        "request": {"ts_ms": now_ms(), "source_kind": source_kind, "source_id": source_id},
      },
      "effects": effects,
    });
    outputs.push(json!({
      "kind": "effect_plan",
      "ref": format!("codegen:plan:{}", run_id),
    }));
  } else {
    patch_json = json!({
      "schema": "pnix-generated-patch@0.1",
      "generator": name,
      "summary": {
        "source_kind": source_kind,
        "source_id": source_id,
        "dry_run": dry_run,
      },
      "objects": [],
    });
    outputs.push(json!({
      "kind": "generated_patch",
      "ref": format!("codegen:patch:{}", run_id),
    }));
  }

  let manifest_json = json!({
    "schema": "pnix-codegen-manifest@0.1",
    "generator": format!("{}@{}", name, version),
    "source": {
      "kind": source_kind,
      "id": source_id,
    },
    "inputs": input_json,
    "options": options_json,
    "outputs": outputs,
    "dry_run": dry_run,
  });
  let patch_ref_id = if patch_json.as_object().is_some_and(|row| !row.is_empty()) {
    Some(format!("codegen:patch:{}", run_id))
  } else {
    None
  };
  let plan_ref_id = if plan_json.as_object().is_some_and(|row| !row.is_empty()) {
    Some(format!("codegen:plan:{}", run_id))
  } else {
    None
  };

  let entry = CodegenRunEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    name,
    version,
    source_kind: source_kind.clone(),
    source_id: source_id.clone(),
    created_ms: now_ms(),
    status: normalize_codegen_run_status(Some("ok".to_string())),
    manifest_ref_id: format!("codegen:manifest:{}", run_id),
    patch_ref_id,
    plan_ref_id,
    manifest_json,
    patch_json,
    plan_json,
    last_error: None,
  };
  let store = get_codegen_run_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      codegen_run_key(org.as_str(), run_id.as_str()),
      entry.clone(),
    );
  }
  save_codegen_run_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "codegen.run.completed",
    "info",
    None,
    Some(run_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "run": codegen_run_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "run": codegen_run_view(&entry),
  }))
}

