fn marketplace_package_upsert_impl(
  request: MarketplacePackageUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let package_id = request
    .package_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_marketplace_package_id);
  let package_type = normalize_marketplace_package_type(Some(request.package_type));
  let name = request.name.trim().to_string();
  let publisher = request.publisher.trim().to_string();
  if name.is_empty() || publisher.is_empty() {
    anyhow::bail!("marketplace.package.upsert requires name and publisher");
  }
  let mut tags_json = request.tags_json.unwrap_or_else(|| json!([]));
  if !tags_json.is_array() {
    tags_json = json!([]);
  }

  let store = get_marketplace_package_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org
        && row.package_id != package_id
        && row.package_type == package_type
        && row.name.eq_ignore_ascii_case(name.as_str())
    }) {
      anyhow::bail!(
        "marketplace package `{}` type `{}` already exists in org `{}`",
        name,
        package_type,
        org
      );
    }
    let key = marketplace_package_key(org.as_str(), package_id.as_str());
    let now = now_ms();
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = MarketplacePackageEntry {
      org: org.clone(),
      package_id: package_id.clone(),
      package_type,
      name,
      description: request
        .description
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      publisher,
      tags_json,
      status: normalize_marketplace_package_status(request.status),
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_marketplace_package_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "marketplace.package.upserted",
    "info",
    None,
    Some(entry.package_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "package": marketplace_package_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "package": marketplace_package_view(&entry),
  }))
}

