fn marketplace_release_list_impl(request: MarketplaceReleaseListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let package_id_filter = request
    .package_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let channel_filter = request
    .channel
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let risk_filter = request
    .risk_level
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_marketplace_risk_level(Some(value.to_string())));
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_marketplace_release_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_marketplace_release_global()?;
  let mut rows: Vec<MarketplaceReleaseEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        package_id_filter
          .as_deref()
          .map(|value| row.package_id == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        channel_filter
          .as_deref()
          .map(|value| row.channel == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        risk_filter
          .as_deref()
          .map(|value| row.risk_level == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.package_id
      .cmp(&b.package_id)
      .then_with(|| a.channel.cmp(&b.channel))
      .then_with(|| b.created_ms.cmp(&a.created_ms))
      .then_with(|| a.release_id.cmp(&b.release_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(marketplace_release_view).collect::<Vec<_>>(),
  }))
}

fn marketplace_release_verify_impl(
  request: MarketplaceReleaseVerifyRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let package_id = request.package_id.trim().to_string();
  let release_id = request.release_id.trim().to_string();
  let run_id = request.run_id.trim().to_string();
  if package_id.is_empty() || release_id.is_empty() || run_id.is_empty() {
    anyhow::bail!("marketplace.release.verify requires package_id, release_id, and run_id");
  }
  let release_key = marketplace_release_key(org.as_str(), package_id.as_str(), release_id.as_str());
  let updated_release = {
    let release_store = get_marketplace_release_global()?;
    let mut guard = release_store.write().unwrap_or_else(|e| e.into_inner());
    let Some(row) = guard.by_key.get_mut(&release_key) else {
      anyhow::bail!(
        "marketplace.release.verify release `{}` not found for package `{}`",
        release_id,
        package_id
      );
    };
    let status = normalize_marketplace_verification_status(request.status.clone());
    if status == "passed" && row.status == "candidate" {
      row.status = "verified".to_string();
      row.updated_ms = now_ms();
      Some(row.clone())
    } else {
      None
    }
  };
  if updated_release.is_some() {
    let release_store = get_marketplace_release_global()?;
    save_marketplace_release_store(&release_store, runtime)?;
  }

  let verification_entry = MarketplaceVerificationResultEntry {
    org: org.clone(),
    package_id: package_id.clone(),
    release_id: release_id.clone(),
    run_id,
    status: normalize_marketplace_verification_status(request.status),
    summary_json: request
      .summary_json
      .filter(|value| value.is_object())
      .unwrap_or_else(|| json!({})),
    updated_ms: now_ms(),
  };
  let verification_store = get_marketplace_verification_result_global()?;
  {
    let mut guard = verification_store
      .write()
      .unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      marketplace_verification_result_key(org.as_str(), package_id.as_str(), release_id.as_str()),
      verification_entry.clone(),
    );
  }
  save_marketplace_verification_result_store(&verification_store, runtime)?;
  publish_supervisor_event(
    events,
    "marketplace.release.verified",
    "info",
    None,
    Some(release_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "package_id": package_id,
      "verification": marketplace_verification_result_view(&verification_entry),
      "release_status_changed": updated_release.is_some(),
    }),
  );
  Ok(json!({
    "org": org,
    "package_id": package_id,
    "verification": marketplace_verification_result_view(&verification_entry),
    "release": updated_release.as_ref().map(marketplace_release_view),
  }))
}

