fn marketplace_release_status_impl(request: MarketplaceReleaseStatusRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let package_id = request.package_id.trim().to_string();
  let release_id = request.release_id.trim().to_string();
  if package_id.is_empty() || release_id.is_empty() {
    anyhow::bail!("marketplace.release.status requires package_id and release_id");
  }
  let release = {
    let store = get_marketplace_release_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&marketplace_release_key(
        org.as_str(),
        package_id.as_str(),
        release_id.as_str(),
      ))
      .cloned()
  };
  let verification = {
    let store = get_marketplace_verification_result_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&marketplace_verification_result_key(
        org.as_str(),
        package_id.as_str(),
        release_id.as_str(),
      ))
      .cloned()
  };
  let revocations = {
    let store = get_marketplace_revoke_event_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org && row.package_id == package_id)
      .filter(|row| row.status == "active")
      .filter(|row| {
        row
          .release_id
          .as_deref()
          .map(|value| value == release_id)
          .unwrap_or(true)
      })
      .cloned()
      .collect::<Vec<_>>()
  };
  Ok(json!({
    "org": org,
    "package_id": package_id,
    "release_id": release_id,
    "exists": release.is_some(),
    "release": release.as_ref().map(marketplace_release_view),
    "verification": verification.as_ref().map(marketplace_verification_result_view),
    "active_revocations": revocations.iter().map(marketplace_revoke_event_view).collect::<Vec<_>>(),
  }))
}

fn marketplace_policy_set_impl(
  request: MarketplacePolicySetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let policy_id = request
    .policy_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_marketplace_policy_id);
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("marketplace.policy.set requires name");
  }
  let policy_json = request
    .policy_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({}));
  let store = get_marketplace_policy_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org && row.policy_id != policy_id && row.name.eq_ignore_ascii_case(name.as_str())
    }) {
      anyhow::bail!(
        "marketplace policy `{}` already exists in org `{}`",
        name,
        org
      );
    }
    let row = MarketplacePolicyEntry {
      org: org.clone(),
      policy_id: policy_id.clone(),
      name,
      policy_json,
      status: normalize_marketplace_policy_status(request.status),
      updated_ms: now_ms(),
    };
    guard.by_key.insert(
      marketplace_policy_key(org.as_str(), policy_id.as_str()),
      row.clone(),
    );
    row
  };
  save_marketplace_policy_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "marketplace.policy.set",
    "info",
    None,
    Some(policy_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "policy": marketplace_policy_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "policy": marketplace_policy_view(&entry),
  }))
}

