fn marketplace_project_pin_set_impl(
  request: MarketplaceProjectPinSetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let project_id = request.project_id.trim().to_string();
  let package_type = normalize_marketplace_package_type(Some(request.package_type));
  let name = request.name.trim().to_string();
  let pinned_release_id = request.pinned_release_id.trim().to_string();
  if project_id.is_empty() || name.is_empty() || pinned_release_id.is_empty() {
    anyhow::bail!("marketplace.project.pin.set requires project_id, name, and pinned_release_id");
  }
  let release = {
    let release_store = get_marketplace_release_global()?;
    let guard = release_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .find(|row| row.org == org && row.release_id == pinned_release_id && row.status != "revoked")
      .cloned()
      .with_context(|| {
        format!(
          "marketplace.project.pin.set release `{}` not found in org `{}`",
          pinned_release_id, org
        )
      })?
  };
  let package = {
    let package_store = get_marketplace_package_global()?;
    let guard = package_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&marketplace_package_key(
        org.as_str(),
        release.package_id.as_str(),
      ))
      .cloned()
      .with_context(|| {
        format!(
          "marketplace.project.pin.set package `{}` not found in org `{}`",
          release.package_id, org
        )
      })?
  };
  if package.package_type != package_type || !package.name.eq_ignore_ascii_case(name.as_str()) {
    anyhow::bail!(
      "marketplace.project.pin.set release `{}` does not match package_type/name `{}/{}`",
      pinned_release_id,
      package_type,
      name
    );
  }
  let pinned_version = if request.pinned_version.trim().is_empty() {
    release.version.clone()
  } else {
    request.pinned_version.trim().to_string()
  };
  let channel = request
    .channel
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
    .unwrap_or_else(|| release.channel.clone());
  let entry = ProjectPackagePinEntry {
    org: org.clone(),
    project_id: project_id.clone(),
    package_type: package_type.clone(),
    name: package.name.clone(),
    pinned_release_id,
    pinned_version,
    channel,
    mode: normalize_project_package_pin_mode(request.mode),
    updated_ms: now_ms(),
  };
  let store = get_project_package_pin_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      project_package_pin_key(
        org.as_str(),
        project_id.as_str(),
        package_type.as_str(),
        package.name.as_str(),
      ),
      entry.clone(),
    );
  }
  save_project_package_pin_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "marketplace.project.pin.updated",
    "info",
    None,
    Some(project_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "pin": project_package_pin_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "pin": project_package_pin_view(&entry),
  }))
}

