fn marketplace_install_request_apply_impl(
  request: MarketplaceInstallRequestApplyRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let req_id = request.req_id.trim().to_string();
  if req_id.is_empty() {
    anyhow::bail!("marketplace.install.request.apply requires req_id");
  }
  let mut install_entry = {
    let install_store = get_marketplace_install_request_global()?;
    let guard = install_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&marketplace_install_request_key(
        org.as_str(),
        req_id.as_str(),
      ))
      .cloned()
      .with_context(|| format!("install request `{}` not found", req_id))?
  };
  if matches!(
    install_entry.status.as_str(),
    "awaiting_approval" | "rejected" | "canceled"
  ) {
    anyhow::bail!(
      "install request `{}` in status `{}` is not applyable",
      req_id,
      install_entry.status
    );
  }
  let release = {
    let release_store = get_marketplace_release_global()?;
    let guard = release_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .find(|row| {
        row.org == org
          && row.package_id == install_entry.package_id
          && row.release_id == install_entry.target_release_id
      })
      .cloned()
      .with_context(|| {
        format!(
          "install request target release `{}` not found",
          install_entry.target_release_id
        )
      })?
  };
  let package = {
    let package_store = get_marketplace_package_global()?;
    let guard = package_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&marketplace_package_key(
        org.as_str(),
        install_entry.package_id.as_str(),
      ))
      .cloned()
      .with_context(|| {
        format!(
          "install request package `{}` not found",
          install_entry.package_id
        )
      })?
  };
  let pin_entry = ProjectPackagePinEntry {
    org: org.clone(),
    project_id: install_entry.project_id.clone(),
    package_type: package.package_type.clone(),
    name: package.name.clone(),
    pinned_release_id: release.release_id.clone(),
    pinned_version: release.version.clone(),
    channel: release.channel.clone(),
    mode: "pinned".to_string(),
    updated_ms: now_ms(),
  };
  let pin_store = get_project_package_pin_global()?;
  {
    let mut guard = pin_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      project_package_pin_key(
        org.as_str(),
        pin_entry.project_id.as_str(),
        pin_entry.package_type.as_str(),
        pin_entry.name.as_str(),
      ),
      pin_entry.clone(),
    );
  }
  save_project_package_pin_store(&pin_store, runtime)?;

  install_entry.status = "applied".to_string();
  install_entry.updated_ms = now_ms();
  install_entry.last_error = None;
  let install_store = get_marketplace_install_request_global()?;
  {
    let mut guard = install_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      marketplace_install_request_key(org.as_str(), req_id.as_str()),
      install_entry.clone(),
    );
  }
  save_marketplace_install_request_store(&install_store, runtime)?;
  publish_supervisor_event(
    events,
    "marketplace.install.request.applied",
    "info",
    None,
    Some(req_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "request": marketplace_install_request_view(&install_entry),
      "pin": project_package_pin_view(&pin_entry),
    }),
  );
  Ok(json!({
    "org": org,
    "request": marketplace_install_request_view(&install_entry),
    "pin": project_package_pin_view(&pin_entry),
  }))
}

