fn resolve_agent_policy(org: &str, policy_id: Option<&str>) -> Result<AgentPolicyEntry> {
  let store = get_agent_policy_global()?;
  let guard = store.read().unwrap_or_else(|e| e.into_inner());
  if let Some(policy_id) = policy_id
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
  {
    let row = guard
      .by_key
      .get(&agent_policy_key(org, policy_id.as_str()))
      .cloned()
      .with_context(|| format!("agent policy `{}` not found for org `{}`", policy_id, org))?;
    return Ok(row);
  }
  if let Some(row) = guard
    .by_key
    .values()
    .find(|row| {
      row.org == org && row.status == "active" && row.name.eq_ignore_ascii_case("default")
    })
    .cloned()
  {
    return Ok(row);
  }
  if let Some(row) = guard
    .by_key
    .values()
    .find(|row| row.org == org && row.status == "active")
    .cloned()
  {
    return Ok(row);
  }
  Ok(AgentPolicyEntry {
    org: org.to_string(),
    policy_id: "builtin-default".to_string(),
    name: "builtin-default".to_string(),
    scope_json: json!({}),
    rules_json: json!({
      "max_iterations": 3,
      "max_patch_bytes": 200000,
      "max_prs_per_run": 1,
      "auto_merge": {
        "dev": {"enabled": true, "max_risk": "low"},
        "staging": {"enabled": false},
        "prod": {"enabled": false}
      }
    }),
    status: "active".to_string(),
    updated_ms: now_ms(),
  })
}

fn risk_rank(level: &str) -> i32 {
  match normalize_marketplace_risk_level(Some(level.to_string())).as_str() {
    "low" => 0,
    "medium" => 1,
    "high" => 2,
    "critical" => 3,
    _ => 0,
  }
}

fn agent_auto_merge_allowed(
  policy: &AgentPolicyEntry,
  channel: Option<&str>,
  risk_level: &str,
) -> bool {
  let channel = channel
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
    .unwrap_or_else(|| "dev".to_string());
  let Some(channel_rules) = policy
    .rules_json
    .get("auto_merge")
    .and_then(Value::as_object)
    .and_then(|auto| auto.get(channel.as_str()))
  else {
    return false;
  };
  let enabled = channel_rules
    .get("enabled")
    .and_then(Value::as_bool)
    .unwrap_or(false);
  if !enabled {
    return false;
  }
  let max_risk = channel_rules
    .get("max_risk")
    .and_then(Value::as_str)
    .map(str::to_string)
    .unwrap_or_else(|| "low".to_string());
  risk_rank(risk_level) <= risk_rank(max_risk.as_str())
}

fn agent_policy_set_impl(
  request: AgentPolicySetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let policy_id = request
    .policy_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_agent_policy_id);
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("agent.policy.set requires name");
  }
  let scope_json = request
    .scope_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({}));
  let rules_json = request
    .rules_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({}));
  let store = get_agent_policy_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org && row.policy_id != policy_id && row.name.eq_ignore_ascii_case(name.as_str())
    }) {
      anyhow::bail!("agent policy `{}` already exists in org `{}`", name, org);
    }
    let row = AgentPolicyEntry {
      org: org.clone(),
      policy_id: policy_id.clone(),
      name,
      scope_json,
      rules_json,
      status: normalize_agent_policy_status(request.status),
      updated_ms: now_ms(),
    };
    guard.by_key.insert(
      agent_policy_key(org.as_str(), policy_id.as_str()),
      row.clone(),
    );
    row
  };
  save_agent_policy_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "agent.policy.set",
    "info",
    None,
    Some(policy_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "policy": agent_policy_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "policy": agent_policy_view(&entry),
  }))
}

