fn agent_run_start_impl(
  request: AgentRunStartRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
  token_id: &str,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request
    .run_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_agent_run_id);
  let trigger_kind = normalize_agent_trigger_kind(Some(request.trigger_kind));
  let trigger_id = request.trigger_id.trim().to_string();
  let project_id = request.project_id.trim().to_string();
  if trigger_id.is_empty() || project_id.is_empty() {
    anyhow::bail!("agent.run.start requires trigger_id and project_id");
  }
  let ns = request
    .ns
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_namespace(value.to_string()))
    .transpose()?;
  let channel = request
    .channel
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let model_spec_json = request
    .model_spec_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({"model":"local-agent-v1","temperature":0.1}));
  let budget_json = request
    .budget_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| {
      json!({
        "max_iterations": 3,
        "max_tool_calls": 16,
        "max_patch_bytes": 200000,
        "max_prs_per_run": 1
      })
    });
  let input_json = request
    .input_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({}));
  let options_json = request
    .options_json
    .filter(|value| value.is_object())
    .unwrap_or_else(|| json!({}));
  let risk_level = options_json
    .get("risk_level")
    .and_then(Value::as_str)
    .map(str::to_string)
    .map(|value| normalize_marketplace_risk_level(Some(value)))
    .unwrap_or_else(|| "low".to_string());
  let policy = resolve_agent_policy(org.as_str(), request.policy_id.as_deref())?;
  let pattern_stack_bundle = agent_pattern_stack_bundle_from_options(&options_json);
  let pattern_stack_gate_passed = pattern_stack_bundle
    .as_ref()
    .map(pattern_stack_gate_pass)
    .unwrap_or(true);

  let mut artifact_links: Vec<AgentArtifactLinkEntry> = Vec::new();
  let input_snapshot = json!({
    "trigger": {
      "kind": trigger_kind,
      "id": trigger_id,
      "project_id": project_id,
      "ns": ns,
      "channel": channel,
    },
    "input_json": input_json,
    "options_json": options_json,
    "policy_id": policy.policy_id,
  });
  artifact_links.push(AgentArtifactLinkEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    kind: "input_snapshot".to_string(),
    ref_id: format!("local:agent_input:{}", run_id),
    sha256: sha256_hex(&input_snapshot)
      .trim_start_matches("sha256:")
      .to_string(),
    created_ms: now_ms(),
  });

  let create_pr = options_json
    .get("create_pr")
    .and_then(Value::as_bool)
    .unwrap_or(true);
  let mut codegen_run: Option<Value> = None;
  if matches!(trigger_kind.as_str(), "contract" | "incident" | "gitplan") {
    let source_kind = match trigger_kind.as_str() {
      "contract" => "contract",
      "incident" => "incident",
      "gitplan" => "git_plan",
      _ => "portal_request",
    };
    let codegen_req = CodegenRunStartRequest {
      org: Some(org.clone()),
      run_id: None,
      name: "agent-loop".to_string(),
      version: Some("0.1.0".to_string()),
      source_kind: source_kind.to_string(),
      source_id: trigger_id.clone(),
      input_json: Some(input_json.clone()),
      options_json: Some(options_json.clone()),
      dry_run: Some(false),
    };
    let codegen_output = codegen_run_start_impl(codegen_req, runtime, events)?;
    codegen_run = codegen_output.get("run").cloned();
    if let Some(run) = codegen_run.as_ref() {
      if let Some(ref_id) = run.get("manifest_ref_id").and_then(Value::as_str) {
        artifact_links.push(AgentArtifactLinkEntry {
          org: org.clone(),
          run_id: run_id.clone(),
          kind: "generated_manifest".to_string(),
          ref_id: ref_id.to_string(),
          sha256: sha256_hex(run).trim_start_matches("sha256:").to_string(),
          created_ms: now_ms(),
        });
      }
      if let Some(ref_id) = run.get("patch_ref_id").and_then(Value::as_str) {
        let patch_json = run.get("patch_json").cloned().unwrap_or_else(|| json!({}));
        artifact_links.push(AgentArtifactLinkEntry {
          org: org.clone(),
          run_id: run_id.clone(),
          kind: "generated_patch".to_string(),
          ref_id: ref_id.to_string(),
          sha256: sha256_hex(&patch_json)
            .trim_start_matches("sha256:")
            .to_string(),
          created_ms: now_ms(),
        });
        let patch_bytes = serde_json::to_vec(&patch_json).unwrap_or_default().len() as u64;
        let max_patch = budget_json
          .get("max_patch_bytes")
          .and_then(Value::as_u64)
          .unwrap_or(200000);
        if patch_bytes > max_patch {
          anyhow::bail!(
            "agent.run.start generated patch bytes {} exceeds budget max_patch_bytes {}",
            patch_bytes,
            max_patch
          );
        }
      }
      if let Some(ref_id) = run.get("plan_ref_id").and_then(Value::as_str) {
        let plan_json = run.get("plan_json").cloned().unwrap_or_else(|| json!({}));
        artifact_links.push(AgentArtifactLinkEntry {
          org: org.clone(),
          run_id: run_id.clone(),
          kind: "effect_plan".to_string(),
          ref_id: ref_id.to_string(),
          sha256: sha256_hex(&plan_json)
            .trim_start_matches("sha256:")
            .to_string(),
          created_ms: now_ms(),
        });
      }
    }
  }

  let sim_req = SimulationRunRequest {
    ns: ns.clone(),
    source_kind: "agent_run".to_string(),
    source_id: run_id.clone(),
    base_ref_json: Some(json!({
      "trigger_kind": trigger_kind,
      "trigger_id": trigger_id,
    })),
    proposed_ref_json: Some(json!({
      "codegen_run_id": codegen_run
        .as_ref()
        .and_then(|run| run.get("run_id"))
        .and_then(Value::as_str),
    })),
    env_snapshot_ref_id: Some(format!("local:agent_env:{}", run_id)),
  };
  let simulation_output = simulation_run_impl(
    sim_req,
    ns.as_deref().unwrap_or(DEFAULT_NAMESPACE),
    runtime,
    events,
  )?;
  if let Some(sim_result) = simulation_output.get("simulation_result") {
    if let Some(ref_id) = sim_result.get("result_ref_id").and_then(Value::as_str) {
      artifact_links.push(AgentArtifactLinkEntry {
        org: org.clone(),
        run_id: run_id.clone(),
        kind: "simulation_result".to_string(),
        ref_id: ref_id.to_string(),
        sha256: sha256_hex(sim_result)
          .trim_start_matches("sha256:")
          .to_string(),
        created_ms: now_ms(),
      });
    }
  }

  let iteration = AgentIterationEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    iter: 1,
    created_ms: now_ms(),
    status: "done".to_string(),
    prompt_ref_id: format!("local:agent_prompt:{}:1", run_id),
    response_ref_id: format!("local:agent_response:{}:1", run_id),
    decision_json: json!({
      "trigger_kind": trigger_kind,
      "selected_policy_id": policy.policy_id,
      "tools_used": {
        "codegen": codegen_run.is_some(),
        "simulation": true
      },
      "risk_level": risk_level,
    }),
  };

  let auto_merge_policy =
    agent_auto_merge_allowed(&policy, channel.as_deref(), risk_level.as_str());
  let auto_merge = auto_merge_policy && pattern_stack_gate_passed;
  let mut gate_reasons = if auto_merge {
    vec![json!({"code":"AGENT_AUTO_MERGE_ALLOWED","msg":"policy allows auto-merge"})]
  } else if auto_merge_policy && !pattern_stack_gate_passed {
    let mut reasons = pattern_stack_bundle
      .as_ref()
      .map(pattern_stack_gate_reasons)
      .unwrap_or_default();
    reasons.push(json!({
      "code":"AGENT_PATTERN_STACK_GATE_BLOCKED",
      "msg":"pattern stack gate blocked challenger promotion",
    }));
    reasons
  } else {
    vec![json!({"code":"AGENT_APPROVAL_REQUIRED","msg":"policy requires approval"})]
  };
  if let Some(bundle) = pattern_stack_bundle.as_ref() {
    gate_reasons.push(json!({
      "code": if pattern_stack_gate_passed {
        "AGENT_PATTERN_STACK_GATE_PASS"
      } else {
        "AGENT_PATTERN_STACK_GATE_REVIEW"
      },
      "msg": "pattern stack optimizer attached to challenger promotion loop",
      "decision": bundle.get("decision").cloned().unwrap_or(Value::Null),
    }));
  }
  let mut gate_entry = AgentDecisionGateEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    gate_kind: if auto_merge {
      "auto_merge".to_string()
    } else {
      "approval_required".to_string()
    },
    reasons_json: Value::Array(gate_reasons),
    approval_id: None,
    updated_ms: now_ms(),
  };
  if !auto_merge {
    let mut approval_reason_codes = if auto_merge_policy && !pattern_stack_gate_passed {
      vec![
        "AGENT_APPROVAL_REQUIRED".to_string(),
        "AGENT_PATTERN_STACK_GATE_BLOCKED".to_string(),
      ]
    } else {
      vec!["AGENT_APPROVAL_REQUIRED".to_string()]
    };
    approval_reason_codes.sort();
    approval_reason_codes.dedup();
    let approval_response = approval_request_create_impl(
      ApprovalRequestCreateRequest {
        ns: ns.clone(),
        approval_id: None,
        target_kind: "agent.promote".to_string(),
        target_id: run_id.clone(),
        reason_codes_json: Some(json!(approval_reason_codes)),
        required_approvals: Some(if channel.as_deref() == Some("prod") {
          2
        } else {
          1
        }),
        required_roles_json: Some(json!(["operator"])),
        scope_json: Some(json!({
          "org": org,
          "project_id": project_id,
          "run_id": run_id,
        })),
        expires_ms: None,
        duration_ms: Some(60 * 60 * 1000),
      },
      ns.as_deref().unwrap_or(DEFAULT_NAMESPACE),
      token_id,
      runtime,
      events,
    )?;
    gate_entry.approval_id = approval_response
      .get("approval")
      .and_then(|value| value.get("approval_id"))
      .and_then(Value::as_str)
      .map(str::to_string);
  }

  let pr_entry = if create_pr {
    Some(AgentPrLinkEntry {
      org: org.clone(),
      run_id: run_id.clone(),
      provider: options_json
        .get("provider")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .unwrap_or_else(|| "local".to_string()),
      pr_id: options_json
        .get("pr_id")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| format!("agent/{}", run_id)),
      status: "open".to_string(),
      head_sha: None,
      checks_json: json!({
        "policy_explain": "pending",
        "plan_analysis": "pending",
        "verification": "pending",
        "what_if": simulation_output
          .get("simulation_result")
          .and_then(|value| value.get("status"))
          .and_then(Value::as_str)
          .unwrap_or("pending"),
      }),
      updated_ms: now_ms(),
    })
  } else {
    None
  };

  let run_entry = AgentRunEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    policy_id: policy.policy_id.clone(),
    created_ms: now_ms(),
    status: if gate_entry.gate_kind == "approval_required" {
      "awaiting_approval".to_string()
    } else if create_pr {
      "pr_open".to_string()
    } else {
      "proposed".to_string()
    },
    trigger_kind,
    trigger_id,
    project_id,
    ns: ns.clone(),
    channel: channel.clone(),
    model_spec_json,
    budget_json,
    summary_json: json!({
      "iteration_count": 1,
      "has_codegen": codegen_run.is_some(),
      "has_pr": pr_entry.is_some(),
      "gate_kind": gate_entry.gate_kind,
      "risk_level": risk_level,
      "pattern_stack_gate_pass": pattern_stack_gate_passed,
      "pattern_stack": pattern_stack_bundle,
      "codegen_run_id": codegen_run
        .as_ref()
        .and_then(|run| run.get("run_id"))
        .and_then(Value::as_str),
      "simulation_scenario_id": simulation_output
        .get("simulation_scenario")
        .and_then(|value| value.get("scenario_id"))
        .and_then(Value::as_str),
    }),
    last_error: None,
    updated_ms: now_ms(),
  };

  let run_store = get_agent_run_global()?;
  {
    let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      agent_run_key(org.as_str(), run_id.as_str()),
      run_entry.clone(),
    );
  }
  save_agent_run_store(&run_store, runtime)?;

  let iter_store = get_agent_iteration_global()?;
  {
    let mut guard = iter_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      agent_iteration_key(org.as_str(), run_id.as_str(), iteration.iter),
      iteration.clone(),
    );
  }
  save_agent_iteration_store(&iter_store, runtime)?;

  let artifact_store = get_agent_artifact_link_global()?;
  {
    let mut guard = artifact_store.write().unwrap_or_else(|e| e.into_inner());
    for entry in &artifact_links {
      guard.by_key.insert(
        agent_artifact_link_key(
          org.as_str(),
          run_id.as_str(),
          entry.kind.as_str(),
          entry.ref_id.as_str(),
        ),
        entry.clone(),
      );
    }
  }
  save_agent_artifact_link_store(&artifact_store, runtime)?;

  if let Some(pr_entry) = pr_entry.clone() {
    let pr_store = get_agent_pr_link_global()?;
    {
      let mut guard = pr_store.write().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .insert(agent_pr_link_key(org.as_str(), run_id.as_str()), pr_entry);
    }
    save_agent_pr_link_store(&pr_store, runtime)?;
  }

  let gate_store = get_agent_decision_gate_global()?;
  {
    let mut guard = gate_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      agent_decision_gate_key(org.as_str(), run_id.as_str()),
      gate_entry.clone(),
    );
  }
  save_agent_decision_gate_store(&gate_store, runtime)?;

  publish_supervisor_event(
    events,
    "agent.run.started",
    "info",
    None,
    Some(run_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "run": agent_run_view(&run_entry),
      "gate": agent_decision_gate_view(&gate_entry),
      "has_pr": pr_entry.is_some(),
    }),
  );
  Ok(json!({
    "org": org,
    "run": agent_run_view(&run_entry),
    "gate": agent_decision_gate_view(&gate_entry),
    "iteration": agent_iteration_view(&iteration),
    "artifacts": artifact_links.iter().map(agent_artifact_link_view).collect::<Vec<_>>(),
    "pr": pr_entry.as_ref().map(agent_pr_link_view),
  }))
}

fn agent_run_get_impl(request: AgentRunByIdRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request.run_id.trim().to_string();
  if run_id.is_empty() {
    anyhow::bail!("agent.run.get requires run_id");
  }
  let run = {
    let store = get_agent_run_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&agent_run_key(org.as_str(), run_id.as_str()))
      .cloned()
  };
  let iterations = {
    let store = get_agent_iteration_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    let mut rows: Vec<AgentIterationEntry> = guard
      .by_key
      .values()
      .filter(|row| row.org == org && row.run_id == run_id)
      .cloned()
      .collect();
    rows.sort_by(|a, b| a.iter.cmp(&b.iter));
    rows
  };
  let artifacts = {
    let store = get_agent_artifact_link_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    let mut rows: Vec<AgentArtifactLinkEntry> = guard
      .by_key
      .values()
      .filter(|row| row.org == org && row.run_id == run_id)
      .cloned()
      .collect();
    rows.sort_by(|a, b| a.kind.cmp(&b.kind).then_with(|| a.ref_id.cmp(&b.ref_id)));
    rows
  };
  let pr = {
    let store = get_agent_pr_link_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&agent_pr_link_key(org.as_str(), run_id.as_str()))
      .cloned()
  };
  let gate = {
    let store = get_agent_decision_gate_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&agent_decision_gate_key(org.as_str(), run_id.as_str()))
      .cloned()
  };
  Ok(json!({
    "org": org,
    "run_id": run_id,
    "exists": run.is_some(),
    "run": run.as_ref().map(agent_run_view),
    "iterations": iterations.iter().map(agent_iteration_view).collect::<Vec<_>>(),
    "artifacts": artifacts.iter().map(agent_artifact_link_view).collect::<Vec<_>>(),
    "pr": pr.as_ref().map(agent_pr_link_view),
    "gate": gate.as_ref().map(agent_decision_gate_view),
  }))
}

fn agent_run_list_impl(request: AgentRunListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let project_filter = request
    .project_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_agent_run_status(Some(value.to_string())));
  let trigger_filter = request
    .trigger_kind
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_agent_trigger_kind(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_agent_run_global()?;
  let mut rows: Vec<AgentRunEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        project_filter
          .as_deref()
          .map(|value| row.project_id == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        trigger_filter
          .as_deref()
          .map(|value| row.trigger_kind == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.created_ms
      .cmp(&a.created_ms)
      .then_with(|| a.run_id.cmp(&b.run_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(agent_run_view).collect::<Vec<_>>(),
  }))
}

fn agent_run_abort_impl(
  request: AgentRunAbortRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request.run_id.trim().to_string();
  if run_id.is_empty() {
    anyhow::bail!("agent.run.abort requires run_id");
  }
  let reason = request
    .reason
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "aborted by request".to_string());
  let run_store = get_agent_run_global()?;
  let run = {
    let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
    let row = guard
      .by_key
      .get_mut(&agent_run_key(org.as_str(), run_id.as_str()))
      .with_context(|| format!("agent run `{}` not found", run_id))?;
    row.status = "aborted".to_string();
    row.last_error = Some(reason.clone());
    row.updated_ms = now_ms();
    row.clone()
  };
  save_agent_run_store(&run_store, runtime)?;
  let pr_store = get_agent_pr_link_global()?;
  {
    let mut guard = pr_store.write().unwrap_or_else(|e| e.into_inner());
    if let Some(pr) = guard
      .by_key
      .get_mut(&agent_pr_link_key(org.as_str(), run_id.as_str()))
    {
      if pr.status == "open" {
        pr.status = "closed".to_string();
        pr.updated_ms = now_ms();
      }
    }
  }
  save_agent_pr_link_store(&pr_store, runtime)?;
  publish_supervisor_event(
    events,
    "agent.run.aborted",
    "warn",
    None,
    Some(run_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "reason": reason,
      "run": agent_run_view(&run),
    }),
  );
  Ok(json!({
    "org": org,
    "run_id": run_id,
    "run": agent_run_view(&run),
  }))
}

fn agent_promote_request_impl(
  request: AgentPromoteRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
  token_id: &str,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request.run_id.trim().to_string();
  if run_id.is_empty() {
    anyhow::bail!("agent.promote.request requires run_id");
  }
  let run_store = get_agent_run_global()?;
  let mut run = {
    let guard = run_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&agent_run_key(org.as_str(), run_id.as_str()))
      .cloned()
      .with_context(|| format!("agent run `{}` not found", run_id))?
  };
  if matches!(run.status.as_str(), "aborted" | "failed") {
    anyhow::bail!(
      "agent run `{}` cannot be promoted from status `{}`",
      run_id,
      run.status
    );
  }
  let policy = resolve_agent_policy(org.as_str(), Some(run.policy_id.as_str()))?;
  let risk_level = run
    .summary_json
    .get("risk_level")
    .and_then(Value::as_str)
    .map(str::to_string)
    .unwrap_or_else(|| "low".to_string());
  let pattern_stack_bundle = run.summary_json.get("pattern_stack").cloned();
  let pattern_stack_gate_passed = pattern_stack_bundle
    .as_ref()
    .map(pattern_stack_gate_pass)
    .unwrap_or(true);
  let auto_merge_policy =
    agent_auto_merge_allowed(&policy, run.channel.as_deref(), risk_level.as_str());
  let auto_merge = auto_merge_policy && pattern_stack_gate_passed;
  let mut gate_reasons = if auto_merge {
    vec![json!({"code":"AGENT_PROMOTE_AUTO_MERGE","msg":"policy permits auto-merge"})]
  } else if auto_merge_policy && !pattern_stack_gate_passed {
    let mut reasons = pattern_stack_bundle
      .as_ref()
      .map(pattern_stack_gate_reasons)
      .unwrap_or_default();
    reasons.push(json!({
      "code":"AGENT_PATTERN_STACK_GATE_BLOCKED",
      "msg":"pattern stack gate blocked challenger promotion",
    }));
    reasons
  } else {
    vec![json!({"code":"AGENT_PROMOTE_APPROVAL_REQUIRED","msg":"approval required by policy"})]
  };
  if pattern_stack_bundle.is_some() {
    gate_reasons.push(json!({
      "code": if pattern_stack_gate_passed {
        "AGENT_PATTERN_STACK_GATE_PASS"
      } else {
        "AGENT_PATTERN_STACK_GATE_REVIEW"
      },
      "msg": "pattern stack optimizer evaluated before promotion",
    }));
  }
  let mut gate = AgentDecisionGateEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    gate_kind: if auto_merge {
      "auto_merge".to_string()
    } else {
      "approval_required".to_string()
    },
    reasons_json: Value::Array(gate_reasons),
    approval_id: None,
    updated_ms: now_ms(),
  };
  if auto_merge {
    let pr_store = get_agent_pr_link_global()?;
    let mut pr_link = {
      let mut guard = pr_store.write().unwrap_or_else(|e| e.into_inner());
      let row = guard
        .by_key
        .entry(agent_pr_link_key(org.as_str(), run_id.as_str()))
        .or_insert(AgentPrLinkEntry {
          org: org.clone(),
          run_id: run_id.clone(),
          provider: "local".to_string(),
          pr_id: format!("agent/{}", run_id),
          status: "open".to_string(),
          head_sha: None,
          checks_json: json!({}),
          updated_ms: now_ms(),
        });
      row.status = "merged".to_string();
      row.updated_ms = now_ms();
      row.clone()
    };
    save_agent_pr_link_store(&pr_store, runtime)?;
    pr_link.status = normalize_agent_pr_status(Some(pr_link.status));
    run.status = "merged".to_string();
    run.updated_ms = now_ms();
  } else {
    let ns = run
      .ns
      .clone()
      .unwrap_or_else(|| DEFAULT_NAMESPACE.to_string());
    let mut approval_reason_codes = if auto_merge_policy && !pattern_stack_gate_passed {
      vec![
        "AGENT_PROMOTE_APPROVAL_REQUIRED".to_string(),
        "AGENT_PATTERN_STACK_GATE_BLOCKED".to_string(),
      ]
    } else {
      vec!["AGENT_PROMOTE_APPROVAL_REQUIRED".to_string()]
    };
    approval_reason_codes.sort();
    approval_reason_codes.dedup();
    let approval_response = approval_request_create_impl(
      ApprovalRequestCreateRequest {
        ns: Some(ns.clone()),
        approval_id: None,
        target_kind: "agent.promote".to_string(),
        target_id: run_id.clone(),
        reason_codes_json: Some(json!(approval_reason_codes)),
        required_approvals: Some(if run.channel.as_deref() == Some("prod") {
          2
        } else {
          1
        }),
        required_roles_json: Some(json!(["operator"])),
        scope_json: Some(json!({
          "org": org,
          "project_id": run.project_id,
          "run_id": run_id,
        })),
        expires_ms: None,
        duration_ms: Some(60 * 60 * 1000),
      },
      ns.as_str(),
      token_id,
      runtime,
      events,
    )?;
    gate.approval_id = approval_response
      .get("approval")
      .and_then(|value| value.get("approval_id"))
      .and_then(Value::as_str)
      .map(str::to_string);
    run.status = "awaiting_approval".to_string();
    run.updated_ms = now_ms();
  }

  {
    let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .insert(agent_run_key(org.as_str(), run_id.as_str()), run.clone());
  }
  save_agent_run_store(&run_store, runtime)?;
  let gate_store = get_agent_decision_gate_global()?;
  {
    let mut guard = gate_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      agent_decision_gate_key(org.as_str(), run_id.as_str()),
      gate.clone(),
    );
  }
  save_agent_decision_gate_store(&gate_store, runtime)?;
  publish_supervisor_event(
    events,
    "agent.promote.requested",
    "info",
    None,
    Some(run_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "run": agent_run_view(&run),
      "gate": agent_decision_gate_view(&gate),
    }),
  );
  Ok(json!({
    "org": org,
    "run": agent_run_view(&run),
    "gate": agent_decision_gate_view(&gate),
  }))
}

fn compliance_pack_set_impl(
  request: CompliancePackSetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let pack_id = request
    .pack_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_compliance_pack_id);
  let name = request.name.trim().to_string();
  let version = request.version.trim().to_string();
  let bundle_ref_id = request.bundle_ref_id.trim().to_string();
  let sha256 = request
    .sha256
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if name.is_empty() || version.is_empty() || bundle_ref_id.is_empty() || sha256.is_empty() {
    anyhow::bail!("compliance.pack.set requires name, version, bundle_ref_id, and sha256");
  }
  let store = get_compliance_pack_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org
        && row.pack_id != pack_id
        && row.name.eq_ignore_ascii_case(name.as_str())
        && row.version == version
    }) {
      anyhow::bail!(
        "compliance pack `{}` version `{}` already exists in org `{}`",
        name,
        version,
        org
      );
    }
    let key = compliance_pack_key(org.as_str(), pack_id.as_str());
    let now = now_ms();
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = CompliancePackEntry {
      org: org.clone(),
      pack_id: pack_id.clone(),
      name,
      version,
      bundle_ref_id,
      sha256,
      status: normalize_compliance_pack_status(request.status),
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_compliance_pack_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "compliance.pack.set",
    "info",
    None,
    Some(entry.pack_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "pack": compliance_pack_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "pack": compliance_pack_view(&entry),
  }))
}

