fn compliance_pack_list_impl(request: CompliancePackListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_compliance_pack_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_compliance_pack_global()?;
  let mut rows: Vec<CompliancePackEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        name_filter
          .as_deref()
          .map(|value| {
            row.name.to_ascii_lowercase().contains(value)
              || row.version.to_ascii_lowercase().contains(value)
          })
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| b.version.cmp(&a.version))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(compliance_pack_view).collect::<Vec<_>>(),
  }))
}

fn control_catalog_set_impl(
  request: ControlCatalogSetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let control_id = request
    .control_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_control_id);
  let pack_id = request.pack_id.trim().to_string();
  let code = request.code.trim().to_string();
  let title = request.title.trim().to_string();
  if pack_id.is_empty() || code.is_empty() || title.is_empty() {
    anyhow::bail!("compliance.control.set requires pack_id, code, and title");
  }
  {
    let pack_store = get_compliance_pack_global()?;
    let guard = pack_store.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&compliance_pack_key(org.as_str(), pack_id.as_str()))
    {
      anyhow::bail!(
        "compliance.control.set pack `{}` not found in org `{}`",
        pack_id,
        org
      );
    }
  }
  let mut scope_json = request.scope_json.unwrap_or_else(|| json!({}));
  if !scope_json.is_object() {
    scope_json = json!({});
  }
  let store = get_control_catalog_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org && row.control_id != control_id && row.pack_id == pack_id && row.code == code
    }) {
      anyhow::bail!(
        "compliance control code `{}` already exists in pack `{}`",
        code,
        pack_id
      );
    }
    let row = ControlCatalogEntry {
      org: org.clone(),
      control_id: control_id.clone(),
      pack_id: pack_id.clone(),
      code,
      title,
      description: request
        .description
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      severity: normalize_control_severity(request.severity),
      scope_json,
      status: normalize_control_status(request.status),
      updated_ms: now_ms(),
    };
    guard.by_key.insert(
      control_catalog_key(org.as_str(), control_id.as_str()),
      row.clone(),
    );
    row
  };
  save_control_catalog_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "compliance.control.set",
    "info",
    None,
    Some(entry.control_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "control": control_catalog_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "control": control_catalog_view(&entry),
  }))
}

