fn evidence_item_ingest_impl(
  request: EvidenceItemIngestRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let mut evidence_id = request
    .evidence_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let kind = request.kind.trim().to_ascii_lowercase();
  let ref_id = request.ref_id.trim().to_string();
  let sha256 = request
    .sha256
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if kind.is_empty() || ref_id.is_empty() || sha256.is_empty() {
    anyhow::bail!("compliance.evidence.ingest requires kind, ref_id, and sha256");
  }
  let mut subject_json = request.subject_json.unwrap_or_else(|| json!({}));
  if !subject_json.is_object() {
    subject_json = json!({});
  }
  let mut integrity_json = request.integrity_json.unwrap_or_else(|| json!({}));
  if !integrity_json.is_object() {
    integrity_json = json!({});
  }
  let store = get_evidence_item_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if evidence_id.is_none() {
      if let Some(existing) = guard
        .by_key
        .values()
        .find(|row| row.org == org && row.kind == kind && row.ref_id == ref_id)
      {
        evidence_id = Some(existing.evidence_id.clone());
      }
    }
    let evidence_id = evidence_id.unwrap_or_else(next_evidence_id);
    let key = evidence_item_key(org.as_str(), evidence_id.as_str());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or_else(|| request.created_ms.unwrap_or_else(now_ms));
    let row = EvidenceItemEntry {
      org: org.clone(),
      evidence_id: evidence_id.clone(),
      kind: kind.clone(),
      ref_id: ref_id.clone(),
      sha256: sha256.clone(),
      created_ms,
      subject_json,
      integrity_json,
      retention_class: normalize_retention_class(request.retention_class),
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_evidence_item_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "compliance.evidence.ingested",
    "info",
    None,
    Some(entry.evidence_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "evidence": evidence_item_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "evidence": evidence_item_view(&entry),
  }))
}

