fn audit_packet_list_impl(request: AuditPacketListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let pack_filter = request
    .pack_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_audit_packet_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_audit_packet_global()?;
  let mut rows: Vec<AuditPacketEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        pack_filter
          .as_deref()
          .map(|value| row.pack_id == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.period_end_ms
      .cmp(&a.period_end_ms)
      .then_with(|| a.packet_id.cmp(&b.packet_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(audit_packet_view).collect::<Vec<_>>(),
  }))
}

fn retention_policy_set_impl(
  request: RetentionPolicySetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let policy_id = request
    .policy_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_retention_policy_id);
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("compliance.retention.set requires name");
  }
  let mut rules_json = request.rules_json.unwrap_or_else(|| json!({}));
  if !rules_json.is_object() {
    rules_json = json!({});
  }
  let store = get_retention_policy_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard.by_key.values().any(|row| {
      row.org == org && row.policy_id != policy_id && row.name.eq_ignore_ascii_case(name.as_str())
    }) {
      anyhow::bail!(
        "retention policy `{}` already exists in org `{}`",
        name,
        org
      );
    }
    let row = RetentionPolicyEntry {
      org: org.clone(),
      policy_id: policy_id.clone(),
      name,
      rules_json,
      status: normalize_retention_policy_status(request.status),
      updated_ms: now_ms(),
    };
    guard.by_key.insert(
      retention_policy_key(org.as_str(), policy_id.as_str()),
      row.clone(),
    );
    row
  };
  save_retention_policy_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "compliance.retention.set",
    "info",
    None,
    Some(policy_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "policy": retention_policy_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "policy": retention_policy_view(&entry),
  }))
}

