fn optimization_scope_channel(scope_json: &Value) -> Option<String> {
  scope_json
    .get("channel")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
}

fn optimization_lever_kind(lever: &Value) -> String {
  lever
    .get("kind")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase)
    .unwrap_or_else(|| "unknown".to_string())
}

fn optimization_forbidden_lever(lever_kind: &str) -> bool {
  matches!(
    lever_kind,
    "waf.disable" | "auth.weaken" | "process.cap.widen"
  )
}

fn optimization_spec_set_impl(
  request: OptimizationSpecSetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spec_id = request
    .spec_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_optimization_spec_id);
  let mut scope_json = request.scope_json.unwrap_or_else(|| json!({}));
  let mut objectives_json = request.objectives_json.unwrap_or_else(|| json!([]));
  let mut constraints_json = request.constraints_json.unwrap_or_else(|| json!([]));
  let mut levers_json = request.levers_json.unwrap_or_else(|| json!([]));
  let mut safety_json = request.safety_json.unwrap_or_else(|| json!({}));
  let mut delivery_json = request.delivery_json.unwrap_or_else(|| json!({}));
  if !scope_json.is_object() {
    scope_json = json!({});
  }
  if !objectives_json.is_array() {
    objectives_json = json!([]);
  }
  if !constraints_json.is_array() {
    constraints_json = json!([]);
  }
  if !levers_json.is_array() {
    levers_json = json!([]);
  }
  if !safety_json.is_object() {
    safety_json = json!({});
  }
  if !delivery_json.is_object() {
    delivery_json = json!({});
  }
  let derived_sha = sha256_hex(&json!({
    "scope_json": scope_json,
    "objectives_json": objectives_json,
    "constraints_json": constraints_json,
    "levers_json": levers_json,
    "safety_json": safety_json,
    "delivery_json": delivery_json,
  }));
  let sha256 = request
    .sha256
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.trim_start_matches("sha256:").to_ascii_lowercase())
    .unwrap_or_else(|| derived_sha.trim_start_matches("sha256:").to_string());
  let spec_ref_id = request
    .spec_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .or_else(|| Some(format!("spec:inline:{}", sha256)));
  let entry = OptimizationSpecEntry {
    org: org.clone(),
    spec_id: spec_id.clone(),
    scope_json,
    objectives_json,
    constraints_json,
    levers_json,
    safety_json,
    delivery_json,
    spec_ref_id,
    sha256,
    status: normalize_optimization_spec_status(request.status),
    updated_ms: now_ms(),
  };
  let store = get_optimization_spec_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      optimization_spec_key(org.as_str(), spec_id.as_str()),
      entry.clone(),
    );
  }
  save_optimization_spec_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "optimizer.spec.set",
    "info",
    None,
    Some(spec_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "spec": optimization_spec_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "spec": optimization_spec_view(&entry),
  }))
}

