fn optimization_run_start_impl(
  request: OptimizationRunStartRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spec_id = request.spec_id.trim().to_string();
  if spec_id.is_empty() {
    anyhow::bail!("optimizer.run.start requires spec_id");
  }
  let spec = {
    let store = get_optimization_spec_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&optimization_spec_key(org.as_str(), spec_id.as_str()))
      .cloned()
      .with_context(|| format!("optimization spec `{}` not found", spec_id))?
  };
  if spec.status == "disabled" {
    anyhow::bail!("optimization spec `{}` is disabled", spec_id);
  }

  let run_id = request
    .run_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_optimization_run_id);
  {
    let store = get_optimization_run_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    if let Some(existing) = guard
      .by_key
      .get(&optimization_run_key(org.as_str(), run_id.as_str()))
      .cloned()
    {
      return Ok(json!({
        "org": org,
        "deduped": true,
        "run": optimization_run_view(&existing),
      }));
    }
  }

  let now = now_ms();
  let window_end_ms = request.window_end_ms.unwrap_or(now);
  let window_start_ms = request
    .window_start_ms
    .unwrap_or_else(|| window_end_ms.saturating_sub(3_600_000));
  if window_start_ms > window_end_ms {
    anyhow::bail!("optimizer.run.start requires window_start_ms <= window_end_ms");
  }
  let input_snapshot_ref_id = request
    .input_snapshot_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| format!("opt-input:inline:{}", run_id));
  let safety_limit = spec
    .safety_json
    .get("max_candidate_plans")
    .and_then(Value::as_u64)
    .map(|value| value as usize)
    .unwrap_or(10);
  let candidate_limit = request
    .candidate_limit
    .unwrap_or(safety_limit)
    .clamp(1, 200);

  let mut levers = spec
    .levers_json
    .as_array()
    .cloned()
    .unwrap_or_default()
    .into_iter()
    .take(candidate_limit)
    .collect::<Vec<_>>();
  if levers.is_empty() {
    levers.push(json!({"kind":"noop"}));
  }
  let pattern_stack_bundle = optimization_pattern_stack_bundle(&spec);
  let pattern_stack_gate_passed = pattern_stack_bundle
    .as_ref()
    .map(pattern_stack_gate_pass)
    .unwrap_or(true);

  let channel = optimization_scope_channel(&spec.scope_json).unwrap_or_else(|| "dev".to_string());
  let run_entry = OptimizationRunEntry {
    org: org.clone(),
    run_id: run_id.clone(),
    spec_id: spec_id.clone(),
    window_start_ms,
    window_end_ms,
    status: "running".to_string(),
    input_snapshot_ref_id,
    summary_json: json!({}),
    last_error: None,
    created_ms: now,
    updated_ms: now,
  };
  {
    let store = get_optimization_run_global()?;
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      optimization_run_key(org.as_str(), run_id.as_str()),
      run_entry.clone(),
    );
    drop(guard);
    save_optimization_run_store(&store, runtime)?;
  }

  let candidate_store = get_optimization_candidate_global()?;
  let evaluation_store = get_optimization_evaluation_global()?;
  let recommendation_store = get_optimization_recommendation_global()?;
  let mut candidate_views = Vec::new();
  let mut evaluation_views = Vec::new();
  let mut recommendation_views = Vec::new();
  let mut rejected = 0usize;
  let mut approval_needed = 0usize;
  for (idx, lever) in levers.into_iter().enumerate() {
    let lever_kind = optimization_lever_kind(&lever);
    let lever_set_json = if lever.is_object() {
      lever
    } else {
      json!({ "kind": lever_kind, "value": lever })
    };
    let cand_id = next_optimization_candidate_id();
    let plan_hash = sha256_hex(&lever_set_json)
      .trim_start_matches("sha256:")
      .to_string();
    let candidate = OptimizationCandidateEntry {
      org: org.clone(),
      run_id: run_id.clone(),
      cand_id: cand_id.clone(),
      lever_set_json,
      patch_ref_id: None,
      plan_ref_id: None,
      plan_hash: Some(plan_hash),
      created_ms: now_ms(),
    };
    {
      let mut guard = candidate_store.write().unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        optimization_candidate_key(org.as_str(), run_id.as_str(), cand_id.as_str()),
        candidate.clone(),
      );
    }
    candidate_views.push(optimization_candidate_view(&candidate));

    let forbidden = optimization_forbidden_lever(lever_kind.as_str());
    let eval_status = if forbidden {
      "violates_constraints"
    } else {
      "ok"
    };
    let delta_cost_minor: i64 = -1000 * ((idx as i64) + 1);
    let delta_p95_ms: i64 = (idx as i64) * 2;
    let risk_score: i64 = if forbidden { 85 } else { 20 + (idx as i64) * 5 };
    let evaluation = OptimizationEvaluationEntry {
      org: org.clone(),
      run_id: run_id.clone(),
      cand_id: cand_id.clone(),
      status: normalize_optimization_evaluation_status(Some(eval_status.to_string())),
      whatif_ref_id: format!("simulation:inline:{}:{}", run_id, cand_id),
      analysis_ref_id: format!("analysis:inline:{}:{}", run_id, cand_id),
      deltas_json: json!({
        "delta_cost_minor": delta_cost_minor,
        "delta_p95_ms": delta_p95_ms,
        "delta_error_bp": 0,
        "delta_risk_score": risk_score,
      }),
      score_json: json!({
        "weighted_score": (100 - ((idx as i64) * 10) - if forbidden { 60 } else { 0 }).max(0),
        "pareto_rank": idx + 1,
      }),
      created_ms: now_ms(),
    };
    {
      let mut guard = evaluation_store.write().unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        optimization_evaluation_key(org.as_str(), run_id.as_str(), cand_id.as_str()),
        evaluation.clone(),
      );
    }
    evaluation_views.push(optimization_evaluation_view(&evaluation));

    let (decision, reason_code) = if forbidden {
      rejected = rejected.saturating_add(1);
      ("reject", "OPTIMIZER_REJECT_FORBIDDEN_LEVER")
    } else if !pattern_stack_gate_passed {
      approval_needed = approval_needed.saturating_add(1);
      (
        "recommend_with_approval",
        "OPTIMIZER_PATTERN_STACK_GATE_HOLD",
      )
    } else if channel == "prod" {
      approval_needed = approval_needed.saturating_add(1);
      (
        "recommend_with_approval",
        "OPTIMIZER_RECOMMEND_APPROVAL_REQUIRED_PROD",
      )
    } else {
      ("recommend", "OPTIMIZER_RECOMMEND")
    };
    let rec = OptimizationRecommendationEntry {
      org: org.clone(),
      rec_id: next_optimization_recommendation_id(),
      run_id: run_id.clone(),
      cand_id: cand_id.clone(),
      decision: normalize_optimization_recommendation_decision(Some(decision.to_string())),
      reasons_json: json!([{
        "code": reason_code,
        "msg": format!("decision for lever kind `{}`", lever_kind),
      }]),
      pr_id: None,
      approval_id: None,
      status: normalize_optimization_recommendation_status(Some("proposed".to_string())),
      created_ms: now_ms(),
      updated_ms: now_ms(),
    };
    {
      let mut guard = recommendation_store
        .write()
        .unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        optimization_recommendation_key(org.as_str(), rec.rec_id.as_str()),
        rec.clone(),
      );
    }
    recommendation_views.push(optimization_recommendation_view(&rec));
  }
  save_optimization_candidate_store(&candidate_store, runtime)?;
  save_optimization_evaluation_store(&evaluation_store, runtime)?;
  save_optimization_recommendation_store(&recommendation_store, runtime)?;

  let completed_run = OptimizationRunEntry {
    summary_json: json!({
      "candidate_count": candidate_views.len(),
      "recommendation_count": recommendation_views.len(),
      "rejected_count": rejected,
      "approval_required_count": approval_needed,
      "channel": channel,
      "pattern_stack_gate_pass": pattern_stack_gate_passed,
      "pattern_stack_decision": if pattern_stack_gate_passed { "accept" } else { "hold" },
      "pattern_stack": pattern_stack_bundle,
    }),
    status: "completed".to_string(),
    updated_ms: now_ms(),
    ..run_entry
  };
  {
    let store = get_optimization_run_global()?;
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      optimization_run_key(org.as_str(), run_id.as_str()),
      completed_run.clone(),
    );
    drop(guard);
    save_optimization_run_store(&store, runtime)?;
  }
  publish_supervisor_event(
    events,
    "optimizer.run.completed",
    "info",
    None,
    Some(run_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "run": optimization_run_view(&completed_run),
      "candidate_count": candidate_views.len(),
      "recommendation_count": recommendation_views.len(),
    }),
  );
  Ok(json!({
    "org": org,
    "deduped": false,
    "run": optimization_run_view(&completed_run),
    "candidates": candidate_views,
    "evaluations": evaluation_views,
    "recommendations": recommendation_views,
  }))
}

fn optimization_run_get_impl(request: OptimizationRunGetRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let run_id = request.run_id.trim().to_string();
  if run_id.is_empty() {
    anyhow::bail!("optimizer.run.get requires run_id");
  }
  let run = {
    let store = get_optimization_run_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&optimization_run_key(org.as_str(), run_id.as_str()))
      .cloned()
  };
  let recommendations = if run.is_some() {
    let store = get_optimization_recommendation_global()?;
    let mut rows: Vec<OptimizationRecommendationEntry> = {
      let guard = store.read().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .values()
        .filter(|row| row.org == org && row.run_id == run_id)
        .cloned()
        .collect()
    };
    rows.sort_by(|a, b| {
      b.updated_ms
        .cmp(&a.updated_ms)
        .then_with(|| a.rec_id.cmp(&b.rec_id))
    });
    rows
      .iter()
      .map(optimization_recommendation_view)
      .collect::<Vec<_>>()
  } else {
    Vec::new()
  };
  Ok(json!({
    "org": org,
    "run_id": run_id,
    "exists": run.is_some(),
    "run": run.as_ref().map(optimization_run_view),
    "recommendations": recommendations,
  }))
}

fn optimization_run_list_impl(request: OptimizationRunListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spec_filter = request
    .spec_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_optimization_run_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 10_000);
  let store = get_optimization_run_global()?;
  let mut rows: Vec<OptimizationRunEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        spec_filter
          .as_deref()
          .map(|value| row.spec_id == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.window_end_ms
      .cmp(&a.window_end_ms)
      .then_with(|| a.run_id.cmp(&b.run_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(optimization_run_view).collect::<Vec<_>>(),
  }))
}

