fn optimization_feedback_upsert_impl(
  request: OptimizationFeedbackUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let rec_id = request.rec_id.trim().to_string();
  if rec_id.is_empty() {
    anyhow::bail!("optimizer.feedback.upsert requires rec_id");
  }
  if request.observed_window_start_ms > request.observed_window_end_ms {
    anyhow::bail!(
      "optimizer.feedback.upsert requires observed_window_start_ms <= observed_window_end_ms"
    );
  }
  {
    let rec_store = get_optimization_recommendation_global()?;
    let guard = rec_store.read().unwrap_or_else(|e| e.into_inner());
    if !guard.by_key.contains_key(&optimization_recommendation_key(
      org.as_str(),
      rec_id.as_str(),
    )) {
      anyhow::bail!("optimization recommendation `{}` not found", rec_id);
    }
  }
  let mut observed_deltas_json = request.observed_deltas_json.unwrap_or_else(|| json!({}));
  if !observed_deltas_json.is_object() {
    observed_deltas_json = json!({});
  }
  let mut regret_json = request.regret_json.unwrap_or_else(|| json!({}));
  if !regret_json.is_object() {
    regret_json = json!({});
  }
  let entry = OptimizationFeedbackEntry {
    org: org.clone(),
    rec_id: rec_id.clone(),
    applied_change_id: request
      .applied_change_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    observed_window_start_ms: request.observed_window_start_ms,
    observed_window_end_ms: request.observed_window_end_ms,
    observed_deltas_json,
    regret_json,
    updated_ms: now_ms(),
  };
  let store = get_optimization_feedback_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      optimization_feedback_key(org.as_str(), rec_id.as_str()),
      entry.clone(),
    );
  }
  save_optimization_feedback_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "optimizer.feedback.upserted",
    "info",
    None,
    Some(rec_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "feedback": optimization_feedback_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "feedback": optimization_feedback_view(&entry),
  }))
}

