fn spec_registry_upsert_impl(
  request: SpecRegistryUpsertRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let spec_id = request
    .spec_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_spec_registry_id);
  let name = request.name.trim().to_string();
  let version = request.version.trim().to_string();
  let media_type = request.media_type.trim().to_string();
  let schema_ref_id = request.schema_ref_id.trim().to_string();
  let canonical_rules_ref_id = request.canonical_rules_ref_id.trim().to_string();
  if name.is_empty()
    || version.is_empty()
    || media_type.is_empty()
    || schema_ref_id.is_empty()
    || canonical_rules_ref_id.is_empty()
  {
    anyhow::bail!(
      "spec.registry.upsert requires name, version, media_type, schema_ref_id, canonical_rules_ref_id"
    );
  }
  let mut notes_json = request.notes_json.unwrap_or_else(|| json!({}));
  if !notes_json.is_object() {
    notes_json = json!({});
  }
  let status = normalize_spec_registry_status(request.status);
  let now = now_ms();
  let key = spec_registry_key(org.as_str(), spec_id.as_str());
  let entry = {
    let store = get_spec_registry_global()?;
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = SpecRegistryEntry {
      org: org.clone(),
      spec_id: spec_id.clone(),
      name,
      version,
      media_type,
      schema_ref_id,
      canonical_rules_ref_id,
      status,
      notes_json,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    drop(guard);
    save_spec_registry_store(&store, runtime)?;
    row
  };
  publish_supervisor_event(
    events,
    "interop.spec.upserted",
    "info",
    None,
    Some(spec_id.clone()),
    None,
    None,
    None,
    json!({
      "org": org,
      "spec": spec_registry_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "spec": spec_registry_view(&entry),
  }))
}

