fn spec_registry_list_impl(request: SpecRegistryListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_spec_registry_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let mut rows: Vec<SpecRegistryEntry> = {
    let store = get_spec_registry_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        name_filter
          .as_deref()
          .map(|value| {
            row.name.to_ascii_lowercase().contains(value)
              || row.media_type.to_ascii_lowercase().contains(value)
          })
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
      .then_with(|| a.spec_id.cmp(&b.spec_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(spec_registry_view).collect::<Vec<_>>(),
  }))
}

