fn segment_compact_impl(
  request: SegmentCompactRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  if request.window_start_ms > request.window_end_ms {
    anyhow::bail!("storage.segment.compact requires window_start_ms <= window_end_ms");
  }
  let segment_id = request
    .segment_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_segment_catalog_id);
  let kind = normalize_segment_kind(request.kind);
  let tier = normalize_segment_tier(request.tier);
  let format = normalize_segment_format(request.format);
  let ref_id = request.ref_id.trim().to_string();
  if ref_id.is_empty() {
    anyhow::bail!("storage.segment.compact requires ref_id");
  }
  let sha256 = request
    .sha256
    .trim()
    .trim_start_matches("sha256:")
    .to_ascii_lowercase();
  if sha256.is_empty() {
    anyhow::bail!("storage.segment.compact requires sha256");
  }
  let prev_hash = request
    .prev_hash
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.trim_start_matches("sha256:").to_ascii_lowercase());
  let signature_ref_id = request
    .signature_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let mut summary_json = request.summary_json.unwrap_or_else(|| json!({}));
  if !summary_json.is_object() {
    summary_json = json!({});
  }
  let key = segment_catalog_key(org.as_str(), segment_id.as_str());
  let now = now_ms();
  let store = get_segment_catalog_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = SegmentCatalogEntry {
      org: org.clone(),
      segment_id: segment_id.clone(),
      kind,
      tier,
      window_start_ms: request.window_start_ms,
      window_end_ms: request.window_end_ms,
      entry_count: request.entry_count.unwrap_or(0),
      bytes_raw: request.bytes_raw,
      bytes_compressed: request.bytes_compressed.unwrap_or(request.bytes_raw),
      format,
      ref_id,
      sha256,
      prev_hash,
      signature_ref_id,
      summary_json,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_segment_catalog_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "storage.segment.compacted",
    "info",
    None,
    Some(segment_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "segment": segment_catalog_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "segment": segment_catalog_view(&entry),
  }))
}

