fn dr_drill_start_impl(
  request: DrDrillStartRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let drill_id = request
    .drill_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_dr_drill_id);
  let runbook_id = request.runbook_id.trim().to_string();
  let scenario = request.scenario.trim().to_string();
  if runbook_id.is_empty() || scenario.is_empty() {
    anyhow::bail!("dr.drill.start requires runbook_id and scenario");
  }
  {
    let runbook_store = get_dr_runbook_global()?;
    let guard = runbook_store.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&dr_runbook_key(org.as_str(), runbook_id.as_str()))
    {
      anyhow::bail!("dr runbook `{}` not found", runbook_id);
    }
  }
  let mut summary_json = request.summary_json.unwrap_or_else(|| json!({}));
  if !summary_json.is_object() {
    summary_json = json!({});
  }
  let evidence_ref_id = request
    .evidence_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let created_by = request
    .created_by
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let now = now_ms();
  let key = dr_drill_key(org.as_str(), drill_id.as_str());
  let store = get_dr_drill_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = DrDrillEntry {
      org: org.clone(),
      drill_id: drill_id.clone(),
      runbook_id,
      scenario,
      status: "running".to_string(),
      started_ms: now,
      ended_ms: None,
      summary_json,
      evidence_ref_id,
      created_by,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_dr_drill_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "dr.drill.started",
    "warn",
    None,
    Some(drill_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "drill": dr_drill_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "drill": dr_drill_view(&entry),
  }))
}

fn dr_drill_update_impl(
  request: DrDrillUpdateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let drill_id = request.drill_id.trim().to_string();
  if drill_id.is_empty() {
    anyhow::bail!("dr.drill.update requires drill_id");
  }
  let status = request
    .status
    .as_deref()
    .map(|value| normalize_dr_drill_status(Some(value.to_string())));
  let mut summary_json = request.summary_json;
  if let Some(value) = summary_json.as_ref() {
    if !value.is_object() {
      anyhow::bail!("dr.drill.update summary_json must be an object");
    }
  }
  let evidence_ref_id = request
    .evidence_ref_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let store = get_dr_drill_global()?;
  let key = dr_drill_key(org.as_str(), drill_id.as_str());
  let now = now_ms();
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let row = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("dr drill `{}` not found", drill_id))?;
    if let Some(status) = status {
      row.status = status;
    }
    if let Some(value) = summary_json.take() {
      row.summary_json = value;
    }
    if let Some(value) = evidence_ref_id {
      row.evidence_ref_id = Some(value);
    }
    if let Some(ended_ms) = request.ended_ms {
      row.ended_ms = Some(ended_ms);
    } else if matches!(row.status.as_str(), "succeeded" | "failed" | "aborted")
      && row.ended_ms.is_none()
    {
      row.ended_ms = Some(now);
    }
    row.updated_ms = now;
    row.clone()
  };
  save_dr_drill_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "dr.drill.updated",
    if updated.status == "succeeded" {
      "info"
    } else if updated.status == "running" {
      "warn"
    } else {
      "error"
    },
    None,
    Some(drill_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "drill": dr_drill_view(&updated),
    }),
  );
  Ok(json!({
    "org": org,
    "drill": dr_drill_view(&updated),
  }))
}

fn dr_drill_get_impl(request: DrDrillGetRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let drill_id = request.drill_id.trim().to_string();
  if drill_id.is_empty() {
    anyhow::bail!("dr.drill.get requires drill_id");
  }
  let row = {
    let store = get_dr_drill_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&dr_drill_key(org.as_str(), drill_id.as_str()))
      .cloned()
  };
  Ok(json!({
    "org": org,
    "drill_id": drill_id,
    "exists": row.is_some(),
    "drill": row.as_ref().map(dr_drill_view),
  }))
}

fn dr_drill_list_impl(request: DrDrillListRequest) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  if request.from_ms.unwrap_or(0) > request.to_ms.unwrap_or(u128::MAX) {
    anyhow::bail!("dr.drill.list requires from_ms <= to_ms");
  }
  let runbook_filter = request
    .runbook_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_dr_drill_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let mut rows: Vec<DrDrillEntry> = {
    let store = get_dr_drill_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|row| row.org == org)
      .filter(|row| {
        runbook_filter
          .as_deref()
          .map(|value| row.runbook_id == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        status_filter
          .as_deref()
          .map(|value| row.status == *value)
          .unwrap_or(true)
      })
      .filter(|row| {
        request
          .from_ms
          .map(|value| row.started_ms >= value)
          .unwrap_or(true)
      })
      .filter(|row| {
        request
          .to_ms
          .map(|value| row.started_ms <= value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.started_ms
      .cmp(&a.started_ms)
      .then_with(|| a.drill_id.cmp(&b.drill_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "org": org,
    "count": rows.len(),
    "items": rows.iter().map(dr_drill_view).collect::<Vec<_>>(),
  }))
}

fn controlplane_slo_set_impl(
  request: ControlPlaneSloSetRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let slo_id = request
    .slo_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_controlplane_slo_id);
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("controlplane.slo.set requires name");
  }
  let mut scope_json = request.scope_json.unwrap_or_else(|| json!({}));
  if !scope_json.is_object() {
    scope_json = json!({});
  }
  let mut targets_json = request.targets_json.unwrap_or_else(|| json!({}));
  if !targets_json.is_object() {
    targets_json = json!({});
  }
  let status = normalize_controlplane_slo_status(request.status);
  let now = now_ms();
  let key = controlplane_slo_key(org.as_str(), slo_id.as_str());
  let store = get_controlplane_slo_global()?;
  let entry = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|row| row.created_ms)
      .unwrap_or(now);
    let row = ControlPlaneSloEntry {
      org: org.clone(),
      slo_id: slo_id.clone(),
      name,
      scope_json,
      targets_json,
      status,
      created_ms,
      updated_ms: now,
    };
    guard.by_key.insert(key, row.clone());
    row
  };
  save_controlplane_slo_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "controlplane.slo.updated",
    "info",
    None,
    Some(slo_id),
    None,
    None,
    None,
    json!({
      "org": org,
      "slo": controlplane_slo_view(&entry),
    }),
  );
  Ok(json!({
    "org": org,
    "slo": controlplane_slo_view(&entry),
  }))
}

