fn queue_priority_class(priority: u32) -> &'static str {
  if priority <= 20 {
    "p0"
  } else if priority <= 100 {
    "p1"
  } else {
    "p2"
  }
}

fn queue_policy_active_for_org(org: &str) -> Result<Option<QueuePolicyEntry>> {
  let store = get_queue_policy_global()?;
  let guard = store.read().unwrap_or_else(|e| e.into_inner());
  Ok(
    guard
      .by_key
      .values()
      .filter(|row| row.org == org && row.status == "active")
      .cloned()
      .max_by(|a, b| a.updated_ms.cmp(&b.updated_ms)),
  )
}

fn queue_job_org(job: &JobEntry) -> String {
  job
    .params_json
    .get("org")
    .and_then(Value::as_str)
    .map(|value| normalize_fed_org(Some(value.to_string())))
    .unwrap_or_else(|| "system".to_string())
}

fn queue_snapshot_for_org(
  job_store: &Arc<RwLock<JobStore>>,
  org: &str,
  include_kinds: bool,
) -> Value {
  let guard = job_store.read().unwrap_or_else(|e| e.into_inner());
  let mut total_queued = 0usize;
  let mut total_running = 0usize;
  let mut total_retry_wait = 0usize;
  let mut p0_queued = 0usize;
  let mut p1_queued = 0usize;
  let mut p2_queued = 0usize;
  let mut kind_counts: HashMap<String, usize> = HashMap::new();
  for job in guard.by_key.values() {
    if queue_job_org(job) != org {
      continue;
    }
    if include_kinds {
      *kind_counts.entry(job.kind.clone()).or_insert(0) += 1;
    }
    match job.state.as_str() {
      "queued" | "retry_wait" => {
        total_queued = total_queued.saturating_add(1);
        if job.state == "retry_wait" {
          total_retry_wait = total_retry_wait.saturating_add(1);
        }
        match queue_priority_class(job.priority) {
          "p0" => p0_queued = p0_queued.saturating_add(1),
          "p1" => p1_queued = p1_queued.saturating_add(1),
          _ => p2_queued = p2_queued.saturating_add(1),
        }
      }
      "running" => {
        total_running = total_running.saturating_add(1);
      }
      _ => {}
    }
  }
  let mut kinds = kind_counts.into_iter().collect::<Vec<_>>();
  kinds.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
  json!({
    "total_queued": total_queued,
    "total_running": total_running,
    "total_retry_wait": total_retry_wait,
    "queued_by_priority": {
      "p0": p0_queued,
      "p1": p1_queued,
      "p2": p2_queued,
    },
    "kind_counts": if include_kinds {
      Value::Array(kinds.into_iter().map(|(kind, count)| json!({"kind": kind, "count": count})).collect::<Vec<_>>())
    } else {
      Value::Array(Vec::new())
    },
  })
}

fn queue_backpressure_decision(
  org: &str,
  class: &str,
  job_store: &Arc<RwLock<JobStore>>,
) -> Result<Value> {
  let policy = queue_policy_active_for_org(org)?;
  let snapshot = queue_snapshot_for_org(job_store, org, false);
  let total_queued = snapshot
    .get("total_queued")
    .and_then(Value::as_u64)
    .unwrap_or(0) as usize;
  let total_running = snapshot
    .get("total_running")
    .and_then(Value::as_u64)
    .unwrap_or(0) as usize;
  let p0_queued = snapshot
    .get("queued_by_priority")
    .and_then(|value| value.get("p0"))
    .and_then(Value::as_u64)
    .unwrap_or(0) as usize;
  let p2_queued = snapshot
    .get("queued_by_priority")
    .and_then(|value| value.get("p2"))
    .and_then(Value::as_u64)
    .unwrap_or(0) as usize;
  let limits = policy
    .as_ref()
    .and_then(|row| row.backpressure_json.as_object())
    .cloned()
    .unwrap_or_default();
  let max_total_queued = limits
    .get("max_total_queued")
    .and_then(Value::as_u64)
    .unwrap_or(4000) as usize;
  let max_running = limits
    .get("max_running")
    .and_then(Value::as_u64)
    .unwrap_or(2000) as usize;
  let max_p2_queued = limits
    .get("max_p2_queued")
    .and_then(Value::as_u64)
    .unwrap_or(1000) as usize;
  let block_p2_if_p0_backlog_ge = limits
    .get("block_p2_if_p0_backlog_ge")
    .and_then(Value::as_u64)
    .unwrap_or(50) as usize;
  let mut reasons = Vec::new();
  if total_queued >= max_total_queued {
    reasons.push(format!(
      "QUEUE_BACKPRESSURE_TOTAL_QUEUED_LIMIT ({} >= {})",
      total_queued, max_total_queued
    ));
  }
  if total_running >= max_running {
    reasons.push(format!(
      "QUEUE_BACKPRESSURE_RUNNING_LIMIT ({} >= {})",
      total_running, max_running
    ));
  }
  if class == "p2" && p2_queued >= max_p2_queued {
    reasons.push(format!(
      "QUEUE_BACKPRESSURE_P2_LIMIT ({} >= {})",
      p2_queued, max_p2_queued
    ));
  }
  if class == "p2" && p0_queued >= block_p2_if_p0_backlog_ge {
    reasons.push(format!(
      "QUEUE_BACKPRESSURE_P0_PROTECTION ({} >= {})",
      p0_queued, block_p2_if_p0_backlog_ge
    ));
  }
  Ok(json!({
    "allow": reasons.is_empty(),
    "class": class,
    "org": org,
    "policy": policy.as_ref().map(queue_policy_view),
    "limits": {
      "max_total_queued": max_total_queued,
      "max_running": max_running,
      "max_p2_queued": max_p2_queued,
      "block_p2_if_p0_backlog_ge": block_p2_if_p0_backlog_ge,
    },
    "snapshot": snapshot,
    "reasons": reasons,
  }))
}

fn controlplane_queue_status_impl(
  request: QueueStatusRequest,
  job_store: &Arc<RwLock<JobStore>>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let include_kinds = request.include_kinds.unwrap_or(false);
  let snapshot = queue_snapshot_for_org(job_store, org.as_str(), include_kinds);
  let policy = queue_policy_active_for_org(org.as_str())?;
  Ok(json!({
    "org": org,
    "snapshot": snapshot,
    "active_policy": policy.as_ref().map(queue_policy_view),
    "decisions": {
      "p0": queue_backpressure_decision(org.as_str(), "p0", job_store)?,
      "p1": queue_backpressure_decision(org.as_str(), "p1", job_store)?,
      "p2": queue_backpressure_decision(org.as_str(), "p2", job_store)?,
    },
  }))
}

fn controlplane_backpressure_evaluate_impl(
  request: BackpressureEvaluateRequest,
  job_store: &Arc<RwLock<JobStore>>,
) -> Result<Value> {
  let org = normalize_fed_org(request.org);
  let class = queue_priority_class(request.priority.unwrap_or(default_job_priority()));
  queue_backpressure_decision(org.as_str(), class, job_store)
}

