fn normalize_policy_name(raw: &str, label: &str) -> Result<String> {
  let trimmed = raw.trim();
  if trimmed.is_empty() {
    anyhow::bail!("{} requires non-empty name", label);
  }
  if trimmed.len() > 128 {
    anyhow::bail!("{} name too long (max 128 chars)", label);
  }
  Ok(trimmed.to_string())
}

fn policy_list_matches_name_status(name: &str, status: &str, request: &PolicyListRequest) -> bool {
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_gateway_policy_status(Some(value.to_string())));
  name_filter
    .as_deref()
    .map(|prefix| name.to_ascii_lowercase().starts_with(prefix))
    .unwrap_or(true)
    && status_filter
      .as_deref()
      .map(|expected| status == expected)
      .unwrap_or(true)
}

fn auth_provider_upsert_impl(
  request: AuthProviderUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let provider_id = request
    .provider_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_auth_provider_id);
  let name = normalize_policy_name(request.name.as_str(), "auth.provider")?;
  let kind = request.kind.trim().to_ascii_lowercase();
  if kind.is_empty() {
    anyhow::bail!("auth.provider.create requires kind");
  }
  let now = now_ms();
  let key = auth_provider_key(namespace.as_str(), provider_id.as_str());
  let providers = get_auth_provider_global()?;
  let entry = {
    let mut guard = providers.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard.by_key.get(&key).map(|e| e.created_ms).unwrap_or(now);
    let entry = AuthProviderEntry {
      ns: namespace.clone(),
      provider_id: provider_id.clone(),
      name,
      kind,
      issuer: request
        .issuer
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      audiences_json: request.audiences_json.unwrap_or_else(|| json!([])),
      jwks_ref_id: request
        .jwks_ref_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      discovery_url: request
        .discovery_url
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string),
      cache_ttl_ms: request.cache_ttl_ms.unwrap_or(3_600_000).max(1_000),
      created_ms,
      updated_ms: now,
      status: normalize_gateway_policy_status(request.status),
    };
    guard.by_key.insert(key, entry.clone());
    entry
  };
  save_auth_provider_store(&providers, runtime)?;
  publish_supervisor_event(
    events,
    "auth.provider.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__gateway_policy__")),
    Some(provider_id),
    None,
    None,
    None,
    json!({ "provider": auth_provider_view(&entry) }),
  );
  Ok(json!({
    "ns": namespace,
    "provider": auth_provider_view(&entry),
  }))
}

