fn rate_limit_policy_upsert_impl(
  request: RateLimitPolicyUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  if request.unit_ms == 0 {
    anyhow::bail!("ratelimit.policy.create requires unit_ms > 0");
  }
  if request.limit == 0 {
    anyhow::bail!("ratelimit.policy.create requires limit > 0");
  }
  let rlp_id = request
    .rlp_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_rate_limit_policy_id);
  let now = now_ms();
  let key = rate_limit_policy_key(namespace.as_str(), rlp_id.as_str());
  let policies = get_rate_limit_policy_global()?;
  let entry = {
    let mut guard = policies.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard.by_key.get(&key).map(|e| e.created_ms).unwrap_or(now);
    let entry = RateLimitPolicyEntry {
      ns: namespace.clone(),
      rlp_id: rlp_id.clone(),
      name: normalize_policy_name(request.name.as_str(), "ratelimit.policy")?,
      key: request.key.trim().to_ascii_lowercase(),
      unit_ms: request.unit_ms,
      limit: request.limit,
      burst: request.burst.max(1),
      action: request
        .action
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("deny_429")
        .to_ascii_lowercase(),
      created_ms,
      updated_ms: now,
      status: normalize_gateway_policy_status(request.status),
    };
    guard.by_key.insert(key, entry.clone());
    entry
  };
  save_rate_limit_policy_store(&policies, runtime)?;
  publish_supervisor_event(
    events,
    "ratelimit.policy.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__gateway_policy__")),
    Some(rlp_id),
    None,
    None,
    None,
    json!({ "policy": rate_limit_policy_view(&entry) }),
  );
  Ok(json!({ "ns": namespace, "policy": rate_limit_policy_view(&entry) }))
}

