fn header_policy_disable_impl(
  request: PolicyByIdRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let hp_id = request.id.trim();
  if hp_id.is_empty() {
    anyhow::bail!("header.policy.disable requires id");
  }
  let policies = get_header_policy_global()?;
  let key = header_policy_key(namespace.as_str(), hp_id);
  let entry = {
    let mut guard = policies.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("header policy `{}` not found", hp_id))?;
    entry.status = "disabled".to_string();
    entry.updated_ms = now_ms();
    entry.clone()
  };
  save_header_policy_store(&policies, runtime)?;
  publish_supervisor_event(
    events,
    "header.policy.disabled",
    "warn",
    Some(scoped_logical_id(namespace.as_str(), "__gateway_policy__")),
    Some(hp_id.to_string()),
    None,
    None,
    None,
    json!({ "policy": header_policy_view(&entry) }),
  );
  Ok(json!({ "ns": namespace, "policy": header_policy_view(&entry) }))
}

fn route_policy_attach_impl(
  request: RoutePolicyAttachRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let route_id = request.route_id.trim().to_string();
  if route_id.is_empty() {
    anyhow::bail!("route.policy.attach requires route_id");
  }
  if let Some(id) = request
    .auth_policy_id
    .as_deref()
    .map(str::trim)
    .filter(|v| !v.is_empty())
  {
    let policies = get_auth_policy_global()?;
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&auth_policy_key(namespace.as_str(), id))
    {
      anyhow::bail!("route.policy.attach unknown auth_policy_id `{}`", id);
    }
  }
  if let Some(id) = request
    .access_policy_id
    .as_deref()
    .map(str::trim)
    .filter(|v| !v.is_empty())
  {
    let policies = get_access_policy_global()?;
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&access_policy_key(namespace.as_str(), id))
    {
      anyhow::bail!("route.policy.attach unknown access_policy_id `{}`", id);
    }
  }
  if let Some(id) = request
    .rlp_id
    .as_deref()
    .map(str::trim)
    .filter(|v| !v.is_empty())
  {
    let policies = get_rate_limit_policy_global()?;
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&rate_limit_policy_key(namespace.as_str(), id))
    {
      anyhow::bail!("route.policy.attach unknown rlp_id `{}`", id);
    }
  }
  if let Some(id) = request
    .waf_id
    .as_deref()
    .map(str::trim)
    .filter(|v| !v.is_empty())
  {
    let policies = get_waf_policy_global()?;
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&waf_policy_key(namespace.as_str(), id))
    {
      anyhow::bail!("route.policy.attach unknown waf_id `{}`", id);
    }
  }
  if let Some(id) = request
    .hp_id
    .as_deref()
    .map(str::trim)
    .filter(|v| !v.is_empty())
  {
    let policies = get_header_policy_global()?;
    let guard = policies.read().unwrap_or_else(|e| e.into_inner());
    if !guard
      .by_key
      .contains_key(&header_policy_key(namespace.as_str(), id))
    {
      anyhow::bail!("route.policy.attach unknown hp_id `{}`", id);
    }
  }
  let attachment = RoutePolicyAttachmentEntry {
    ns: namespace.clone(),
    route_id: route_id.clone(),
    auth_policy_id: request
      .auth_policy_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    access_policy_id: request
      .access_policy_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    rlp_id: request
      .rlp_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    waf_id: request
      .waf_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    hp_id: request
      .hp_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    updated_ms: now_ms(),
  };
  let attachments = get_route_policy_attachment_global()?;
  {
    let mut guard = attachments.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      route_policy_attachment_key(namespace.as_str(), route_id.as_str()),
      attachment.clone(),
    );
  }
  save_route_policy_attachment_store(&attachments, runtime)?;
  publish_supervisor_event(
    events,
    "route.policy.attached",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__gateway_route__")),
    Some(route_id),
    None,
    None,
    None,
    json!({ "attachment": route_policy_attachment_view(&attachment) }),
  );
  Ok(json!({
    "ns": namespace,
    "attachment": route_policy_attachment_view(&attachment),
  }))
}

fn route_policy_get_impl(request: RoutePolicyGetRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let route_id = request.route_id.trim();
  if route_id.is_empty() {
    anyhow::bail!("route.policy.get requires route_id");
  }
  let attachments = get_route_policy_attachment_global()?;
  let key = route_policy_attachment_key(namespace.as_str(), route_id);
  let guard = attachments.read().unwrap_or_else(|e| e.into_inner());
  let attachment = guard.by_key.get(&key).cloned();
  Ok(json!({
    "ns": namespace,
    "route_id": route_id,
    "exists": attachment.is_some(),
    "attachment": attachment.as_ref().map(route_policy_attachment_view),
  }))
}

fn gateway_decision_rollup_upsert_impl(
  request: GatewayDecisionRollupUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let route_id = request.route_id.trim().to_string();
  let code = request.code.trim().to_ascii_uppercase();
  if route_id.is_empty() || code.is_empty() {
    anyhow::bail!("gateway.decision.rollup.upsert requires route_id and code");
  }
  let ts_ms = request.ts_ms.unwrap_or_else(now_ms) / 60_000 * 60_000;
  let key =
    gateway_decision_rollup_key(namespace.as_str(), route_id.as_str(), ts_ms, code.as_str());
  let count_inc = request.count.unwrap_or(1).max(1);
  let rollups = get_gateway_decision_rollup_global()?;
  let updated = {
    let mut guard = rollups.write().unwrap_or_else(|e| e.into_inner());
    let mut entry = guard
      .by_key
      .get(&key)
      .cloned()
      .unwrap_or(GatewayDecisionRollupEntry {
        ns: namespace.clone(),
        route_id: route_id.clone(),
        ts_ms,
        code: code.clone(),
        count: 0,
      });
    entry.count = entry.count.saturating_add(count_inc);
    guard.by_key.insert(key, entry.clone());
    entry
  };
  save_gateway_decision_rollup_store(&rollups, runtime)?;
  Ok(json!({
    "ns": namespace,
    "rollup": gateway_decision_rollup_view(&updated),
  }))
}

fn gateway_decision_stats_impl(
  request: GatewayDecisionStatsRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let route_filter = request
    .route_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let code_filter = request
    .code
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_uppercase());
  let since_ms = request.since_ms.unwrap_or(0);
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let rollups = get_gateway_decision_rollup_global()?;
  let mut rows: Vec<GatewayDecisionRollupEntry> = {
    let guard = rollups.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| entry.ts_ms >= since_ms)
      .filter(|entry| {
        route_filter
          .as_deref()
          .map(|route_id| entry.route_id == route_id)
          .unwrap_or(true)
      })
      .filter(|entry| {
        code_filter
          .as_deref()
          .map(|code| entry.code == code)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.ts_ms
      .cmp(&a.ts_ms)
      .then_with(|| a.route_id.cmp(&b.route_id))
      .then_with(|| a.code.cmp(&b.code))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  let total_count = rows
    .iter()
    .fold(0u64, |acc, row| acc.saturating_add(row.count));
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "total_decisions": total_count,
    "items": rows.iter().map(gateway_decision_rollup_view).collect::<Vec<_>>(),
  }))
}

fn policy_reason(code: &str, msg: String, meta: Value) -> Value {
  json!({
    "code": code,
    "msg": msg,
    "meta": meta,
  })
}

fn policy_reason_from_error(error: &str) -> Value {
  let normalized = error.to_ascii_lowercase();
  if normalized.contains("unmanaged path exec") {
    return policy_reason(
      "COMPLIANCE_PATH_EXEC_DENY",
      "prod channel blocks unmanaged path exec".to_string(),
      json!({ "error": error }),
    );
  }
  if normalized.contains("attestation") {
    return policy_reason(
      "ATTESTATION_MISSING_OR_INVALID",
      "managed exec requires a valid pnix.exec.bundle attestation".to_string(),
      json!({ "error": error }),
    );
  }
  if normalized.contains("runtime alias mismatch") {
    return policy_reason(
      "RUNTIME_ALIAS_MISMATCH",
      "exec runtime alias does not match compliance requirements".to_string(),
      json!({ "error": error }),
    );
  }
  if normalized.contains("composed verdict") {
    return policy_reason(
      "COMPOSED_VERDICT_MISSING",
      "missing pass composed verdict for runtime/app inputs".to_string(),
      json!({ "error": error }),
    );
  }
  if normalized.contains("processspec") || normalized.contains("parse failed") {
    return policy_reason(
      "PROCESS_SPEC_INVALID",
      "provided process spec is invalid".to_string(),
      json!({ "error": error }),
    );
  }
  policy_reason(
    "ADMISSION_DENY",
    "admission policy rejected request".to_string(),
    json!({ "error": error }),
  )
}

fn policy_eval_log_view(entry: &PolicyEvalLogEntry) -> Value {
  json!({
    "ns": entry.ns,
    "eval_id": entry.eval_id,
    "ts_ms": entry.ts_ms,
    "channel": entry.channel,
    "release_id": entry.release_id,
    "target": entry.target,
    "subject_kind": entry.subject_kind,
    "subject_id": entry.subject_id,
    "decision": entry.decision,
    "reasons": entry.reasons_json,
    "warnings": entry.warnings_json,
    "input_hash": entry.input_hash,
    "output_hash": entry.output_hash,
    "invocation_id": entry.invocation_id,
    "change_id": entry.change_id,
    "git_commit": entry.git_commit,
  })
}

fn policy_eval_list_impl(request: PolicyEvalListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let channel_filter = request
    .channel
    .map(normalize_channel)
    .transpose()?
    .map(|value| value.to_ascii_lowercase());
  let target_filter = request
    .target
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let decision_filter = request
    .decision
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let since_ms = request.since_ms.unwrap_or(0);
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_policy_eval_log_global()?;
  let mut rows: Vec<PolicyEvalLogEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| entry.ts_ms >= since_ms)
      .filter(|entry| {
        channel_filter
          .as_deref()
          .map(|channel| {
            entry
              .channel
              .as_deref()
              .map(|value| value.eq_ignore_ascii_case(channel))
              .unwrap_or(false)
          })
          .unwrap_or(true)
      })
      .filter(|entry| {
        target_filter
          .as_deref()
          .map(|target| entry.target == *target)
          .unwrap_or(true)
      })
      .filter(|entry| {
        decision_filter
          .as_deref()
          .map(|decision| entry.decision.eq_ignore_ascii_case(decision))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.ts_ms
      .cmp(&a.ts_ms)
      .then_with(|| a.target.cmp(&b.target))
      .then_with(|| a.eval_id.cmp(&b.eval_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(policy_eval_log_view).collect::<Vec<_>>(),
  }))
}

fn kpi_value_count(value: &Value) -> u64 {
  value
    .get("count")
    .and_then(Value::as_u64)
    .or_else(|| {
      value
        .get("items")
        .and_then(Value::as_array)
        .map(|values| values.len() as u64)
    })
    .or_else(|| {
      value
        .get("changes")
        .and_then(Value::as_array)
        .map(|values| values.len() as u64)
    })
    .unwrap_or(0)
}

fn value_string_set(value: Option<&Value>) -> HashSet<String> {
  value
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(str::to_string)
        .collect::<HashSet<_>>()
    })
    .unwrap_or_default()
}

fn sorted_string_values(values: &HashSet<String>) -> Vec<String> {
  let mut rows = values.iter().cloned().collect::<Vec<_>>();
  rows.sort();
  rows
}

fn scope_backend(scope: &Value) -> Option<String> {
  scope
    .get("backend")
    .and_then(Value::as_str)
    .or_else(|| {
      scope
        .get("target")
        .and_then(Value::as_object)
        .and_then(|target| target.get("backend"))
        .and_then(Value::as_str)
    })
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
}

fn scope_string_allowlist(scope: &Value, key: &str) -> HashSet<String> {
  value_string_set(scope.get(key))
}

fn scope_path_allowlist(scope: &Value) -> Vec<String> {
  let mut values = scope
    .get("fs_paths")
    .and_then(Value::as_array)
    .map(|rows| {
      rows
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  values.sort();
  values.dedup();
  values
}

fn path_allowed_by_prefix(path: &str, prefixes: &[String]) -> bool {
  if prefixes.is_empty() {
    return true;
  }
  prefixes.iter().any(|prefix| {
    if prefix == "*" {
      return true;
    }
    let normalized = prefix.trim();
    !normalized.is_empty() && path.starts_with(normalized)
  })
}

fn intersect_optional_allowlists(
  mut base: HashSet<String>,
  filters: &[HashSet<String>],
) -> HashSet<String> {
  for filter in filters {
    if filter.is_empty() {
      continue;
    }
    base = base
      .intersection(filter)
      .map(|entry| entry.to_string())
      .collect::<HashSet<_>>();
  }
  base
}

fn min_positive_u64(values: &[Option<u64>], fallback: u64) -> u64 {
  let mut selected = None::<u64>;
  for value in values.iter().flatten().copied() {
    if value == 0 {
      continue;
    }
    selected = Some(selected.map(|current| current.min(value)).unwrap_or(value));
  }
  selected.unwrap_or(fallback)
}

fn consent_scope_limit(scope: &Value, key: &str) -> Option<u64> {
  scope
    .get("limits")
    .and_then(|limits| limits.get(key))
    .and_then(Value::as_u64)
}

fn compute_consent_compile_runtime(consent: &Value, now: u128) -> Value {
  let request_id = consent
    .get("request_id")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| format!("ccr_{now}"));
  let template_id = consent
    .get("template_id")
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "ct_inline_breakglass".to_string());
  let requested_scope = consent
    .get("requested_scope")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let template_scope = consent
    .get("template_scope")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let runtime_policy = consent
    .get("runtime_policy")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let backend_spec = consent
    .get("backend_spec")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let enforcement_caps = consent
    .get("enforcement_caps")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let quota = consent.get("quota").cloned().unwrap_or_else(|| json!({}));
  let requested_grant_spec = consent
    .get("requested_grant_spec")
    .cloned()
    .unwrap_or_else(|| json!({}));

  let requested_backend = scope_backend(&requested_scope);
  let template_backend = scope_backend(&template_scope);
  let mut out_of_scope_fields = Vec::<String>::new();
  if let (Some(req), Some(tpl)) = (requested_backend.as_deref(), template_backend.as_deref()) {
    if tpl != "*" && req != tpl {
      out_of_scope_fields.push(format!("requested_scope.backend={req}"));
    }
  }

  let requested_methods = scope_string_allowlist(&requested_scope, "methods");
  let template_methods = scope_string_allowlist(&template_scope, "methods");
  for method in &requested_methods {
    if !template_methods.is_empty() && !template_methods.contains(method) {
      out_of_scope_fields.push(format!("requested_scope.methods={method}"));
    }
  }

  let requested_hosts = scope_string_allowlist(&requested_scope, "net_hosts");
  let template_hosts = scope_string_allowlist(&template_scope, "net_hosts");
  for host in &requested_hosts {
    if !template_hosts.is_empty() && !template_hosts.contains(host) {
      out_of_scope_fields.push(format!("requested_scope.net_hosts={host}"));
    }
  }

  let requested_paths = scope_path_allowlist(&requested_scope);
  let template_paths = scope_path_allowlist(&template_scope);
  for path in &requested_paths {
    if !path_allowed_by_prefix(path, &template_paths) {
      out_of_scope_fields.push(format!("requested_scope.fs_paths={path}"));
    }
  }

  if !out_of_scope_fields.is_empty() {
    let additional_consent = json!({
      "required": true,
      "diff_summary": format!("{} out-of-scope additions require explicit consent", out_of_scope_fields.len()),
      "suggested_ttl_seconds": 300,
    });
    return json!({
      "decision": "out_of_scope",
      "result": {
        "apiVersion": PUCK_API_VERSION_V01,
        "kind": "ConsentCompileOutOfScope",
        "request_id": request_id,
        "ok": false,
        "template_id": template_id,
        "out_of_scope_fields": out_of_scope_fields,
        "additional_consent": additional_consent,
      },
      "cache_entry": Value::Null,
      "audit_record": Value::Null,
      "compile_fingerprint": Value::Null,
      "grant_id": Value::Null,
      "grant_spec": Value::Null,
      "granted_scope": Value::Null,
    });
  }

  let runtime_methods = scope_string_allowlist(&runtime_policy, "methods");
  let backend_methods = scope_string_allowlist(&backend_spec, "methods");
  let caps_methods = scope_string_allowlist(&enforcement_caps, "methods");
  let granted_methods = intersect_optional_allowlists(
    requested_methods.clone(),
    &[
      template_methods,
      runtime_methods,
      backend_methods,
      caps_methods,
    ],
  );

  let runtime_hosts = scope_string_allowlist(&runtime_policy, "net_hosts");
  let backend_hosts = scope_string_allowlist(&backend_spec, "net_hosts");
  let caps_hosts = scope_string_allowlist(&enforcement_caps, "net_hosts");
  let granted_hosts = intersect_optional_allowlists(
    requested_hosts.clone(),
    &[template_hosts, runtime_hosts, backend_hosts, caps_hosts],
  );

  let runtime_paths = scope_path_allowlist(&runtime_policy);
  let backend_paths = scope_path_allowlist(&backend_spec);
  let cap_paths = scope_path_allowlist(&enforcement_caps);
  let mut granted_paths = requested_paths
    .iter()
    .filter(|path| path_allowed_by_prefix(path, &template_paths))
    .cloned()
    .collect::<Vec<_>>();
  granted_paths = granted_paths
    .into_iter()
    .filter(|path| path_allowed_by_prefix(path, &runtime_paths))
    .filter(|path| path_allowed_by_prefix(path, &backend_paths))
    .filter(|path| path_allowed_by_prefix(path, &cap_paths))
    .collect::<Vec<_>>();

  let mut blockers = Vec::<String>::new();
  if !requested_methods.is_empty() && granted_methods.is_empty() {
    blockers.push("RuntimePolicyDenied:methods".to_string());
  }
  if !requested_hosts.is_empty() && granted_hosts.is_empty() {
    blockers.push("RuntimePolicyDenied:net_hosts".to_string());
  }
  if !requested_paths.is_empty() && granted_paths.is_empty() {
    blockers.push("RuntimePolicyDenied:fs_paths".to_string());
  }

  if !blockers.is_empty() {
    return json!({
      "decision": "policy_denied",
      "result": {
        "apiVersion": PUCK_API_VERSION_V01,
        "kind": "ConsentCompilePolicyDenied",
        "request_id": request_id,
        "ok": false,
        "template_id": template_id,
        "blockers": blockers,
      },
      "cache_entry": Value::Null,
      "audit_record": Value::Null,
      "compile_fingerprint": Value::Null,
      "grant_id": Value::Null,
      "grant_spec": Value::Null,
      "granted_scope": Value::Null,
    });
  }

  let granted_scope = json!({
    "backend": requested_backend.or(template_backend).unwrap_or_else(|| "runtime/default".to_string()),
    "methods": sorted_string_values(&granted_methods),
    "net_hosts": sorted_string_values(&granted_hosts),
    "fs_paths": granted_paths,
  });
  let ttl_seconds = min_positive_u64(
    &[
      requested_grant_spec
        .get("ttl_seconds")
        .and_then(Value::as_u64),
      consent_scope_limit(&template_scope, "ttl_seconds"),
      quota.get("ttl_seconds").and_then(Value::as_u64),
      Some(120),
    ],
    120,
  );
  let max_net_req_per_min = min_positive_u64(
    &[
      requested_grant_spec
        .get("max_net_req_per_min")
        .and_then(Value::as_u64),
      consent_scope_limit(&template_scope, "req_per_min"),
      quota.get("max_net_req_per_min").and_then(Value::as_u64),
      Some(30),
    ],
    30,
  );
  let max_fs_writes_per_min = min_positive_u64(
    &[
      requested_grant_spec
        .get("max_fs_writes_per_min")
        .and_then(Value::as_u64),
      consent_scope_limit(&template_scope, "writes_per_min"),
      quota.get("max_fs_writes_per_min").and_then(Value::as_u64),
      Some(20),
    ],
    20,
  );
  let grant_spec = json!({
    "ttl_seconds": ttl_seconds,
    "max_net_req_per_min": max_net_req_per_min,
    "max_fs_writes_per_min": max_fs_writes_per_min,
  });

  let template_hash = consent
    .get("template_hash")
    .cloned()
    .unwrap_or_else(|| json!(sha256_hex(&template_scope)));
  let policy_hash = consent
    .get("policy_hash")
    .cloned()
    .unwrap_or_else(|| json!(sha256_hex(&runtime_policy)));
  let backend_spec_hash = consent
    .get("backend_spec_hash")
    .cloned()
    .unwrap_or_else(|| json!(sha256_hex(&backend_spec)));
  let request_scope_hash = json!(sha256_hex(&requested_scope));
  let granted_scope_hash = json!(sha256_hex(&granted_scope));
  let compile_fingerprint = sha256_hex(&json!({
    "template_hash": template_hash,
    "policy_hash": policy_hash,
    "backend_spec_hash": backend_spec_hash,
    "request_scope_hash": request_scope_hash,
    "compiler_version": CONSENT_COMPILER_VERSION_V01,
  }));
  let grant_id = format!(
    "gr_{}",
    compile_fingerprint
      .trim_start_matches("sha256:")
      .chars()
      .take(12)
      .collect::<String>()
  );
  let cache_key = format!(
    "{}:{}:{}:{}",
    template_id,
    granted_scope
      .get("backend")
      .and_then(Value::as_str)
      .unwrap_or("runtime/default"),
    granted_scope
      .get("methods")
      .and_then(Value::as_array)
      .and_then(|rows| rows.first())
      .and_then(Value::as_str)
      .unwrap_or("*"),
    granted_scope
      .get("net_hosts")
      .and_then(Value::as_array)
      .and_then(|rows| rows.first())
      .and_then(Value::as_str)
      .unwrap_or("*")
  );
  let cache_entry = json!({
    "apiVersion": PUCK_API_VERSION_V01,
    "kind": "ConsentCompileCacheEntry",
    "cache_key": cache_key,
    "template_id": template_id,
    "scope_hash": granted_scope_hash,
    "policy_hash": policy_hash,
    "expires_at_ms": now.saturating_add((ttl_seconds as u128).saturating_mul(1000)),
    "compile_fingerprint": compile_fingerprint,
  });
  let audit_record = json!({
    "apiVersion": PUCK_API_VERSION_V01,
    "kind": "ConsentGrantAuditRecord",
    "effect_id": format!("ef_runtime_call_{}", now),
    "template_id": template_id,
    "request_scope": requested_scope,
    "granted_scope": granted_scope,
    "grant_id": grant_id,
    "compile_fingerprint": compile_fingerprint,
    "policy_hash": policy_hash,
    "template_hash": template_hash,
    "request_scope_hash": request_scope_hash,
    "granted_scope_hash": granted_scope_hash,
    "compiler_version": CONSENT_COMPILER_VERSION_V01,
  });
  let result = json!({
    "apiVersion": PUCK_API_VERSION_V01,
    "kind": "ConsentCompileGrantResult",
    "request_id": request_id,
    "ok": true,
    "template_id": template_id,
    "granted_scope": granted_scope,
    "grant_spec": grant_spec,
  });
  json!({
    "decision": "granted",
    "result": result,
    "cache_entry": cache_entry,
    "audit_record": audit_record,
    "compile_fingerprint": compile_fingerprint,
    "grant_id": grant_id,
    "grant_spec": grant_spec,
    "granted_scope": granted_scope,
  })
}

fn normalize_pattern_stage(pattern_id: &str, row: Option<&Value>) -> String {
  if let Some(stage) = row
    .and_then(|value| value.get("stage"))
    .and_then(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
  {
    let stage = stage.to_ascii_lowercase();
    if stage == "stage0" || stage == "0" {
      return "stage0".to_string();
    }
    if stage == "stage1" || stage == "1" {
      return "stage1".to_string();
    }
    if stage == "stage2" || stage == "2" {
      return "stage2".to_string();
    }
  }
  let lowered = pattern_id.to_ascii_lowercase();
  if lowered.contains("clamp") || lowered.contains("normalize") {
    return "stage0".to_string();
  }
  if lowered.contains("strategy") || lowered.contains("switch") {
    return "stage1".to_string();
  }
  "stage2".to_string()
}

fn optimize_pattern_stack_bundle(
  universe: Vec<String>,
  patterns: Vec<Value>,
  pattern_costs_json: Option<&Value>,
  min_coverage: f64,
  min_support_count: Option<u64>,
  min_generalization_score: Option<f64>,
) -> Value {
  let mut universe_sorted = universe
    .iter()
    .map(|value| value.trim())
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .collect::<Vec<_>>();
  universe_sorted.sort();
  universe_sorted.dedup();
  let universe_set = universe_sorted.iter().cloned().collect::<HashSet<_>>();

  let costs_by_id = pattern_costs_json
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter_map(|item| {
          let pattern_id = item
            .get("pattern_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())?;
          let weight = item.get("weight").and_then(Value::as_f64).unwrap_or(1.0);
          Some((pattern_id.to_string(), weight.max(0.0001)))
        })
        .collect::<HashMap<_, _>>()
    })
    .unwrap_or_default();

  let mut rows = Vec::<(
    String,
    HashSet<String>,
    HashSet<String>,
    f64,
    u64,
    f64,
    Value,
  )>::new();
  for pattern in patterns {
    let pattern_id = pattern
      .get("pattern_id")
      .and_then(Value::as_str)
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    let Some(pattern_id) = pattern_id else {
      continue;
    };
    let fix_cover = value_string_set(pattern.get("fix_cover"));
    let mask_cover = value_string_set(pattern.get("mask_cover"));
    let weight = pattern
      .get("weight")
      .and_then(Value::as_f64)
      .or_else(|| costs_by_id.get(pattern_id.as_str()).copied())
      .unwrap_or(1.0)
      .max(0.0001);
    let support_count = pattern
      .get("support_count")
      .and_then(Value::as_u64)
      .unwrap_or(0);
    let generalization_score = pattern
      .get("generalization_score")
      .and_then(Value::as_f64)
      .unwrap_or(0.0)
      .max(0.0);
    rows.push((
      pattern_id,
      fix_cover,
      mask_cover,
      weight,
      support_count,
      generalization_score,
      pattern,
    ));
  }

  let mut uncovered = universe_set.clone();
  let mut selected = Vec::<String>::new();
  let mut selected_rows = Vec::<(
    String,
    HashSet<String>,
    HashSet<String>,
    f64,
    u64,
    f64,
    Value,
  )>::new();
  let mut used = HashSet::<String>::new();
  while !uncovered.is_empty() {
    let best = rows
      .iter()
      .filter(|(pattern_id, _, _, _, _, _, _)| !used.contains(pattern_id.as_str()))
      .map(
        |(pattern_id, fix_cover, _mask_cover, weight, _support, _generalization, row)| {
          let newly = fix_cover.intersection(&uncovered).count() as f64;
          let score = if newly > 0.0 { newly / *weight } else { 0.0 };
          (
            pattern_id.clone(),
            newly,
            score,
            fix_cover.clone(),
            *weight,
            row.clone(),
          )
        },
      )
      .max_by(|a, b| {
        a.2
          .partial_cmp(&b.2)
          .unwrap_or(std::cmp::Ordering::Equal)
          .then_with(|| a.0.cmp(&b.0))
      });
    let Some((pattern_id, newly, score, fix_cover, _weight, _row)) = best else {
      break;
    };
    if score <= 0.0 || newly <= 0.0 {
      break;
    }
    used.insert(pattern_id.clone());
    uncovered = uncovered
      .difference(&fix_cover)
      .map(|entry| entry.to_string())
      .collect::<HashSet<_>>();
    if let Some((_, fix, mask, weight, support, generalization, row)) = rows
      .iter()
      .find(|(id, _, _, _, _, _, _)| id == pattern_id.as_str())
      .cloned()
    {
      selected_rows.push((
        pattern_id.clone(),
        fix,
        mask,
        weight,
        support,
        generalization,
        row,
      ));
    }
    selected.push(pattern_id);
  }

  let selected_set = selected.iter().cloned().collect::<HashSet<_>>();
  let covered_count = universe_set
    .difference(&uncovered)
    .collect::<HashSet<_>>()
    .len() as f64;
  let covered_ratio = if universe_set.is_empty() {
    1.0
  } else {
    covered_count / (universe_set.len() as f64)
  };
  let total_weight = selected_rows
    .iter()
    .map(|(_, _, _, weight, _, _, _)| *weight)
    .sum::<f64>();

  let mut stage0 = Vec::<String>::new();
  let mut stage1 = Vec::<String>::new();
  let mut stage2 = Vec::<String>::new();
  let mut seen = HashSet::<String>::new();
  let mut dedupe_removed = 0u64;
  let mut fix_total = 0u64;
  let mut mask_total = 0u64;
  let mut selected_min_support_count: Option<u64> = None;
  let mut selected_min_generalization: Option<f64> = None;
  for (pattern_id, fix_cover, mask_cover, _weight, support_count, generalization_score, row) in
    &selected_rows
  {
    if !seen.insert(pattern_id.clone()) {
      dedupe_removed = dedupe_removed.saturating_add(1);
      continue;
    }
    fix_total = fix_total.saturating_add(fix_cover.len() as u64);
    mask_total = mask_total.saturating_add(mask_cover.len() as u64);
    selected_min_support_count = Some(match selected_min_support_count {
      Some(current) => current.min(*support_count),
      None => *support_count,
    });
    selected_min_generalization = Some(match selected_min_generalization {
      Some(current) => current.min(*generalization_score),
      None => *generalization_score,
    });
    match normalize_pattern_stage(pattern_id.as_str(), Some(row)).as_str() {
      "stage0" => stage0.push(pattern_id.clone()),
      "stage1" => stage1.push(pattern_id.clone()),
      _ => stage2.push(pattern_id.clone()),
    }
  }
  stage0.sort();
  stage1.sort();
  stage2.sort();

  let masking_entropy = if fix_total + mask_total == 0 {
    0.0
  } else {
    (mask_total as f64) / ((fix_total + mask_total) as f64)
  };
  let coverage_gate = covered_ratio >= min_coverage.max(0.0).min(1.0);
  let support_count_threshold = min_support_count.unwrap_or(0);
  let generalization_threshold = min_generalization_score.unwrap_or(0.0).max(0.0);
  let support_count_gate = selected_min_support_count
    .map(|value| value >= support_count_threshold)
    .unwrap_or(true);
  let generalization_gate = selected_min_generalization
    .map(|value| value >= generalization_threshold)
    .unwrap_or(true);
  let regression_gate = true;
  let exploration_gate = true;
  let determinism_gate = true;
  let gate_pass = coverage_gate
    && support_count_gate
    && generalization_gate
    && regression_gate
    && exploration_gate
    && determinism_gate;

  json!({
    "apiVersion": FREECAT_API_VERSION_V01,
    "kind": "PatternStackOptimizationResult",
    "coverage_matrix": {
      "apiVersion": FREECAT_API_VERSION_V01,
      "kind": "PatternCoverageMatrix",
      "universe": universe_sorted.clone(),
      "patterns": rows.iter().map(|(pattern_id, fix_cover, mask_cover, _, support_count, generalization_score, _)| {
        json!({
          "pattern_id": pattern_id,
          "fix_cover": sorted_string_values(fix_cover),
          "mask_cover": sorted_string_values(mask_cover),
          "support_count": support_count,
          "generalization_score": generalization_score,
        })
      }).collect::<Vec<_>>(),
    },
    "set_cover_request": {
      "apiVersion": FREECAT_API_VERSION_V01,
      "kind": "PatternSetCoverRequest",
      "universe": universe_sorted.clone(),
      "pattern_costs": rows.iter().map(|(pattern_id, _, _, weight, _, _, _)| {
        json!({"pattern_id": pattern_id, "weight": weight})
      }).collect::<Vec<_>>(),
    },
    "set_cover_result": {
      "apiVersion": FREECAT_API_VERSION_V01,
      "kind": "PatternSetCoverResult",
      "selected_patterns": selected,
      "covered_ratio": covered_ratio,
      "total_weight": total_weight,
    },
    "normalized_stack": {
      "apiVersion": FREECAT_API_VERSION_V01,
      "kind": "PatternNormalizedStack",
      "stages": {
        "stage0": stage0,
        "stage1": stage1,
        "stage2": stage2,
      },
      "conflicts_resolved": dedupe_removed,
    },
    "gate_result": {
      "apiVersion": FREECAT_API_VERSION_V01,
      "kind": "PatternStackGateResult",
      "coverage_gate": coverage_gate,
      "support_count_gate": support_count_gate,
      "generalization_gate": generalization_gate,
      "regression_gate": regression_gate,
      "exploration_gate": exploration_gate,
      "determinism_gate": determinism_gate,
      "masking_entropy": masking_entropy,
      "minimum_support_count": selected_min_support_count,
      "minimum_generalization_score": selected_min_generalization,
      "threshold_support_count": support_count_threshold,
      "threshold_generalization_score": generalization_threshold,
    },
    "decision": if gate_pass { "accept" } else { "hold" },
    "selected_pattern_count": selected_set.len(),
  })
}

fn pattern_stack_gate_pass(bundle: &Value) -> bool {
  let gate = bundle
    .get("gate_result")
    .or_else(|| bundle.get("pattern_stack_gate"))
    .unwrap_or(bundle);
  gate
    .get("coverage_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
    && gate
      .get("support_count_gate")
      .and_then(Value::as_bool)
      .unwrap_or(true)
    && gate
      .get("generalization_gate")
      .and_then(Value::as_bool)
      .unwrap_or(true)
    && gate
      .get("regression_gate")
      .and_then(Value::as_bool)
      .unwrap_or(true)
    && gate
      .get("exploration_gate")
      .and_then(Value::as_bool)
      .unwrap_or(true)
    && gate
      .get("determinism_gate")
      .and_then(Value::as_bool)
      .unwrap_or(true)
}

fn pattern_stack_gate_reasons(bundle: &Value) -> Vec<Value> {
  if pattern_stack_gate_pass(bundle) {
    return vec![];
  }
  let gate = bundle
    .get("gate_result")
    .or_else(|| bundle.get("pattern_stack_gate"))
    .unwrap_or(bundle);
  let mut reasons = Vec::<Value>::new();
  if !gate
    .get("coverage_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_COVERAGE_GATE_FAIL","msg":"pattern coverage gate failed"}),
    );
  }
  if !gate
    .get("support_count_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_SUPPORT_COUNT_GATE_FAIL","msg":"pattern support-count gate failed"}),
    );
  }
  if !gate
    .get("generalization_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_GENERALIZATION_GATE_FAIL","msg":"pattern generalization gate failed"}),
    );
  }
  if !gate
    .get("regression_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_REGRESSION_GATE_FAIL","msg":"pattern regression gate failed"}),
    );
  }
  if !gate
    .get("exploration_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_EXPLORATION_GATE_FAIL","msg":"pattern exploration gate failed"}),
    );
  }
  if !gate
    .get("determinism_gate")
    .and_then(Value::as_bool)
    .unwrap_or(true)
  {
    reasons.push(
      json!({"code":"AGENT_PATTERN_STACK_DETERMINISM_GATE_FAIL","msg":"pattern determinism gate failed"}),
    );
  }
  if reasons.is_empty() {
    reasons.push(json!({"code":"AGENT_PATTERN_STACK_GATE_FAIL","msg":"pattern stack gate failed"}));
  }
  reasons
}

fn optimization_pattern_stack_bundle(spec: &OptimizationSpecEntry) -> Option<Value> {
  let universe = spec
    .objectives_json
    .get("fp_universe")
    .or_else(|| spec.objectives_json.get("universe"))
    .and_then(Value::as_array)
    .map(|values| {
      values
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  let patterns = spec
    .levers_json
    .as_array()
    .map(|values| {
      values
        .iter()
        .map(|row| {
          let pattern_id = row
            .get("pattern_id")
            .and_then(Value::as_str)
            .map(str::to_string)
            .or_else(|| {
              row.get("kind")
                .and_then(Value::as_str)
                .map(|kind| format!("pattern_{kind}"))
            })
            .unwrap_or_else(|| "pattern_inline".to_string());
          json!({
            "pattern_id": pattern_id,
            "fix_cover": row.get("fix_cover").cloned().unwrap_or_else(|| json!([])),
            "mask_cover": row.get("mask_cover").cloned().unwrap_or_else(|| json!([])),
            "weight": row.get("weight").cloned().unwrap_or_else(|| json!(1.0)),
            "support_count": row.get("support_count").cloned().unwrap_or_else(|| json!(0)),
            "generalization_score": row.get("generalization_score").cloned().unwrap_or_else(|| json!(0.0)),
            "stage": row.get("stage").cloned().unwrap_or(Value::Null),
          })
        })
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  if universe.is_empty() || patterns.is_empty() {
    return None;
  }
  let min_coverage = spec
    .safety_json
    .get("pattern_min_coverage")
    .and_then(Value::as_f64)
    .unwrap_or(1.0);
  let min_support_count = spec
    .safety_json
    .get("pattern_min_support_count")
    .and_then(Value::as_u64);
  let min_generalization_score = spec
    .safety_json
    .get("pattern_min_generalization_score")
    .and_then(Value::as_f64);
  let costs = spec.safety_json.get("pattern_costs");
  Some(optimize_pattern_stack_bundle(
    universe,
    patterns,
    costs,
    min_coverage,
    min_support_count,
    min_generalization_score,
  ))
}

fn agent_pattern_stack_bundle_from_options(options_json: &Value) -> Option<Value> {
  let stack = options_json
    .get("pattern_stack")
    .or_else(|| options_json.get("synthesis_pattern_stack"))?;
  if !stack.is_object() {
    return None;
  }
  let universe = stack
    .get("universe")
    .and_then(Value::as_array)
    .map(|values| {
      values
        .iter()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>()
    })
    .unwrap_or_default();
  let patterns = stack
    .get("patterns")
    .or_else(|| stack.pointer("/coverage_matrix/patterns"))
    .and_then(Value::as_array)
    .cloned()
    .unwrap_or_default();
  if universe.is_empty() || patterns.is_empty() {
    return None;
  }
  let min_coverage = stack
    .get("min_coverage")
    .and_then(Value::as_f64)
    .unwrap_or(1.0);
  let min_support_count = stack.get("min_support_count").and_then(Value::as_u64);
  let min_generalization_score = stack
    .get("min_generalization_score")
    .and_then(Value::as_f64);
  let costs = stack.get("pattern_costs");
  Some(optimize_pattern_stack_bundle(
    universe,
    patterns,
    costs,
    min_coverage,
    min_support_count,
    min_generalization_score,
  ))
}

fn breakglass_active_grant_count(session: &Value) -> u64 {
  session
    .get("active_grants_json")
    .and_then(Value::as_array)
    .map(|entries| {
      entries
        .iter()
        .filter(|entry| {
          !entry
            .get("status")
            .and_then(Value::as_str)
            .map(|status| {
              status.eq_ignore_ascii_case("revoked") || status.eq_ignore_ascii_case("closed")
            })
            .unwrap_or(false)
        })
        .count() as u64
    })
    .unwrap_or(0)
}

fn breakglass_lease_accounting_snapshot(breakglass_all: &Value, now: u128) -> Value {
  let mut total_sessions = 0u64;
  let mut active_sessions = 0u64;
  let mut pending_sessions = 0u64;
  let mut active_grants = 0u64;
  let mut stale_sessions = 0u64;
  let mut indicator_lost_sessions = 0u64;
  if let Some(items) = breakglass_all.get("items").and_then(Value::as_array) {
    for session in items {
      total_sessions = total_sessions.saturating_add(1);
      let status = session
        .get("status")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .unwrap_or_else(|| "pending".to_string());
      if status == "active" {
        active_sessions = active_sessions.saturating_add(1);
        active_grants = active_grants.saturating_add(breakglass_active_grant_count(session));
      } else if status == "pending" {
        pending_sessions = pending_sessions.saturating_add(1);
      }
      let expired = session
        .get("expires_ms")
        .and_then(Value::as_u64)
        .map(|value| (value as u128) <= now)
        .unwrap_or(false);
      if (status == "active" || status == "pending") && expired {
        stale_sessions = stale_sessions.saturating_add(1);
      }
      let indicator_lost = session
        .get("indicator_state")
        .and_then(Value::as_str)
        .map(|state| state.eq_ignore_ascii_case("lost"))
        .unwrap_or(false);
      if indicator_lost {
        indicator_lost_sessions = indicator_lost_sessions.saturating_add(1);
      }
    }
  }
  json!({
    "schema": "pnix-breakglass-lease-accounting@0.1",
    "totals": {
      "sessions": total_sessions,
      "sessions_active": active_sessions,
      "sessions_pending": pending_sessions,
      "active_grants": active_grants,
      "stale_sessions": stale_sessions,
      "indicator_lost_sessions": indicator_lost_sessions,
    },
    "levels": {
      "global": {
        "sessions_active": active_sessions,
        "active_grants": active_grants,
      },
      "session": {
        "sessions_total": total_sessions,
        "sessions_pending": pending_sessions,
      }
    }
  })
}

fn breakglass_lease_accounting_for_namespace(
  store: &HumanOpsStore,
  namespace: &str,
  now: u128,
  projected_status: Option<(&str, &str)>,
) -> Value {
  let items = store
    .breakglass_sessions
    .values()
    .filter(|session| session.ns == namespace)
    .map(|session| {
      let status = match projected_status {
        Some((session_id, projected)) if session.session_id == session_id => projected,
        _ => session.status.as_str(),
      };
      json!({
        "status": status,
        "expires_ms": session.expires_ms,
        "indicator_state": session.indicator_state.clone(),
        "active_grants_json": session.active_grants_json.clone(),
      })
    })
    .collect::<Vec<_>>();
  breakglass_lease_accounting_snapshot(&json!({ "items": items }), now)
}

fn breakglass_quota_decision_for_namespace(
  store: &HumanOpsStore,
  namespace: &str,
  now: u128,
  projected_status: Option<(&str, &str)>,
) -> Value {
  let accounting =
    breakglass_lease_accounting_for_namespace(store, namespace, now, projected_status);
  breakglass_quota_enforcer_decision(&accounting)
}

fn breakglass_quota_enforcer_decision(accounting: &Value) -> Value {
  let active_sessions = accounting
    .pointer("/totals/sessions_active")
    .and_then(Value::as_u64)
    .unwrap_or(0);
  let active_grants = accounting
    .pointer("/totals/active_grants")
    .and_then(Value::as_u64)
    .unwrap_or(0);
  let throttle_sessions = ((BREAKGLASS_QUOTA_MAX_ACTIVE_SESSIONS
    .saturating_mul(BREAKGLASS_QUOTA_THROTTLE_BP))
  .saturating_add(9_999))
    / 10_000;
  let throttle_grants = ((BREAKGLASS_QUOTA_MAX_ACTIVE_GRANTS
    .saturating_mul(BREAKGLASS_QUOTA_THROTTLE_BP))
  .saturating_add(9_999))
    / 10_000;

  let (decision, reason_code) = if active_sessions > BREAKGLASS_QUOTA_MAX_ACTIVE_SESSIONS
    || active_grants > BREAKGLASS_QUOTA_MAX_ACTIVE_GRANTS
  {
    ("close", "QUOTA_EXCEEDED")
  } else if active_sessions >= throttle_sessions || active_grants >= throttle_grants {
    ("throttle", "QUOTA_NEAR_LIMIT")
  } else {
    ("allow", "QUOTA_OK")
  };

  json!({
    "schema": "pnix-breakglass-quota-enforcer@0.1",
    "decision": decision,
    "reason_code": reason_code,
    "limits": {
      "max_active_sessions": BREAKGLASS_QUOTA_MAX_ACTIVE_SESSIONS,
      "max_active_grants": BREAKGLASS_QUOTA_MAX_ACTIVE_GRANTS,
      "throttle_bp": BREAKGLASS_QUOTA_THROTTLE_BP,
      "throttle_active_sessions": throttle_sessions,
      "throttle_active_grants": throttle_grants,
    },
    "usage": {
      "active_sessions": active_sessions,
      "active_grants": active_grants,
      "session_headroom": BREAKGLASS_QUOTA_MAX_ACTIVE_SESSIONS.saturating_sub(active_sessions),
      "grant_headroom": BREAKGLASS_QUOTA_MAX_ACTIVE_GRANTS.saturating_sub(active_grants),
    }
  })
}

fn kpi_summary_u64(summary: &Value, key: &str) -> u64 {
  summary.get(key).and_then(Value::as_u64).unwrap_or(0)
}

fn cert_valid_half_life_from_jsonl(path: &str) -> Result<Value> {
  let content = fs::read_to_string(path).with_context(|| format!("read cert history {}", path))?;
  let mut rows: Vec<(u128, String)> = content
    .lines()
    .filter_map(|line| {
      let trimmed = line.trim();
      if trimmed.is_empty() {
        return None;
      }
      let parsed = serde_json::from_str::<Value>(trimmed).ok()?;
      let ts = parsed
        .get("updated_ms")
        .and_then(Value::as_u64)
        .map(|value| value as u128)
        .or_else(|| {
          parsed
            .get("ts_ms")
            .and_then(Value::as_u64)
            .map(|value| value as u128)
        })?;
      let status = parsed
        .get("status")
        .and_then(Value::as_str)
        .map(str::to_string)?;
      Some((ts, status))
    })
    .collect();
  rows.sort_by(|a, b| a.0.cmp(&b.0));
  if rows.is_empty() {
    return Ok(json!({
      "path": path,
      "valid_windows": 0u64,
      "valid_half_life_ms": Value::Null,
    }));
  }

  let mut windows: Vec<u128> = Vec::new();
  for idx in 0..rows.len() {
    let (start_ts, status) = &rows[idx];
    if !status.eq_ignore_ascii_case("VALID") {
      continue;
    }
    if let Some((end_ts, _)) = rows.get(idx + 1) {
      windows.push(end_ts.saturating_sub(*start_ts));
    }
  }
  let half_life = if windows.is_empty() {
    None
  } else {
    Some((windows.iter().sum::<u128>() / windows.len() as u128) as u64)
  };
  Ok(json!({
    "path": path,
    "valid_windows": windows.len() as u64,
    "valid_half_life_ms": half_life,
  }))
}

fn kpi_snapshot_impl(
  request: KpiSnapshotRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  changes: &Arc<RwLock<ChangeRequestStore>>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let now = now_ms();
  let since_ms = request
    .since_ms
    .unwrap_or_else(|| now.saturating_sub(24 * 60 * 60 * 1000));
  let limit = request.limit.unwrap_or(500).clamp(1, 20_000);

  let denies = policy_eval_list_impl(
    PolicyEvalListRequest {
      ns: Some(namespace.clone()),
      channel: None,
      target: None,
      decision: Some("deny".to_string()),
      since_ms: Some(since_ms),
      limit: Some(limit),
    },
    namespace.as_str(),
  )?;

  let breakglass_active = breakglass_session_list_impl(
    BreakglassSessionListRequest {
      ns: Some(namespace.clone()),
      status: Some("active".to_string()),
      limit: Some(limit),
    },
    namespace.as_str(),
    runtime,
  )?;
  let breakglass_all = breakglass_session_list_impl(
    BreakglassSessionListRequest {
      ns: Some(namespace.clone()),
      status: None,
      limit: Some(limit),
    },
    namespace.as_str(),
    runtime,
  )?;
  let changes_pending = change_list_impl(
    ChangeListRequest {
      ns: Some(namespace.clone()),
      status: Some("pending".to_string()),
      risk: None,
      limit: Some(limit),
    },
    namespace.as_str(),
    changes,
  )?;
  let changes_pending_high = change_list_impl(
    ChangeListRequest {
      ns: Some(namespace.clone()),
      status: Some("pending".to_string()),
      risk: Some("high".to_string()),
      limit: Some(limit),
    },
    namespace.as_str(),
    changes,
  )?;
  let gateway_stats = gateway_decision_stats_impl(
    GatewayDecisionStatsRequest {
      ns: Some(namespace.clone()),
      route_id: None,
      code: None,
      since_ms: Some(since_ms),
      limit: Some(limit),
    },
    namespace.as_str(),
  )?;

  let breakglass_recent_24h = breakglass_all
    .get("items")
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .filter(|entry| {
          entry
            .get("starts_ms")
            .and_then(Value::as_u64)
            .map(|starts| (starts as u128) >= since_ms)
            .unwrap_or(false)
        })
        .count() as u64
    })
    .unwrap_or(0);
  let lease_accounting = breakglass_lease_accounting_snapshot(&breakglass_all, now);
  let lease_quota = breakglass_quota_enforcer_decision(&lease_accounting);

  let cert_summary = request
    .cert_history_path
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .and_then(|path| cert_valid_half_life_from_jsonl(path).ok());

  Ok(json!({
    "schema": "pnix-governance-kpi-snapshot@0.1",
    "window": {
      "since_ms": since_ms,
      "until_ms": now,
    },
    "summary": {
      "preflight_denies": kpi_value_count(&denies),
      "breakglass_active": kpi_value_count(&breakglass_active),
      "breakglass_recent_24h": breakglass_recent_24h,
      "lease_active_grants": lease_accounting.pointer("/totals/active_grants").and_then(Value::as_u64).unwrap_or(0),
      "lease_quota_decision": lease_quota.get("decision").cloned().unwrap_or(Value::Null),
      "lease_quota_reason_code": lease_quota.get("reason_code").cloned().unwrap_or(Value::Null),
      "changes_pending": kpi_value_count(&changes_pending),
      "changes_pending_high": kpi_value_count(&changes_pending_high),
      "gateway_total_decisions": gateway_stats.get("total_decisions").and_then(Value::as_u64).unwrap_or(0),
      "certificate_half_life_ms": cert_summary.as_ref().and_then(|v| v.get("valid_half_life_ms")).and_then(Value::as_u64),
      "certificate_valid_windows": cert_summary.as_ref().and_then(|v| v.get("valid_windows")).and_then(Value::as_u64),
    },
    "sources": {
      "policy_eval_deny": denies,
      "breakglass_active": breakglass_active,
      "breakglass_all": breakglass_all,
      "lease_accounting": lease_accounting,
      "lease_quota": lease_quota,
      "changes_pending": changes_pending,
      "changes_pending_high": changes_pending_high,
      "gateway_stats": gateway_stats,
      "certificate": cert_summary,
    }
  }))
}

fn synthesize_kpi_ledger_input(
  snapshot: &Value,
  request: &KpiLedgerRequest,
  now_ms: u128,
) -> Value {
  let summary = snapshot
    .get("summary")
    .cloned()
    .unwrap_or_else(|| json!({}));
  let window = snapshot.get("window").cloned().unwrap_or_else(|| json!({}));
  let ns = request
    .ns
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .or_else(|| {
      snapshot
        .pointer("/sources/policy_eval_deny/ns")
        .and_then(Value::as_str)
        .map(str::to_string)
    })
    .unwrap_or_else(|| "default".to_string());
  let actor = request
    .actor
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "svc:pnix-ops".to_string());
  let track = request
    .track
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "stable".to_string());
  let week_id = request
    .week_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let period_tag = week_id.clone().unwrap_or_else(|| "adhoc".to_string());
  let track_tag = track.to_ascii_uppercase();

  let deny_weight = request
    .weights
    .get("deny")
    .and_then(Value::as_f64)
    .unwrap_or(1.0);
  let bg_active_weight = request
    .weights
    .get("bg_active")
    .and_then(Value::as_f64)
    .unwrap_or(3.0);
  let bg_recent_weight = request
    .weights
    .get("bg_recent")
    .and_then(Value::as_f64)
    .unwrap_or(1.0);
  let pending_weight = request
    .weights
    .get("pending")
    .and_then(Value::as_f64)
    .unwrap_or(0.5);
  let pending_high_weight = request
    .weights
    .get("pending_high")
    .and_then(Value::as_f64)
    .unwrap_or(2.0);
  let uncertainty_default = request
    .uncertainty
    .get("default_ucb")
    .and_then(Value::as_f64)
    .unwrap_or(0.0);
  let uncertainty_authz = request
    .uncertainty
    .get("authz_ucb")
    .and_then(Value::as_f64)
    .unwrap_or(uncertainty_default);
  let uncertainty_bg = request
    .uncertainty
    .get("break_glass_ucb")
    .and_then(Value::as_f64)
    .unwrap_or(uncertainty_default);
  let uncertainty_release = request
    .uncertainty
    .get("release_ucb")
    .and_then(Value::as_f64)
    .unwrap_or(uncertainty_default);

  let preflight_denies = kpi_summary_u64(&summary, "preflight_denies") as f64;
  let breakglass_active = kpi_summary_u64(&summary, "breakglass_active") as f64;
  let breakglass_recent = kpi_summary_u64(&summary, "breakglass_recent_24h") as f64;
  let pending = kpi_summary_u64(&summary, "changes_pending") as f64;
  let pending_high = kpi_summary_u64(&summary, "changes_pending_high") as f64;

  let rc_authz_exposure = preflight_denies * deny_weight;
  let rc_bg = breakglass_active * bg_active_weight + breakglass_recent * bg_recent_weight;
  let rc_release_backlog = pending * pending_weight + pending_high * pending_high_weight;

  let account_ref_authz = format!("URLA_{}_AUTHZ_{}", track_tag, period_tag);
  let account_ref_bg = format!("URLA_{}_BREAK_GLASS_{}", track_tag, period_tag);
  let account_ref_release = format!("URLA_{}_RELEASE_{}", track_tag, period_tag);

  json!({
    "apiVersion": "puck.pnix.dev/v0.1",
    "kind": "UnifiedRiskLedgerInputBatch",
    "generated_ms": now_ms,
    "week_id": week_id,
    "scope": {
      "ns": ns,
      "track": track,
    },
    "weights": {
      "deny": deny_weight,
      "bg_active": bg_active_weight,
      "bg_recent": bg_recent_weight,
      "pending": pending_weight,
      "pending_high": pending_high_weight,
    },
    "window": window,
    "summary": summary,
    "ledger_txns": [
      {
        "apiVersion": "puck.pnix.dev/v0.1",
        "kind": "UnifiedRiskLedgerTransaction",
        "txn_id": format!("URLTX_AUTHZ_{}_001", now_ms),
        "account_ref": account_ref_authz,
        "risk_type": "authz",
        "delta_rc": rc_authz_exposure,
        "rc_breakdown": {
          "rule_rc": 0.0,
          "authz_rc": rc_authz_exposure,
          "break_glass_rc": 0.0,
          "release_rc": 0.0,
          "total_rc": rc_authz_exposure
        },
        "uncertainty_ucb": uncertainty_authz,
        "evidence_refs": [
          "kpi.snapshot.summary.preflight_denies"
        ],
        "authorized_path": "decision",
        "status": "pending"
      },
      {
        "apiVersion": "puck.pnix.dev/v0.1",
        "kind": "UnifiedRiskLedgerTransaction",
        "txn_id": format!("URLTX_BG_{}_002", now_ms),
        "account_ref": account_ref_bg,
        "risk_type": "break_glass",
        "delta_rc": rc_bg,
        "rc_breakdown": {
          "rule_rc": 0.0,
          "authz_rc": 0.0,
          "break_glass_rc": rc_bg,
          "release_rc": 0.0,
          "total_rc": rc_bg
        },
        "uncertainty_ucb": uncertainty_bg,
        "evidence_refs": [
          "kpi.snapshot.summary.breakglass"
        ],
        "authorized_path": "decision",
        "status": "pending"
      },
      {
        "apiVersion": "puck.pnix.dev/v0.1",
        "kind": "UnifiedRiskLedgerTransaction",
        "txn_id": format!("URLTX_RELEASE_{}_003", now_ms),
        "account_ref": account_ref_release,
        "risk_type": "release",
        "delta_rc": rc_release_backlog,
        "rc_breakdown": {
          "rule_rc": 0.0,
          "authz_rc": 0.0,
          "break_glass_rc": 0.0,
          "release_rc": rc_release_backlog,
          "total_rc": rc_release_backlog
        },
        "uncertainty_ucb": uncertainty_release,
        "evidence_refs": [
          "kpi.snapshot.summary.pending_changes"
        ],
        "authorized_path": "decision",
        "status": "pending"
      }
    ],
    "source": {
      "kpi_snapshot": snapshot,
      "actor": actor
    }
  })
}

fn kpi_ledger_impl(
  request: KpiLedgerRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  changes: &Arc<RwLock<ChangeRequestStore>>,
) -> Result<Value> {
  let snapshot = kpi_snapshot_impl(
    KpiSnapshotRequest {
      ns: request.ns.clone(),
      since_ms: request.since_ms,
      limit: request.limit,
      cert_history_path: request.cert_history_path.clone(),
    },
    namespace,
    runtime,
    changes,
  )?;
  Ok(synthesize_kpi_ledger_input(&snapshot, &request, now_ms()))
}

fn admission_check_impl(
  request: AdmissionCheckRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.clone().unwrap_or_else(|| namespace.to_string()))?;
  let channel = normalize_channel(
    request
      .channel
      .clone()
      .or_else(|| {
        request
          .system
          .get("channel")
          .and_then(Value::as_str)
          .map(str::to_string)
      })
      .unwrap_or_else(|| "prod".to_string()),
  )?;
  let target = request.target.trim().to_string();
  if target.is_empty() {
    anyhow::bail!("admission.check requires target");
  }

  let subject_kind = request
    .subject_kind
    .clone()
    .or_else(|| {
      request
        .subject
        .get("kind")
        .and_then(Value::as_str)
        .map(str::to_string)
    })
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty());
  let subject_id = request
    .subject_id
    .clone()
    .or_else(|| {
      request
        .subject
        .get("id")
        .and_then(Value::as_str)
        .map(str::to_string)
    })
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty());
  let breakglass = request.breakglass.unwrap_or(false)
    || request
      .actor
      .get("breakglass")
      .and_then(Value::as_bool)
      .unwrap_or(false);

  let compliance_mode_value = get_compliance_policy_global()
    .ok()
    .and_then(|store| {
      let guard = store.read().unwrap_or_else(|e| e.into_inner());
      guard
        .by_key
        .get(&compliance_policy_key(namespace.as_str(), channel.as_str()))
        .map(|entry| compliance_mode(&entry.policy_json))
    })
    .unwrap_or_else(|| "permissive".to_string());

  let policy_release_id = request
    .policy_release_id
    .clone()
    .or_else(|| {
      request
        .system
        .get("policy_release_id")
        .and_then(Value::as_str)
        .map(str::to_string)
    })
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty());

  let mut decision = "allow".to_string();
  let mut reasons: Vec<Value> = Vec::new();
  let mut warnings: Vec<Value> = Vec::new();
  let tenant = tenant_for_namespace(namespace.as_str());
  if let Some(tenant_entry) = tenant.as_ref() {
    if tenant_entry.status == "suspended" {
      if breakglass {
        warnings.push(policy_reason(
          "TENANT_SUSPENDED_BREAKGLASS",
          format!(
            "tenant `{}` is suspended but breakglass override is active",
            tenant_entry.tenant_id
          ),
          json!({
            "tenant_id": tenant_entry.tenant_id,
            "namespace": namespace,
          }),
        ));
      } else {
        decision = "deny".to_string();
        reasons.push(policy_reason(
          "TENANT_SUSPENDED",
          format!(
            "tenant `{}` is suspended; operation `{}` is blocked",
            tenant_entry.tenant_id, target
          ),
          json!({
            "tenant_id": tenant_entry.tenant_id,
            "namespace": namespace,
          }),
        ));
      }
    }
    if let Some(budget_state) = latest_budget_state_for_tenant(tenant_entry.tenant_id.as_str()) {
      let deploy_target = matches!(
        target.as_str(),
        "service.release.activate"
          | "service.release.create"
          | "desired.apply"
          | "route.revision.activate"
          | "change.run"
          | "remote.execute"
          | "run.execute"
      );
      if deploy_target {
        if budget_state.level == "hard" {
          if breakglass {
            warnings.push(policy_reason(
              "BUDGET_HARD_BREAKGLASS",
              format!(
                "tenant `{}` budget level is hard; breakglass override permits `{}`",
                tenant_entry.tenant_id, target
              ),
              json!({
                "tenant_id": tenant_entry.tenant_id,
                "policy_id": budget_state.policy_id,
                "period_key": budget_state.period_key,
                "spent_minor": budget_state.spent_minor,
                "budget_minor": budget_state.budget_minor,
              }),
            ));
          } else {
            decision = "deny".to_string();
            reasons.push(policy_reason(
              "BUDGET_HARD_BLOCK_DEPLOY",
              format!(
                "tenant `{}` budget hard limit reached; `{}` denied",
                tenant_entry.tenant_id, target
              ),
              json!({
                "tenant_id": tenant_entry.tenant_id,
                "policy_id": budget_state.policy_id,
                "period_key": budget_state.period_key,
                "spent_minor": budget_state.spent_minor,
                "budget_minor": budget_state.budget_minor,
              }),
            ));
          }
        } else if budget_state.level == "soft" {
          warnings.push(policy_reason(
            "BUDGET_SOFT_REQUIRE_APPROVAL",
            format!(
              "tenant `{}` budget level is soft; additional approval recommended for `{}`",
              tenant_entry.tenant_id, target
            ),
            json!({
              "tenant_id": tenant_entry.tenant_id,
              "policy_id": budget_state.policy_id,
              "period_key": budget_state.period_key,
              "spent_minor": budget_state.spent_minor,
              "budget_minor": budget_state.budget_minor,
            }),
          ));
        }
      }
    }
  }

  if target == "exec.admit" {
    let spec_value = request.process_spec.clone().or_else(|| {
      request
        .subject
        .get("process_spec")
        .or_else(|| request.subject.get("spec"))
        .cloned()
    });
    let Some(spec_value) = spec_value else {
      decision = "deny".to_string();
      reasons.push(policy_reason(
        "ADMISSION_INPUT_INVALID",
        "exec.admit requires process_spec (or subject.spec)".to_string(),
        json!({}),
      ));
      let output = json!({
        "schema": "pnix-admission-decision@0.1",
        "allow": false,
        "decision": decision,
        "reasons": reasons,
        "warnings": warnings,
        "target": target,
        "subject_kind": subject_kind,
        "subject_id": subject_id,
        "policy": {
          "release_id": policy_release_id,
          "mode": compliance_mode_value,
          "channel": channel,
        }
      });
      let input = json!({
        "schema": "pnix-admission-input@0.1",
        "request": {"target": target, "ns": namespace, "channel": channel, "ts_ms": now_ms()},
        "actor": request.actor.clone(),
        "subject": request.subject.clone(),
        "desired": request.desired.clone(),
        "system": request.system.clone(),
        "evidence": request.evidence.clone(),
        "links": request.links.clone(),
        "breakglass": breakglass,
      });
      let now = now_ms();
      let log = PolicyEvalLogEntry {
        ns: namespace.clone(),
        eval_id: next_policy_eval_id(),
        ts_ms: now,
        channel: Some(channel.clone()),
        release_id: policy_release_id.clone(),
        target: target.clone(),
        subject_kind: subject_kind.clone(),
        subject_id: subject_id.clone(),
        decision: decision.clone(),
        reasons_json: json!(reasons),
        warnings_json: json!(warnings),
        input_hash: sha256_hex(&input),
        output_hash: sha256_hex(&output),
        invocation_id: request
          .links
          .get("invocation_id")
          .and_then(Value::as_str)
          .map(str::to_string),
        change_id: request
          .links
          .get("change_id")
          .and_then(Value::as_str)
          .map(str::to_string),
        git_commit: request
          .links
          .get("git_commit")
          .and_then(Value::as_str)
          .map(str::to_string),
      };
      let store = get_policy_eval_log_global()?;
      {
        let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
        guard.by_key.insert(
          policy_eval_log_key(log.ns.as_str(), log.eval_id.as_str()),
          log.clone(),
        );
      }
      save_policy_eval_log_store(&store, runtime)?;
      return Ok(output);
    };
    match parse_spec(&spec_value).and_then(|spec| enforce_exec_compliance(&spec, breakglass)) {
      Ok(_) => {}
      Err(error) => {
        decision = "deny".to_string();
        reasons.push(policy_reason_from_error(error.to_string().as_str()));
      }
    }
  } else if matches!(compliance_mode_value.as_str(), "enforcing" | "locked") {
    decision = "deny".to_string();
    reasons.push(policy_reason(
      "TARGET_NOT_IMPLEMENTED",
      format!(
        "admission target `{}` is not yet implemented in enforcing mode",
        target
      ),
      json!({ "channel": channel }),
    ));
  } else {
    warnings.push(policy_reason(
      "TARGET_NOT_IMPLEMENTED",
      format!(
        "admission target `{}` uses permissive fallback allow",
        target
      ),
      json!({ "channel": channel }),
    ));
  }

  let output = json!({
    "schema": "pnix-admission-decision@0.1",
    "allow": decision == "allow",
    "decision": decision,
    "reasons": reasons,
    "warnings": warnings,
    "target": target,
    "subject_kind": subject_kind,
    "subject_id": subject_id,
    "policy": {
      "release_id": policy_release_id,
      "mode": compliance_mode_value,
      "channel": channel,
    }
  });

  let input = json!({
    "schema": "pnix-admission-input@0.1",
    "request": {"target": target, "ns": namespace, "channel": channel, "ts_ms": now_ms()},
    "actor": request.actor.clone(),
    "subject": request.subject.clone(),
    "desired": request.desired.clone(),
    "system": request.system.clone(),
    "evidence": request.evidence.clone(),
    "links": request.links.clone(),
    "breakglass": breakglass,
  });
  let now = now_ms();
  let log = PolicyEvalLogEntry {
    ns: namespace.clone(),
    eval_id: next_policy_eval_id(),
    ts_ms: now,
    channel: Some(channel.clone()),
    release_id: policy_release_id.clone(),
    target: target.clone(),
    subject_kind: subject_kind.clone(),
    subject_id: subject_id.clone(),
    decision: decision.clone(),
    reasons_json: output.get("reasons").cloned().unwrap_or_else(|| json!([])),
    warnings_json: output.get("warnings").cloned().unwrap_or_else(|| json!([])),
    input_hash: sha256_hex(&input),
    output_hash: sha256_hex(&output),
    invocation_id: request
      .links
      .get("invocation_id")
      .and_then(Value::as_str)
      .map(str::to_string),
    change_id: request
      .links
      .get("change_id")
      .and_then(Value::as_str)
      .map(str::to_string),
    git_commit: request
      .links
      .get("git_commit")
      .and_then(Value::as_str)
      .map(str::to_string),
  };
  let store = get_policy_eval_log_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      policy_eval_log_key(log.ns.as_str(), log.eval_id.as_str()),
      log,
    );
  }
  save_policy_eval_log_store(&store, runtime)?;

  Ok(output)
}

