fn team_list_impl(request: TeamListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_team_status(Some(value.to_string())));
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_human_ops_global()?;
  let mut rows: Vec<TeamEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .teams
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|status| entry.status == *status)
          .unwrap_or(true)
      })
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|needle| entry.name.to_ascii_lowercase().contains(needle))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| a.team_id.cmp(&b.team_id))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(team_view).collect::<Vec<_>>(),
  }))
}

