fn oncall_schedule_set_impl(
  request: OncallScheduleSetRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let team_id = request.team_id.trim().to_string();
  let name = request.name.trim().to_string();
  if team_id.is_empty() || name.is_empty() {
    anyhow::bail!("oncall.schedule.set requires team_id and name");
  }
  let schedule_id = request
    .schedule_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_schedule_id);
  let timezone = request
    .timezone
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "UTC".to_string());
  let status = normalize_oncall_schedule_status(request.status);
  let spec_json = request.spec_json.unwrap_or_else(|| json!({}));
  let store = get_human_ops_global()?;
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if !guard
      .teams
      .contains_key(&team_key(namespace.as_str(), team_id.as_str()))
    {
      anyhow::bail!("team `{}` not found", team_id);
    }
    let row = OncallScheduleEntry {
      ns: namespace.clone(),
      schedule_id: schedule_id.clone(),
      team_id: team_id.clone(),
      name,
      timezone,
      spec_json: if spec_json.is_object() {
        spec_json
      } else {
        json!({})
      },
      status,
      updated_ms: now_ms(),
    };
    guard.oncall_schedules.insert(
      oncall_schedule_key(namespace.as_str(), schedule_id.as_str()),
      row.clone(),
    );
    row
  };
  save_human_ops_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "oncall.schedule.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__human__")),
    Some(updated.schedule_id.clone()),
    None,
    None,
    None,
    json!({ "schedule": oncall_schedule_view(&updated) }),
  );
  Ok(json!({
    "ns": namespace,
    "schedule": oncall_schedule_view(&updated),
  }))
}

