fn forecast_profile_list_impl(
  request: ForecastProfileListRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let scope_kind_filter = request
    .scope_kind
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_forecast_scope_kind(Some(value.to_string())));
  let scope_id_filter = request
    .scope_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let channel_filter = match request.channel {
    Some(value) => Some(normalize_channel(value)?),
    None => None,
  };
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_forecast_profile_global()?;
  let mut rows: Vec<ForecastProfileEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        scope_kind_filter
          .as_deref()
          .map(|value| entry.scope_kind == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        scope_id_filter
          .as_deref()
          .map(|value| entry.scope_id == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        channel_filter
          .as_ref()
          .map(|value| entry.channel.as_ref() == Some(value))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.updated_ms
      .cmp(&a.updated_ms)
      .then_with(|| a.profile_id.cmp(&b.profile_id))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(forecast_profile_view).collect::<Vec<_>>(),
  }))
}

