fn predictive_run_now_impl(
  request: PredictiveRunNowRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let scope_kind_raw = request.scope_kind.trim();
  if scope_kind_raw.is_empty() {
    anyhow::bail!("predictive.run.now requires scope_kind");
  }
  let scope_kind = normalize_forecast_scope_kind(Some(scope_kind_raw.to_string()));
  let scope_id = request.scope_id.trim().to_string();
  if scope_id.is_empty() {
    anyhow::bail!("predictive.run.now requires scope_id");
  }
  let channel = match request.channel {
    Some(value) => Some(normalize_channel(value)?),
    None => None,
  };
  let requested_profile_id = request
    .profile_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let profile_store = get_forecast_profile_global()?;
  let selected_profile = {
    let guard = profile_store.read().unwrap_or_else(|e| e.into_inner());
    if let Some(profile_id) = requested_profile_id.as_deref() {
      guard
        .by_key
        .get(&forecast_profile_key(namespace.as_str(), profile_id))
        .cloned()
    } else {
      guard
        .by_key
        .values()
        .filter(|entry| entry.ns == namespace)
        .filter(|entry| entry.scope_kind == scope_kind)
        .filter(|entry| entry.scope_id == scope_id)
        .filter(|entry| entry.channel == channel)
        .max_by(|a, b| {
          a.updated_ms
            .cmp(&b.updated_ms)
            .then_with(|| a.profile_id.cmp(&b.profile_id))
        })
        .cloned()
    }
  };
  if let Some(profile_id) = requested_profile_id.as_deref() {
    if selected_profile.is_none() {
      anyhow::bail!("forecast profile `{}` not found", profile_id);
    }
  }

  let profile_id = selected_profile
    .as_ref()
    .map(|entry| entry.profile_id.clone())
    .or(requested_profile_id)
    .unwrap_or_else(|| "default".to_string());
  let model_kind = selected_profile
    .as_ref()
    .map(|entry| entry.model_kind.clone())
    .unwrap_or_else(|| "ewma".to_string());
  let horizon_ms = selected_profile
    .as_ref()
    .map(|entry| entry.horizon_ms)
    .unwrap_or(6 * 60 * 60 * 1000);
  let step_ms = selected_profile
    .as_ref()
    .map(|entry| entry.step_ms)
    .unwrap_or(60_000);
  let mut features_json = selected_profile
    .as_ref()
    .map(|entry| entry.features_json.clone())
    .unwrap_or_else(|| json!({}));
  if !features_json.is_object() {
    features_json = json!({});
  }
  let mut guardrails_json = selected_profile
    .as_ref()
    .map(|entry| entry.guardrails_json.clone())
    .unwrap_or_else(|| json!({}));
  if !guardrails_json.is_object() {
    guardrails_json = json!({});
  }
  let min_confidence_bp = guardrails_json
    .get("min_confidence_bp")
    .and_then(Value::as_u64)
    .map(|value| value.min(10_000) as u32)
    .unwrap_or(7_000);
  let confidence_bp = guardrails_json
    .get("confidence_bp")
    .and_then(Value::as_u64)
    .map(|value| value.min(10_000) as u32)
    .unwrap_or(8_000);
  let now = now_ms();
  let run_id = next_forecast_run_id();
  let run_status = if selected_profile.is_some() {
    "ok".to_string()
  } else {
    "insufficient_data".to_string()
  };
  let run = ForecastRunEntry {
    ns: namespace.clone(),
    run_id: run_id.clone(),
    profile_id: profile_id.clone(),
    scope_kind: scope_kind.clone(),
    scope_id: scope_id.clone(),
    channel: channel.clone(),
    created_ms: now,
    input_range_json: json!({
      "from_ms": now.saturating_sub(horizon_ms as u128),
      "to_ms": now,
      "step_ms": step_ms,
    }),
    model_kind: model_kind.clone(),
    confidence_bp,
    status: run_status,
    summary_json: json!({
      "scope_kind": scope_kind,
      "scope_id": scope_id,
      "channel": channel,
      "model_kind": model_kind,
      "horizon_ms": horizon_ms,
      "step_ms": step_ms,
      "signals": features_json,
    }),
    forecast_ref_id: format!("local:forecast:{}", run_id),
  };
  let run_store = get_forecast_run_global()?;
  {
    let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      forecast_run_key(namespace.as_str(), run.run_id.as_str()),
      run.clone(),
    );
  }
  save_forecast_run_store(&run_store, runtime)?;

  let plan_id = next_predictive_plan_id();
  let actions_json = if confidence_bp >= min_confidence_bp {
    json!([
      {
        "type": "autoscale.evaluate",
        "scope_kind": run.scope_kind,
        "scope_id": run.scope_id,
        "channel": run.channel,
      },
      {
        "type": "prefetch.stage",
        "scope_kind": run.scope_kind,
        "scope_id": run.scope_id,
        "channel": run.channel,
      }
    ])
  } else {
    json!([
      {
        "type": "observe.only",
        "reason": "low_confidence",
      }
    ])
  };
  let plan = PredictiveActionPlanEntry {
    ns: namespace.clone(),
    plan_id: plan_id.clone(),
    created_ms: now,
    scope_kind: run.scope_kind.clone(),
    scope_id: run.scope_id.clone(),
    channel: run.channel.clone(),
    forecast_run_id: run.run_id.clone(),
    confidence_bp,
    actions_json,
    expected_impact_json: json!({
      "min_confidence_bp": min_confidence_bp,
      "recommended": confidence_bp >= min_confidence_bp,
      "confidence_bp": confidence_bp,
    }),
    status: "proposed".to_string(),
    change_id: None,
  };
  let plan_store = get_predictive_action_plan_global()?;
  {
    let mut guard = plan_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      predictive_action_plan_key(namespace.as_str(), plan.plan_id.as_str()),
      plan.clone(),
    );
  }
  save_predictive_action_plan_store(&plan_store, runtime)?;
  publish_supervisor_event(
    events,
    "predictive.plan.proposed",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__predictive__")),
    Some(plan_id.clone()),
    None,
    None,
    None,
    json!({
      "forecast_run_id": run.run_id,
      "plan_id": plan_id,
      "confidence_bp": confidence_bp,
      "min_confidence_bp": min_confidence_bp,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "forecast_run": forecast_run_view(&run),
    "predictive_action_plan": predictive_action_plan_view(&plan),
  }))
}

