fn simulation_run_impl(
  request: SimulationRunRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let source_kind = request.source_kind.trim().to_ascii_lowercase();
  if source_kind.is_empty() {
    anyhow::bail!("simulation.run requires source_kind");
  }
  if source_kind.len() > 64
    || !source_kind
      .chars()
      .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
  {
    anyhow::bail!("simulation.run source_kind contains unsupported characters");
  }
  let source_id = request.source_id.trim().to_string();
  if source_id.is_empty() {
    anyhow::bail!("simulation.run requires source_id");
  }
  let base_ref_json = request.base_ref_json.unwrap_or_else(|| json!({}));
  let proposed_ref_json = request.proposed_ref_json.unwrap_or_else(|| json!({}));
  let scenario_id = next_simulation_scenario_id();
  let now = now_ms();
  let scenario = SimulationScenarioEntry {
    ns: namespace.clone(),
    scenario_id: scenario_id.clone(),
    created_ms: now,
    source_kind: source_kind.clone(),
    source_id: source_id.clone(),
    base_ref_json,
    proposed_ref_json,
    env_snapshot_ref_id: request
      .env_snapshot_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
      .unwrap_or_else(|| format!("local:sim_env:{}", scenario_id)),
    status: "done".to_string(),
    last_error: None,
  };
  let scenario_store = get_simulation_scenario_global()?;
  {
    let mut guard = scenario_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      simulation_scenario_key(namespace.as_str(), scenario.scenario_id.as_str()),
      scenario.clone(),
    );
  }
  save_simulation_scenario_store(&scenario_store, runtime)?;

  let result = SimulationResultEntry {
    ns: namespace.clone(),
    result_id: next_simulation_result_id(),
    scenario_id: scenario.scenario_id.clone(),
    created_ms: now,
    summary_json: json!({
      "source": {
        "kind": source_kind,
        "id": source_id,
      },
      "delta": {
        "cost_minor": 0,
        "p95_ms_range": [0, 0],
        "err_ppm_range": [0, 0],
      },
      "flags": [],
      "mitigations": [],
      "assumptions": {
        "model": "heuristic-v0",
        "window": "recent-rollups",
      }
    }),
    result_ref_id: format!("local:simulation:{}", scenario.scenario_id),
    status: "ok".to_string(),
  };
  let result_store = get_simulation_result_global()?;
  {
    let mut guard = result_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      simulation_result_key(namespace.as_str(), result.result_id.as_str()),
      result.clone(),
    );
  }
  save_simulation_result_store(&result_store, runtime)?;
  publish_supervisor_event(
    events,
    "simulation.completed",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__simulation__")),
    Some(scenario.scenario_id.clone()),
    None,
    None,
    None,
    json!({
      "source_kind": scenario.source_kind,
      "source_id": scenario.source_id,
      "result_id": result.result_id,
      "status": result.status,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "simulation_scenario": simulation_scenario_view(&scenario),
    "simulation_result": simulation_result_view(&result),
  }))
}

fn simulation_get_latest_impl(
  request: SimulationGetLatestRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let source_kind = request.source_kind.trim().to_ascii_lowercase();
  if source_kind.is_empty() {
    anyhow::bail!("simulation.get_latest requires source_kind");
  }
  let source_id = request.source_id.trim().to_string();
  if source_id.is_empty() {
    anyhow::bail!("simulation.get_latest requires source_id");
  }
  let scenario_store = get_simulation_scenario_global()?;
  let scenario = {
    let guard = scenario_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| entry.source_kind == source_kind)
      .filter(|entry| entry.source_id == source_id)
      .max_by(|a, b| {
        a.created_ms
          .cmp(&b.created_ms)
          .then_with(|| a.scenario_id.cmp(&b.scenario_id))
      })
      .cloned()
  };
  let result = if let Some(latest) = scenario.as_ref() {
    let result_store = get_simulation_result_global()?;
    let guard = result_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| entry.scenario_id == latest.scenario_id)
      .max_by(|a, b| {
        a.created_ms
          .cmp(&b.created_ms)
          .then_with(|| a.result_id.cmp(&b.result_id))
      })
      .cloned()
  } else {
    None
  };
  Ok(json!({
    "ns": namespace,
    "source_kind": source_kind,
    "source_id": source_id,
    "exists": scenario.is_some(),
    "simulation_scenario": scenario.as_ref().map(simulation_scenario_view),
    "simulation_result": result.as_ref().map(simulation_result_view),
  }))
}

fn parse_numeric(value: Option<&Value>) -> Option<f64> {
  value
    .and_then(|v| v.as_f64().or_else(|| v.as_i64().map(|x| x as f64)))
    .filter(|v| v.is_finite())
}

fn compare_with_op(lhs: f64, op: &str, rhs: f64) -> bool {
  match op {
    ">" => lhs > rhs,
    ">=" => lhs >= rhs,
    "<" => lhs < rhs,
    "<=" => lhs <= rhs,
    "==" | "=" => (lhs - rhs).abs() < f64::EPSILON,
    "!=" => (lhs - rhs).abs() >= f64::EPSILON,
    _ => lhs > rhs,
  }
}

fn evaluate_alert_condition(condition_json: &Value, value_json: &Value) -> bool {
  let Some(condition) = condition_json.as_object() else {
    return false;
  };
  let metric_ok = if let Some(metric) = condition.get("metric").and_then(Value::as_str) {
    let lhs = parse_numeric(value_json.get(metric));
    let rhs = parse_numeric(condition.get("value"));
    match (lhs, rhs) {
      (Some(left), Some(right)) => {
        let op = condition.get("op").and_then(Value::as_str).unwrap_or(">");
        compare_with_op(left, op, right)
      }
      _ => false,
    }
  } else {
    true
  };
  let and_ok = condition
    .get("and")
    .and_then(Value::as_array)
    .map(|items| {
      items
        .iter()
        .all(|item| evaluate_alert_condition(item, value_json))
    })
    .unwrap_or(true);
  let or_ok = condition
    .get("or")
    .and_then(Value::as_array)
    .map(|items| {
      items.is_empty()
        || items
          .iter()
          .any(|item| evaluate_alert_condition(item, value_json))
    })
    .unwrap_or(true);
  metric_ok && and_ok && or_ok
}

fn render_dedupe_key(
  template: &str,
  values: &Value,
  namespace: &str,
  rule: &AlertRuleEntry,
) -> String {
  let mut rendered = template.to_string();
  rendered = rendered.replace("{ns}", namespace);
  rendered = rendered.replace("{rule_id}", rule.rule_id.as_str());
  rendered = rendered.replace("{source_kind}", rule.source_kind.as_str());
  if let Some(obj) = values.as_object() {
    for (key, value) in obj {
      let slot = format!("{{{}}}", key);
      if rendered.contains(slot.as_str()) {
        let replacement = value
          .as_str()
          .map(str::to_string)
          .or_else(|| value.as_i64().map(|v| v.to_string()))
          .or_else(|| value.as_u64().map(|v| v.to_string()))
          .or_else(|| value.as_f64().map(|v| format!("{:.3}", v)))
          .unwrap_or_default();
        rendered = rendered.replace(slot.as_str(), replacement.as_str());
      }
    }
  }
  let compact = rendered.trim();
  if compact.is_empty() {
    format!("rule:{}:scope:{}", rule.rule_id, rule.source_kind)
  } else {
    compact.chars().take(256).collect()
  }
}

