fn alert_rule_set_impl(
  request: AlertRuleSetRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("alert.rule.set requires name");
  }
  let source_kind = request.source_kind.trim().to_ascii_lowercase();
  if source_kind.is_empty() {
    anyhow::bail!("alert.rule.set requires source_kind");
  }
  let rule_id = request
    .rule_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_alert_rule_id);
  let mut selector_json = request.selector_json.unwrap_or_else(|| json!({}));
  if !selector_json.is_object() {
    selector_json = json!({});
  }
  let mut condition_json = request.condition_json.unwrap_or_else(|| json!({}));
  if !condition_json.is_object() {
    condition_json = json!({});
  }
  let mut labels_json = request.labels_json.unwrap_or_else(|| json!({}));
  if !labels_json.is_object() {
    labels_json = json!({});
  }
  let mut autopilot_json = request.autopilot_json.unwrap_or_else(|| json!({}));
  if !autopilot_json.is_object() {
    autopilot_json = json!({});
  }
  let entry = AlertRuleEntry {
    ns: namespace.clone(),
    rule_id: rule_id.clone(),
    name,
    source_kind,
    selector_json,
    window_ms: request
      .window_ms
      .unwrap_or(300_000)
      .clamp(1_000, 7 * 24 * 60 * 60 * 1000),
    eval_every_ms: request
      .eval_every_ms
      .unwrap_or(30_000)
      .clamp(1_000, 7 * 24 * 60 * 60 * 1000),
    condition_json,
    severity: normalize_incident_severity(request.severity),
    dedupe_key_template: request
      .dedupe_key_template
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
      .unwrap_or_else(|| format!("rule:{}:kind:{}", rule_id, "default")),
    labels_json,
    autopilot_json,
    status: normalize_alert_rule_status(request.status),
    updated_ms: now_ms(),
  };
  let store = get_alert_rule_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      alert_rule_key(namespace.as_str(), rule_id.as_str()),
      entry.clone(),
    );
  }
  save_alert_rule_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "alert.rule.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__alert__")),
    Some(rule_id.clone()),
    None,
    None,
    None,
    json!({ "rule": alert_rule_view(&entry) }),
  );
  Ok(json!({
    "ns": namespace,
    "rule": alert_rule_view(&entry),
  }))
}

