fn alert_rule_list_impl(request: AlertRuleListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let source_kind = request
    .source_kind
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_ascii_lowercase);
  let severity = request
    .severity
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_incident_severity(Some(value.to_string())));
  let status = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_alert_rule_status(Some(value.to_string())));
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_alert_rule_global()?;
  let mut rows: Vec<AlertRuleEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        source_kind
          .as_deref()
          .map(|value| entry.source_kind == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        severity
          .as_deref()
          .map(|value| entry.severity == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        status
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.updated_ms
      .cmp(&a.updated_ms)
      .then_with(|| a.name.cmp(&b.name))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(alert_rule_view).collect::<Vec<_>>(),
  }))
}

