fn incident_ack_impl(
  request: IncidentAckRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let incident_id = request.incident_id.trim().to_string();
  if incident_id.is_empty() {
    anyhow::bail!("incident.ack requires incident_id");
  }
  let incident_store = get_incident_global()?;
  let updated = {
    let mut guard = incident_store.write().unwrap_or_else(|e| e.into_inner());
    let row = guard
      .by_key
      .get_mut(&incident_key(namespace.as_str(), incident_id.as_str()))
      .with_context(|| format!("incident `{}` not found", incident_id))?;
    row.status = "acked".to_string();
    row.acked_by = Some(token_id.to_string());
    row.acked_ms = Some(now_ms());
    if let Some(owner) = request.owner_json {
      row.owner_json = if owner.is_object() { owner } else { json!({}) };
    }
    row.updated_ms = now_ms();
    row.clone()
  };
  save_incident_store(&incident_store, runtime)?;
  let _ = append_incident_event(
    namespace.as_str(),
    incident_id.as_str(),
    "acked",
    format!("incident acked by {}", token_id),
    json!({
      "token_id": token_id,
    }),
    runtime,
  )?;
  publish_supervisor_event(
    events,
    "incident.acked",
    "warn",
    Some(scoped_logical_id(namespace.as_str(), "__incident__")),
    Some(incident_id),
    None,
    None,
    None,
    json!({
      "incident": incident_view(&updated),
    }),
  );
  Ok(json!({
    "ns": namespace,
    "incident": incident_view(&updated),
  }))
}

