fn runbook_set_impl(
  request: RunbookSetRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("runbook.set requires name");
  }
  let key = runbook_key(namespace.as_str(), name.as_str());
  let runbook_id = request
    .runbook_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_runbook_id);
  let version = request
    .version
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "1.0.0".to_string());
  let steps_json = serde_json::to_value(request.steps).unwrap_or_else(|_| json!([]));
  let entry = RunbookEntry {
    ns: namespace.clone(),
    runbook_id: runbook_id.clone(),
    name: name.clone(),
    version,
    bundle_ref_id: request
      .bundle_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    sha256: request
      .sha256
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string),
    policy_json: request.policy_json.unwrap_or_else(|| json!({})),
    steps_json: if steps_json.is_array() {
      steps_json
    } else {
      json!([])
    },
    status: normalize_runbook_status(request.status),
    updated_ms: now_ms(),
  };
  let store = get_runbook_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(key, entry.clone());
  }
  save_runbook_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "runbook.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__runbook__")),
    Some(runbook_id),
    None,
    None,
    None,
    json!({ "runbook": runbook_view(&entry) }),
  );
  Ok(json!({
    "ns": namespace,
    "runbook": runbook_view(&entry),
  }))
}

