fn runbook_list_impl(request: RunbookListRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let status = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_runbook_status(Some(value.to_string())));
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase());
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_runbook_global()?;
  let mut rows: Vec<RunbookEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        status
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|value| entry.name.to_ascii_lowercase().contains(value))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.updated_ms
      .cmp(&a.updated_ms)
      .then_with(|| a.name.cmp(&b.name))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(runbook_view).collect::<Vec<_>>(),
  }))
}

fn runbook_execute_impl(
  request: RunbookExecuteRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
  changes: &Arc<RwLock<ChangeRequestStore>>,
  job_store: &Arc<RwLock<JobStore>>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let incident_id = request.incident_id.trim().to_string();
  if incident_id.is_empty() {
    anyhow::bail!("runbook.execute requires incident_id");
  }
  let runbook_name = request.runbook_name.trim().to_string();
  if runbook_name.is_empty() {
    anyhow::bail!("runbook.execute requires runbook_name");
  }
  let mode = request
    .mode
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .unwrap_or("manual")
    .to_ascii_lowercase();
  let auto_run = request.auto_run.unwrap_or_else(|| mode == "auto");

  let incident = {
    let store = get_incident_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&incident_key(namespace.as_str(), incident_id.as_str()))
      .cloned()
      .with_context(|| format!("incident `{}` not found", incident_id))?
  };
  let runbook = {
    let store = get_runbook_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&runbook_key(namespace.as_str(), runbook_name.as_str()))
      .cloned()
      .with_context(|| format!("runbook `{}` not found", runbook_name))?
  };
  if runbook.status != "active" {
    anyhow::bail!("runbook `{}` is not active", runbook_name);
  }

  let requested_steps: Vec<PlanStepRequest> = runbook
    .steps_json
    .as_array()
    .cloned()
    .unwrap_or_default()
    .into_iter()
    .filter_map(|item| serde_json::from_value::<PlanStepRequest>(item).ok())
    .collect();
  let steps = if requested_steps.is_empty() {
    build_plan_steps(vec![PlanStepRequest {
      kind: "noop".to_string(),
      spec: json!({}),
    }])
  } else {
    build_plan_steps(requested_steps)
  };
  let risk = match incident.severity.as_str() {
    "S1" => "high",
    "S2" => "medium",
    _ => "low",
  };
  let now = now_ms();
  let change = ChangeRequestEntry {
    ns: namespace.clone(),
    change_id: next_change_id(),
    created_ms: now,
    updated_ms: now,
    title: format!("Runbook {} for incident {}", runbook.name, incident_id),
    reason: Some(format!("incident:{} runbook:{}", incident_id, runbook.name)),
    source: "runbook".to_string(),
    risk: risk.to_string(),
    status: "proposed".to_string(),
    policy_id: None,
    invocation_id: None,
    session_id: None,
    plan_id: None,
    scheduled_start_ms: None,
    scheduled_end_ms: None,
    steps,
    approvals: Vec::new(),
    last_error: None,
  };
  {
    let mut guard = changes.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      change_request_key(namespace.as_str(), change.change_id.as_str()),
      change.clone(),
    );
  }
  save_change_request_store(changes, runtime)?;

  let run_exec = RunbookExecutionEntry {
    ns: namespace.clone(),
    exec_id: next_runbook_execution_id(),
    incident_id: incident_id.clone(),
    runbook_name: runbook.name.clone(),
    runbook_version: runbook.version.clone(),
    mode: mode.clone(),
    status: if auto_run {
      "running".to_string()
    } else {
      "queued".to_string()
    },
    created_ms: now,
    updated_ms: now,
    change_id: Some(change.change_id.clone()),
    reasons_json: json!({
      "incident_severity": incident.severity,
      "auto_run": auto_run,
    }),
    last_error: None,
  };
  {
    let store = get_runbook_execution_global()?;
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      runbook_execution_key(namespace.as_str(), run_exec.exec_id.as_str()),
      run_exec.clone(),
    );
    drop(guard);
    save_runbook_execution_store(&store, runtime)?;
  }

  {
    let incidents = get_incident_global()?;
    let mut guard = incidents.write().unwrap_or_else(|e| e.into_inner());
    if let Some(row) = guard
      .by_key
      .get_mut(&incident_key(namespace.as_str(), incident_id.as_str()))
    {
      row.runbook_last_execution_id = Some(run_exec.exec_id.clone());
      row.status = "mitigating".to_string();
      row.updated_ms = now_ms();
    }
    drop(guard);
    save_incident_store(&incidents, runtime)?;
  }
  let _ = append_incident_event(
    namespace.as_str(),
    incident_id.as_str(),
    "runbook_started",
    format!("runbook {} started", runbook.name),
    json!({
      "runbook_name": runbook.name,
      "runbook_version": runbook.version,
      "exec_id": run_exec.exec_id,
      "change_id": change.change_id,
      "auto_run": auto_run,
    }),
    runtime,
  )?;
  if auto_run {
    let _ = change_run_impl(
      ChangeByIdRequest {
        ns: Some(namespace.clone()),
        change_id: change.change_id.clone(),
      },
      namespace.as_str(),
      token_id,
      runtime,
      changes,
      job_store,
      events,
    )?;
  }
  Ok(json!({
    "ns": namespace,
    "execution": runbook_execution_view(&run_exec),
    "change": change_request_view(&change),
  }))
}

fn postmortem_generate_impl(
  request: PostmortemGenerateRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let incident_id = request.incident_id.trim().to_string();
  if incident_id.is_empty() {
    anyhow::bail!("postmortem.generate requires incident_id");
  }
  let incident = {
    let store = get_incident_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&incident_key(namespace.as_str(), incident_id.as_str()))
      .cloned()
      .with_context(|| format!("incident `{}` not found", incident_id))?
  };
  let timeline_count = {
    let events_store = get_incident_event_global()?;
    let guard = events_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace && entry.incident_id == incident_id)
      .count()
  };
  let entry = PostmortemEntry {
    ns: namespace.clone(),
    pm_id: request
      .pm_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
      .unwrap_or_else(next_postmortem_id),
    incident_id: incident_id.clone(),
    created_ms: now_ms(),
    status: "draft".to_string(),
    report_ref_id: request
      .report_ref_id
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string)
      .unwrap_or_else(|| format!("local:postmortem:{}", incident_id)),
    summary_json: json!({
      "incident_id": incident.incident_id,
      "title": incident.title,
      "severity": incident.severity,
      "status": incident.status,
      "timeline_count": timeline_count,
      "related_change_ids_json": incident.related_change_ids_json,
      "related_release_ids_json": incident.related_release_ids_json,
      "related_git_commits_json": incident.related_git_commits_json,
    }),
  };
  let store = get_postmortem_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      postmortem_key(namespace.as_str(), incident_id.as_str()),
      entry.clone(),
    );
  }
  save_postmortem_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "postmortem.generated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__incident__")),
    Some(incident_id),
    None,
    None,
    None,
    json!({ "postmortem": postmortem_view(&entry) }),
  );
  Ok(json!({
    "ns": namespace,
    "postmortem": postmortem_view(&entry),
  }))
}

