fn chaos_experiment_publish_impl(
  request: ChaosExperimentPublishRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("chaos.experiment.publish requires name");
  }
  let bundle_ref_id = request.bundle_ref_id.trim().to_string();
  if bundle_ref_id.is_empty() {
    anyhow::bail!("chaos.experiment.publish requires bundle_ref_id");
  }
  let sha256 = request.sha256.trim().to_ascii_lowercase();
  if sha256.len() < 8 {
    anyhow::bail!("chaos.experiment.publish requires sha256");
  }
  let exp_id = request
    .exp_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_chaos_experiment_id);
  let mut spec_json = request.spec_json.unwrap_or_else(|| json!({}));
  if !spec_json.is_object() {
    spec_json = json!({});
  }
  let entry = ChaosExperimentEntry {
    ns: namespace.clone(),
    exp_id: exp_id.clone(),
    name,
    bundle_ref_id,
    sha256,
    spec_json,
    status: normalize_chaos_experiment_status(request.status),
    updated_ms: now_ms(),
  };
  let store = get_chaos_experiment_global()?;
  {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      chaos_experiment_key(namespace.as_str(), exp_id.as_str()),
      entry.clone(),
    );
  }
  save_chaos_experiment_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "chaos.experiment.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__chaos__")),
    Some(exp_id),
    None,
    None,
    None,
    json!({ "experiment": chaos_experiment_view(&entry) }),
  );
  Ok(json!({
    "ns": namespace,
    "experiment": chaos_experiment_view(&entry),
  }))
}

