fn chaos_experiment_list_impl(
  request: ChaosExperimentListRequest,
  namespace: &str,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let status = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_chaos_experiment_status(Some(value.to_string())));
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase());
  let limit = request.limit.unwrap_or(200).clamp(1, 20_000);
  let store = get_chaos_experiment_global()?;
  let mut rows: Vec<ChaosExperimentEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .filter(|entry| {
        status
          .as_deref()
          .map(|value| entry.status == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|value| entry.name.to_ascii_lowercase().contains(value))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    b.updated_ms
      .cmp(&a.updated_ms)
      .then_with(|| a.name.cmp(&b.name))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "ns": namespace,
    "count": rows.len(),
    "items": rows.iter().map(chaos_experiment_view).collect::<Vec<_>>(),
  }))
}

