fn chaos_run_start_impl(
  request: ChaosRunStartRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
  changes: &Arc<RwLock<ChangeRequestStore>>,
  job_store: &Arc<RwLock<JobStore>>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let exp_id = request.exp_id.trim().to_string();
  if exp_id.is_empty() {
    anyhow::bail!("chaos.run.start requires exp_id");
  }
  let exp = {
    let store = get_chaos_experiment_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&chaos_experiment_key(namespace.as_str(), exp_id.as_str()))
      .cloned()
      .with_context(|| format!("chaos experiment `{}` not found", exp_id))?
  };
  if exp.status != "approved" && exp.status != "active" {
    anyhow::bail!(
      "chaos experiment `{}` must be approved/active before run (current `{}`)",
      exp_id,
      exp.status
    );
  }
  let now = now_ms();
  let change = ChangeRequestEntry {
    ns: namespace.clone(),
    change_id: next_change_id(),
    created_ms: now,
    updated_ms: now,
    title: format!("Chaos run {}", exp.name),
    reason: Some(format!("chaos experiment {}", exp_id)),
    source: "chaos".to_string(),
    risk: "high".to_string(),
    status: "proposed".to_string(),
    policy_id: None,
    invocation_id: None,
    session_id: None,
    plan_id: None,
    scheduled_start_ms: None,
    scheduled_end_ms: None,
    steps: build_plan_steps(vec![PlanStepRequest {
      kind: "noop".to_string(),
      spec: json!({
        "exp_id": exp_id,
      }),
    }]),
    approvals: Vec::new(),
    last_error: None,
  };
  {
    let mut guard = changes.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      change_request_key(namespace.as_str(), change.change_id.as_str()),
      change.clone(),
    );
  }
  save_change_request_store(changes, runtime)?;
  let _ = change_run_impl(
    ChangeByIdRequest {
      ns: Some(namespace.clone()),
      change_id: change.change_id.clone(),
    },
    namespace.as_str(),
    token_id,
    runtime,
    changes,
    job_store,
    events,
  )?;
  let run = ChaosRunEntry {
    ns: namespace.clone(),
    run_id: next_chaos_run_id(),
    exp_id: exp_id.clone(),
    created_ms: now,
    status: "running".to_string(),
    started_ms: Some(now),
    ended_ms: None,
    policy_eval_id: None,
    change_id: Some(change.change_id.clone()),
    result_ref_id: None,
    last_error: None,
  };
  let run_store = get_chaos_run_global()?;
  {
    let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      chaos_run_key(namespace.as_str(), run.run_id.as_str()),
      run.clone(),
    );
  }
  save_chaos_run_store(&run_store, runtime)?;
  let _ = append_chaos_event(
    namespace.as_str(),
    run.run_id.as_str(),
    "steady_state_ok",
    "pre-check completed".to_string(),
    json!({}),
    runtime,
  )?;
  let _ = append_chaos_event(
    namespace.as_str(),
    run.run_id.as_str(),
    "fault_injected",
    "fault injected (simulated)".to_string(),
    json!({
      "exp_id": exp_id,
    }),
    runtime,
  )?;
  publish_supervisor_event(
    events,
    "chaos.run.started",
    "warn",
    Some(scoped_logical_id(namespace.as_str(), "__chaos__")),
    Some(run.run_id.clone()),
    None,
    None,
    None,
    json!({
      "run": chaos_run_view(&run),
    }),
  );
  Ok(json!({
    "ns": namespace,
    "run": chaos_run_view(&run),
    "change": change_request_view(&change),
  }))
}

