fn chaos_run_get_impl(request: ChaosRunByIdRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let run_id = request.run_id.trim().to_string();
  if run_id.is_empty() {
    anyhow::bail!("chaos.run.get requires run_id");
  }
  let run = {
    let store = get_chaos_run_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&chaos_run_key(namespace.as_str(), run_id.as_str()))
      .cloned()
  };
  let timeline = {
    let store = get_chaos_event_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    let mut rows: Vec<ChaosEventEntry> = guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace && entry.run_id == run_id)
      .cloned()
      .collect();
    rows.sort_by(|a, b| a.ts_ms.cmp(&b.ts_ms));
    rows
  };
  Ok(json!({
    "ns": namespace,
    "run_id": run_id,
    "exists": run.is_some(),
    "run": run.as_ref().map(chaos_run_view),
    "timeline_count": timeline.len(),
    "timeline": timeline.iter().map(chaos_event_view).collect::<Vec<_>>(),
  }))
}

fn chaos_run_latest_impl(request: ChaosRunLatestRequest, namespace: &str) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let exp_id = request.exp_id.trim().to_string();
  if exp_id.is_empty() {
    anyhow::bail!("chaos.run.latest requires exp_id");
  }
  let row = {
    let store = get_chaos_run_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace && entry.exp_id == exp_id)
      .max_by(|a, b| {
        a.created_ms
          .cmp(&b.created_ms)
          .then_with(|| a.run_id.cmp(&b.run_id))
      })
      .cloned()
  };
  Ok(json!({
    "ns": namespace,
    "exp_id": exp_id,
    "exists": row.is_some(),
    "run": row.as_ref().map(chaos_run_view),
  }))
}

fn alert_evaluate_impl(
  request: AlertEvaluateRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let rule_id = request.rule_id.trim().to_string();
  if rule_id.is_empty() {
    anyhow::bail!("alert.evaluate requires rule_id");
  }
  let value_json = request.value_json.unwrap_or_else(|| json!({}));
  let rule = {
    let store = get_alert_rule_global()?;
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .get(&alert_rule_key(namespace.as_str(), rule_id.as_str()))
      .cloned()
      .with_context(|| format!("alert rule `{}` not found", rule_id))?
  };
  if rule.status != "active" {
    anyhow::bail!("alert rule `{}` is not active", rule_id);
  }
  let firing = evaluate_alert_condition(&rule.condition_json, &value_json);
  let dedupe_key = request
    .dedupe_key
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| {
      render_dedupe_key(
        rule.dedupe_key_template.as_str(),
        &value_json,
        namespace.as_str(),
        &rule,
      )
    });
  let now = now_ms();
  let (state, incident_opt) = {
    let state_store = get_alert_state_global()?;
    let incident_store = get_incident_global()?;
    let mut state_guard = state_store.write().unwrap_or_else(|e| e.into_inner());
    let mut incident_guard = incident_store.write().unwrap_or_else(|e| e.into_inner());
    let key = alert_state_key(namespace.as_str(), dedupe_key.as_str());
    let mut row = state_guard
      .by_key
      .get(&key)
      .cloned()
      .unwrap_or(AlertStateEntry {
        ns: namespace.clone(),
        dedupe_key: dedupe_key.clone(),
        rule_id: rule_id.clone(),
        first_seen_ms: now,
        last_seen_ms: now,
        firing: false,
        last_value_json: json!({}),
        incident_id: None,
      });
    row.last_seen_ms = now;
    row.firing = firing;
    row.last_value_json = if value_json.is_object() {
      value_json.clone()
    } else {
      json!({})
    };

    let mut incident_opt: Option<IncidentEntry> = None;
    if firing {
      if row.incident_id.is_none() {
        let incident_id = next_incident_id();
        let incident = IncidentEntry {
          ns: namespace.clone(),
          incident_id: incident_id.clone(),
          created_ms: now,
          updated_ms: now,
          severity: rule.severity.clone(),
          status: "open".to_string(),
          title: format!("{} fired", rule.name),
          primary_object_kind: rule.source_kind.clone(),
          primary_object_id: rule
            .selector_json
            .get("service_name")
            .and_then(Value::as_str)
            .or_else(|| rule.selector_json.get("route_id").and_then(Value::as_str))
            .or_else(|| rule.selector_json.get("node_id").and_then(Value::as_str))
            .unwrap_or(rule.rule_id.as_str())
            .to_string(),
          affected_json: json!({
            "selector_json": rule.selector_json,
            "dedupe_key": dedupe_key,
          }),
          owner_json: json!({}),
          acked_by: None,
          acked_ms: None,
          suspected_causes_json: json!([]),
          related_change_ids_json: json!([]),
          related_release_ids_json: json!([]),
          related_git_commits_json: json!([]),
          runbook_last_execution_id: None,
          resolution_json: json!({}),
        };
        incident_guard.by_key.insert(
          incident_key(namespace.as_str(), incident_id.as_str()),
          incident.clone(),
        );
        row.incident_id = Some(incident_id);
        incident_opt = Some(incident);
      } else if let Some(incident_id) = row.incident_id.clone() {
        if let Some(existing) = incident_guard
          .by_key
          .get_mut(&incident_key(namespace.as_str(), incident_id.as_str()))
        {
          existing.updated_ms = now;
          if existing.status == "monitoring" {
            existing.status = "open".to_string();
          }
          incident_opt = Some(existing.clone());
        }
      }
    } else if let Some(incident_id) = row.incident_id.as_ref() {
      if let Some(existing) = incident_guard
        .by_key
        .get_mut(&incident_key(namespace.as_str(), incident_id.as_str()))
      {
        if existing.status != "resolved" {
          existing.status = "monitoring".to_string();
        }
        existing.updated_ms = now;
        incident_opt = Some(existing.clone());
      }
    }
    state_guard.by_key.insert(key, row.clone());
    drop(incident_guard);
    drop(state_guard);
    save_alert_state_store(&state_store, runtime)?;
    save_incident_store(&incident_store, runtime)?;
    (row, incident_opt)
  };
  if let Some(incident) = incident_opt.as_ref() {
    let _ = append_incident_event(
      namespace.as_str(),
      incident.incident_id.as_str(),
      if firing {
        "alert_fired"
      } else {
        "alert_cleared"
      },
      if firing {
        format!("rule {} fired", rule.name)
      } else {
        format!("rule {} cleared", rule.name)
      },
      json!({
        "rule_id": rule.rule_id,
        "dedupe_key": dedupe_key,
        "firing": firing,
        "value_json": value_json,
      }),
      runtime,
    )?;
  }
  publish_supervisor_event(
    events,
    if firing {
      "alert.firing"
    } else {
      "alert.clear"
    },
    if firing { "warn" } else { "info" },
    Some(scoped_logical_id(namespace.as_str(), "__alert__")),
    Some(rule.rule_id.clone()),
    None,
    None,
    None,
    json!({
      "rule_id": rule.rule_id,
      "firing": firing,
      "dedupe_key": dedupe_key,
      "incident_id": state.incident_id,
    }),
  );
  Ok(json!({
    "ns": namespace,
    "rule": alert_rule_view(&rule),
    "alert_state": alert_state_view(&state),
    "incident": incident_opt.as_ref().map(incident_view),
  }))
}

fn tenant_for_namespace(namespace: &str) -> Option<TenantEntry> {
  let tenant_ns_store = get_tenant_namespace_global().ok()?;
  let tenant_store = get_tenant_global().ok()?;
  let tenant_id = {
    let guard = tenant_ns_store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.ns == namespace)
      .max_by(|a, b| a.created_ms.cmp(&b.created_ms))
      .map(|entry| entry.tenant_id.clone())
  }?;
  let guard = tenant_store.read().unwrap_or_else(|e| e.into_inner());
  guard.by_id.get(tenant_id.as_str()).cloned()
}

fn latest_budget_state_for_tenant(tenant_id: &str) -> Option<BudgetStateEntry> {
  let budget_store = get_budget_state_global().ok()?;
  let guard = budget_store.read().unwrap_or_else(|e| e.into_inner());
  guard
    .by_key
    .values()
    .filter(|entry| entry.tenant_id == tenant_id)
    .max_by(|a, b| a.last_change_ms.cmp(&b.last_change_ms))
    .cloned()
}

fn tenant_create_impl(
  request: TenantCreateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let name = request.name.trim();
  if name.is_empty() {
    anyhow::bail!("tenant.create requires name");
  }
  let tenant_id = request
    .tenant_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_tenant_id);
  let status = normalize_tenant_status(request.status);
  let owner_json = request.owner_json.unwrap_or_else(|| json!({}));
  let store = get_tenant_global()?;
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard
      .by_id
      .values()
      .any(|entry| entry.name.eq_ignore_ascii_case(name) && entry.tenant_id != tenant_id)
    {
      anyhow::bail!("tenant.create name `{}` already exists", name);
    }
    let now = now_ms();
    let created_ms = guard
      .by_id
      .get(tenant_id.as_str())
      .map(|entry| entry.created_ms)
      .unwrap_or(now);
    let entry = TenantEntry {
      tenant_id: tenant_id.clone(),
      name: name.to_string(),
      owner_json: if owner_json.is_object() {
        owner_json
      } else {
        json!({})
      },
      status,
      created_ms,
      updated_ms: now,
    };
    guard.by_id.insert(tenant_id.clone(), entry.clone());
    entry
  };
  save_tenant_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "tenant.created",
    "info",
    Some(scoped_logical_id(DEFAULT_NAMESPACE, "__tenant__")),
    Some(updated.tenant_id.clone()),
    None,
    None,
    None,
    json!({
      "tenant": tenant_view(&updated),
    }),
  );
  Ok(json!({
    "tenant": tenant_view(&updated),
  }))
}

fn tenant_get_impl(request: TenantByIdRequest) -> Result<Value> {
  let tenant_id = request.tenant_id.trim();
  if tenant_id.is_empty() {
    anyhow::bail!("tenant.get requires tenant_id");
  }
  let store = get_tenant_global()?;
  let tenant = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard.by_id.get(tenant_id).cloned()
  };
  Ok(json!({
    "tenant_id": tenant_id,
    "exists": tenant.is_some(),
    "tenant": tenant.as_ref().map(tenant_view),
  }))
}

fn tenant_list_impl(request: TenantListRequest) -> Result<Value> {
  let status_filter = request
    .status
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| normalize_tenant_status(Some(value.to_string())));
  let name_filter = request
    .name
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_lowercase());
  let limit = request.limit.unwrap_or(200).clamp(1, 5_000);
  let store = get_tenant_global()?;
  let mut rows: Vec<TenantEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_id
      .values()
      .filter(|entry| {
        status_filter
          .as_deref()
          .map(|status| entry.status == *status)
          .unwrap_or(true)
      })
      .filter(|entry| {
        name_filter
          .as_deref()
          .map(|needle| entry.name.to_ascii_lowercase().contains(needle))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| {
    a.name
      .cmp(&b.name)
      .then_with(|| a.tenant_id.cmp(&b.tenant_id))
      .then_with(|| b.updated_ms.cmp(&a.updated_ms))
  });
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "count": rows.len(),
    "items": rows.iter().map(tenant_view).collect::<Vec<_>>(),
  }))
}

fn tenant_update_impl(
  request: TenantUpdateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let tenant_id = request.tenant_id.trim();
  if tenant_id.is_empty() {
    anyhow::bail!("tenant.update requires tenant_id");
  }
  let store = get_tenant_global()?;
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let proposed_name = request
      .name
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    if let Some(name) = proposed_name.as_ref() {
      if guard
        .by_id
        .values()
        .any(|entry| entry.tenant_id != tenant_id && entry.name.eq_ignore_ascii_case(name))
      {
        anyhow::bail!("tenant.update name `{}` already exists", name);
      }
    }
    let entry = guard
      .by_id
      .get_mut(tenant_id)
      .with_context(|| format!("tenant `{}` not found", tenant_id))?;
    if let Some(name) = proposed_name {
      entry.name = name;
    }
    if let Some(owner_json) = request.owner_json {
      entry.owner_json = if owner_json.is_object() {
        owner_json
      } else {
        json!({})
      };
    }
    if request.status.is_some() {
      entry.status = normalize_tenant_status(request.status);
    }
    entry.updated_ms = now_ms();
    entry.clone()
  };
  save_tenant_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "tenant.updated",
    "info",
    Some(scoped_logical_id(DEFAULT_NAMESPACE, "__tenant__")),
    Some(updated.tenant_id.clone()),
    None,
    None,
    None,
    json!({
      "tenant": tenant_view(&updated),
    }),
  );
  Ok(json!({
    "tenant": tenant_view(&updated),
  }))
}

fn tenant_suspend_impl(
  request: TenantByIdRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  tenant_update_impl(
    TenantUpdateRequest {
      tenant_id: request.tenant_id,
      name: None,
      owner_json: None,
      status: Some("suspended".to_string()),
    },
    runtime,
    events,
  )
}

fn tenant_attach_namespace_impl(
  request: TenantNamespaceAttachRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let tenant_id = request.tenant_id.trim().to_string();
  if tenant_id.is_empty() {
    anyhow::bail!("tenant.attach_namespace requires tenant_id");
  }
  let namespace = normalize_namespace(request.ns)?;
  let tenant_store = get_tenant_global()?;
  {
    let guard = tenant_store.read().unwrap_or_else(|e| e.into_inner());
    if !guard.by_id.contains_key(tenant_id.as_str()) {
      anyhow::bail!("tenant `{}` not found", tenant_id);
    }
  }
  let namespace_store = get_tenant_namespace_global()?;
  let key = tenant_namespace_key(tenant_id.as_str(), namespace.as_str());
  let updated = {
    let mut guard = namespace_store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|entry| entry.created_ms)
      .unwrap_or_else(now_ms);
    let entry = TenantNamespaceEntry {
      tenant_id: tenant_id.clone(),
      ns: namespace.clone(),
      created_ms,
    };
    guard.by_key.insert(key, entry.clone());
    entry
  };
  save_tenant_namespace_store(&namespace_store, runtime)?;
  publish_supervisor_event(
    events,
    "tenant.namespace.attached",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__tenant__")),
    Some(tenant_id.clone()),
    None,
    None,
    None,
    json!({
      "mapping": tenant_namespace_view(&updated),
    }),
  );
  Ok(json!({
    "mapping": tenant_namespace_view(&updated),
  }))
}

fn tenant_detach_namespace_impl(
  request: TenantNamespaceDetachRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let tenant_id = request.tenant_id.trim().to_string();
  if tenant_id.is_empty() {
    anyhow::bail!("tenant.detach_namespace requires tenant_id");
  }
  let namespace = normalize_namespace(request.ns)?;
  let namespace_store = get_tenant_namespace_global()?;
  let key = tenant_namespace_key(tenant_id.as_str(), namespace.as_str());
  let removed = {
    let mut guard = namespace_store.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.remove(&key)
  };
  if removed.is_some() {
    save_tenant_namespace_store(&namespace_store, runtime)?;
    publish_supervisor_event(
      events,
      "tenant.namespace.detached",
      "warn",
      Some(scoped_logical_id(namespace.as_str(), "__tenant__")),
      Some(tenant_id.clone()),
      None,
      None,
      None,
      json!({
        "tenant_id": tenant_id,
        "ns": namespace,
      }),
    );
  }
  Ok(json!({
    "tenant_id": tenant_id,
    "ns": namespace,
    "removed": removed.is_some(),
  }))
}

