fn usage_query_impl(request: UsageQueryRequest) -> Result<Value> {
  let tenant_id = request.tenant_id.trim().to_string();
  if tenant_id.is_empty() {
    anyhow::bail!("usage.query requires tenant_id");
  }
  let namespace_filter = request
    .ns
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let region_filter = request
    .region
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string);
  let from_ts_ms = request.from_ts_ms.unwrap_or(0);
  let to_ts_ms = request.to_ts_ms.unwrap_or(u128::MAX);
  let limit = request.limit.unwrap_or(500).clamp(1, 20_000);
  let store = get_usage_rollup_global()?;
  let mut rows: Vec<UsageRollupEntry> = {
    let guard = store.read().unwrap_or_else(|e| e.into_inner());
    guard
      .by_key
      .values()
      .filter(|entry| entry.tenant_id == tenant_id)
      .filter(|entry| entry.ts_ms >= from_ts_ms && entry.ts_ms <= to_ts_ms)
      .filter(|entry| {
        namespace_filter
          .as_deref()
          .map(|value| entry.ns == *value)
          .unwrap_or(true)
      })
      .filter(|entry| {
        region_filter
          .as_deref()
          .map(|value| entry.region.as_deref() == Some(value))
          .unwrap_or(true)
      })
      .cloned()
      .collect()
  };
  rows.sort_by(|a, b| b.ts_ms.cmp(&a.ts_ms).then_with(|| a.ns.cmp(&b.ns)));
  if rows.len() > limit {
    rows.truncate(limit);
  }
  Ok(json!({
    "tenant_id": tenant_id,
    "count": rows.len(),
    "items": rows.iter().map(usage_rollup_view).collect::<Vec<_>>(),
  }))
}

