fn rate_card_create_impl(
  request: RateCardCreateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let name = request.name.trim().to_string();
  if name.is_empty() {
    anyhow::bail!("rate_card.create requires name");
  }
  let card_id = request
    .card_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_rate_card_id);
  let currency = request
    .currency
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(|value| value.to_ascii_uppercase())
    .unwrap_or_else(|| "USD".to_string());
  let status = normalize_rate_card_status(request.status);
  let rates_json = request.rates_json.unwrap_or_else(|| json!({}));
  let valid_to_ms = match request.valid_to_ms {
    Some(value) if value > request.valid_from_ms => Some(value),
    _ => None,
  };
  let store = get_rate_card_global()?;
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    if guard
      .by_id
      .values()
      .any(|entry| entry.name.eq_ignore_ascii_case(name.as_str()) && entry.card_id != card_id)
    {
      anyhow::bail!("rate_card.create name `{}` already exists", name);
    }
    let created_ms = guard
      .by_id
      .get(card_id.as_str())
      .map(|entry| entry.created_ms)
      .unwrap_or_else(now_ms);
    let entry = RateCardEntry {
      card_id: card_id.clone(),
      name,
      currency,
      rates_json: if rates_json.is_object() {
        rates_json
      } else {
        json!({})
      },
      valid_from_ms: request.valid_from_ms,
      valid_to_ms,
      status,
      created_ms,
    };
    guard.by_id.insert(card_id.clone(), entry.clone());
    entry
  };
  save_rate_card_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "rate.card.updated",
    "info",
    Some(scoped_logical_id(DEFAULT_NAMESPACE, "__rate_card__")),
    None,
    None,
    None,
    None,
    json!({
      "card_id": updated.card_id,
      "name": updated.name,
      "currency": updated.currency,
      "status": updated.status,
      "valid_from_ms": updated.valid_from_ms,
      "valid_to_ms": updated.valid_to_ms,
    }),
  );
  Ok(json!({
    "rate_card": rate_card_view(&updated),
  }))
}

fn rate_card_activate_impl(
  request: RateCardActivateRequest,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let card_id = request.card_id.trim();
  if card_id.is_empty() {
    anyhow::bail!("rate_card.activate requires card_id");
  }
  let store = get_rate_card_global()?;
  let updated = {
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    let Some(target_currency) = guard.by_id.get(card_id).map(|row| row.currency.clone()) else {
      anyhow::bail!("rate card `{}` not found", card_id);
    };
    for entry in guard.by_id.values_mut() {
      if entry.currency == target_currency && entry.card_id != card_id && entry.status == "active" {
        entry.status = "deprecated".to_string();
      }
    }
    let target = guard
      .by_id
      .get_mut(card_id)
      .expect("target rate card exists");
    target.status = "active".to_string();
    target.clone()
  };
  save_rate_card_store(&store, runtime)?;
  publish_supervisor_event(
    events,
    "rate.card.activated",
    "info",
    Some(scoped_logical_id(DEFAULT_NAMESPACE, "__rate_card__")),
    None,
    None,
    None,
    None,
    json!({
      "card_id": updated.card_id,
      "currency": updated.currency,
      "status": updated.status,
    }),
  );
  Ok(json!({
    "rate_card": rate_card_view(&updated),
  }))
}

