fn pki_cert_revoke_impl(
  request: PkiCertRevokeRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let cert_id = request.cert_id.trim();
  if cert_id.is_empty() {
    anyhow::bail!("pki.cert.revoke requires cert_id");
  }
  let cert_store = get_pki_cert_global()?;
  let key = pki_cert_key(namespace.as_str(), cert_id);
  let updated = {
    let mut guard = cert_store.write().unwrap_or_else(|e| e.into_inner());
    let entry = guard
      .by_key
      .get_mut(&key)
      .with_context(|| format!("pki cert `{}` not found", cert_id))?;
    entry.status = "revoked".to_string();
    entry.updated_ms = now_ms();
    entry.last_error = request
      .reason
      .as_deref()
      .map(str::trim)
      .filter(|value| !value.is_empty())
      .map(str::to_string);
    entry.clone()
  };
  save_pki_cert_store(&cert_store, runtime)?;
  publish_supervisor_event(
    events,
    "pki.cert.revoked",
    "warn",
    Some(scoped_logical_id(namespace.as_str(), "__pki__")),
    Some(cert_id.to_string()),
    None,
    None,
    None,
    json!({ "cert": pki_cert_view(&updated) }),
  );
  Ok(json!({
    "ns": namespace,
    "cert": pki_cert_view(&updated),
  }))
}

fn git_source_upsert_impl(
  request: GitSourceUpsertRequest,
  namespace: &str,
  runtime: &RuntimeConfig,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let source_id = request
    .source_id
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(next_git_source_id);
  let name = request.name.trim().to_string();
  let connector_id = request.connector_id.trim().to_string();
  let repo_url = request.repo_url.trim().to_string();
  let branch = request
    .branch
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "main".to_string());
  let subdir = request
    .subdir
    .as_deref()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(str::to_string)
    .unwrap_or_else(|| "pnix".to_string());
  if name.is_empty() || connector_id.is_empty() || repo_url.is_empty() {
    anyhow::bail!("gitops.source.add requires name, connector_id, repo_url");
  }
  let mode = normalize_git_source_mode(request.mode);
  let status = normalize_git_source_status(request.status);
  let source_store = get_git_source_global()?;
  let key = git_source_key(namespace.as_str(), source_id.as_str());
  let updated = {
    let mut guard = source_store.write().unwrap_or_else(|e| e.into_inner());
    let created_ms = guard
      .by_key
      .get(&key)
      .map(|entry| entry.created_ms)
      .unwrap_or_else(now_ms);
    let entry = GitSourceEntry {
      ns: namespace.clone(),
      source_id: source_id.clone(),
      name: name.clone(),
      connector_id: connector_id.clone(),
      repo_url: repo_url.clone(),
      branch: branch.clone(),
      subdir,
      mode,
      policy_json: request.policy_json.unwrap_or_else(|| json!({})),
      status,
      created_ms,
      updated_ms: now_ms(),
    };
    guard.by_key.insert(key, entry.clone());
    entry
  };
  save_git_source_store(&source_store, runtime)?;
  publish_supervisor_event(
    events,
    "gitops.source.updated",
    "info",
    Some(scoped_logical_id(namespace.as_str(), "__gitops__")),
    Some(source_id.clone()),
    None,
    None,
    None,
    json!({ "source": git_source_view(&updated) }),
  );
  Ok(json!({
    "ns": namespace,
    "source": git_source_view(&updated),
  }))
}

