fn remediation_plan_escalate_impl(
  request: RemediationPlanEscalateRequest,
  namespace: &str,
  token_id: &str,
  runtime: &RuntimeConfig,
  plans: &Arc<RwLock<RemediationPlanStore>>,
  changes: &Arc<RwLock<ChangeRequestStore>>,
  job_store: &Arc<RwLock<JobStore>>,
  events: &Arc<SharedEvents>,
) -> Result<Value> {
  let namespace = normalize_namespace(request.ns.unwrap_or_else(|| namespace.to_string()))?;
  let plan_key = remediation_plan_key(namespace.as_str(), request.plan_id.as_str());
  let (plan_id, source, risk, reason, title, invocation_id, session_id, steps) = {
    let guard = plans.read().unwrap_or_else(|e| e.into_inner());
    let plan = guard
      .by_key
      .get(&plan_key)
      .with_context(|| format!("remediation plan `{}` not found", request.plan_id))?;
    (
      plan.plan_id.clone(),
      request
        .source
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("remediation")
        .to_string(),
      normalize_risk(request.risk.as_deref(), plan.risk.as_str()),
      request.reason.or_else(|| Some(plan.summary.clone())),
      request
        .title
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| format!("Remediation escalation {}", plan.plan_id)),
      plan.invocation_id.clone(),
      plan.session_id.clone(),
      plan.steps.clone(),
    )
  };

  let now = now_ms();
  let change = ChangeRequestEntry {
    ns: namespace.clone(),
    change_id: next_change_id(),
    created_ms: now,
    updated_ms: now,
    title,
    reason,
    source,
    risk,
    status: "proposed".to_string(),
    policy_id: None,
    invocation_id,
    session_id,
    plan_id: Some(plan_id.clone()),
    scheduled_start_ms: None,
    scheduled_end_ms: None,
    steps,
    approvals: Vec::new(),
    last_error: None,
  };
  {
    let mut guard = changes.write().unwrap_or_else(|e| e.into_inner());
    guard.by_key.insert(
      change_request_key(namespace.as_str(), change.change_id.as_str()),
      change.clone(),
    );
  }
  save_change_request_store(changes, runtime)?;
  {
    let mut guard = plans.write().unwrap_or_else(|e| e.into_inner());
    if let Some(plan) = guard.by_key.get_mut(&plan_key) {
      plan.change_id = Some(change.change_id.clone());
      plan.status = "escalated".to_string();
      plan.updated_ms = now;
    }
  }
  save_remediation_plan_store(plans, runtime)?;
  publish_supervisor_event(
    events,
    "remediation.plan.escalated",
    "warn",
    Some(scoped_logical_id(namespace.as_str(), "__change__")),
    None,
    None,
    None,
    None,
    json!({
      "ns": namespace,
      "plan_id": plan_id,
      "change_id": change.change_id,
      "token_id": token_id,
    }),
  );

  let mut response = json!({
    "ns": namespace,
    "plan_id": plan_id,
    "change": change_request_view(&change),
  });

  if request.auto_run.unwrap_or(false) {
    let run_out = change_run_impl(
      ChangeByIdRequest {
        ns: Some(namespace.clone()),
        change_id: change.change_id.clone(),
      },
      namespace.as_str(),
      token_id,
      runtime,
      changes,
      job_store,
      events,
    )?;
    response["auto_run"] = run_out;
  }

  Ok(response)
}

