  #[test]
  fn drift_policy_accepts_replace_and_rolling() {
    let replace: DriftPolicy =
      serde_json::from_str("\"replace\"").expect("deserialize replace drift policy");
    let rolling: DriftPolicy =
      serde_json::from_str("\"rolling\"").expect("deserialize rolling drift policy");

    assert!(matches!(replace, DriftPolicy::Replace));
    assert!(matches!(rolling, DriftPolicy::Rolling));
    assert_eq!(drift_restart_tag(&replace), Some("replaced"));
    assert_eq!(drift_restart_tag(&rolling), Some("rolling_restarted"));
  }

