  #[test]
  fn claim_next_job_uses_stable_tiebreak_for_same_priority_and_time() {
    let runtime = test_runtime_config("job-claim-stable-tiebreak");
    let job_store = Arc::new(RwLock::new(JobStore::default()));
    let created_ms = now_ms();

    let make_job = |job_id: &str| JobEntry {
      ns: DEFAULT_NAMESPACE.to_string(),
      job_id: job_id.to_string(),
      kind: "change.execute".to_string(),
      params_json: json!({}),
      dedupe_key: None,
      priority: 50,
      state: "queued".to_string(),
      created_ms,
      updated_ms: created_ms,
      token_id: None,
      invocation_id: None,
      session_id: None,
      worker_id: None,
      lease_until_ms: None,
      attempt: 0,
      max_attempt: 1,
      next_run_ms: None,
      last_error: None,
      reason_code: None,
      progress: None,
      stage: None,
      result_json: None,
      cancel_requested: false,
      id_prefixes: Vec::new(),
      logs: Vec::new(),
    };

    {
      let mut guard = job_store.write().unwrap_or_else(|e| e.into_inner());
      for job_id in ["job-z", "job-a", "job-m"] {
        let job = make_job(job_id);
        guard
          .by_key
          .insert(job_key(DEFAULT_NAMESPACE, job_id), job.clone());
      }
    }

    let first = claim_next_job(&runtime, "worker-1", &job_store)
      .expect("claim first")
      .expect("first job");
    let second = claim_next_job(&runtime, "worker-1", &job_store)
      .expect("claim second")
      .expect("second job");
    let third = claim_next_job(&runtime, "worker-1", &job_store)
      .expect("claim third")
      .expect("third job");

    assert_eq!(first.job_id, "job-a");
    assert_eq!(second.job_id, "job-m");
    assert_eq!(third.job_id, "job-z");

    cleanup_runtime(&runtime);
  }

  #[test]
  fn job_submit_dedupes_inflight_job_and_emits_join_event() {
    let _phase60_63_guard = phase60_63_test_guard();
    reset_phase60_63_globals();
    let runtime = test_runtime_config("job-dedup-inflight-join");
    let events = Arc::new(SharedEvents::new(256));
    let job_store = Arc::new(RwLock::new(JobStore::default()));

    let first_submit = job_submit_impl(
      JobSubmitRequest {
        ns: Some(DEFAULT_NAMESPACE.to_string()),
        kind: "change.execute".to_string(),
        params: json!({
          "ns": DEFAULT_NAMESPACE,
          "change_id": "chg-dedup-join",
        }),
        priority: Some(50),
        dedupe_key: Some("dedupe:change.execute:join".to_string()),
        invocation_id: None,
        session_id: None,
        max_attempt: Some(1),
      },
      DEFAULT_NAMESPACE,
      "token-test",
      &[],
      &runtime,
      &job_store,
      &events,
    )
    .expect("submit first job");

    let first_job_id = first_submit
      .get("job_id")
      .and_then(Value::as_str)
      .expect("first job_id")
      .to_string();

    let claimed = claim_next_job(&runtime, "worker-join", &job_store)
      .expect("claim queued job")
      .expect("queued job exists");
    assert_eq!(claimed.job_id, first_job_id);
    assert_eq!(claimed.state, "running");

    let second_submit = job_submit_impl(
      JobSubmitRequest {
        ns: Some(DEFAULT_NAMESPACE.to_string()),
        kind: "change.execute".to_string(),
        params: json!({
          "ns": DEFAULT_NAMESPACE,
          "change_id": "chg-dedup-join",
        }),
        priority: Some(50),
        dedupe_key: Some("dedupe:change.execute:join".to_string()),
        invocation_id: None,
        session_id: None,
        max_attempt: Some(1),
      },
      DEFAULT_NAMESPACE,
      "token-test",
      &[],
      &runtime,
      &job_store,
      &events,
    )
    .expect("submit second job");

    assert_eq!(second_submit.get("deduped"), Some(&json!(true)));
    assert_eq!(
      second_submit.get("job_id"),
      Some(&json!(first_job_id.clone()))
    );

    let filter = EventFilter {
      kinds: vec!["job.joined".to_string()],
      namespaces: vec![DEFAULT_NAMESPACE.to_string()],
      ..EventFilter::default()
    };
    let (_, joined_events, _) = events.poll_since(0, 64, Some(&filter));
    assert!(
      joined_events.iter().any(|event| {
        event.kind == "job.joined"
          && event.payload.get("job_id") == Some(&json!(first_job_id))
          && event.payload.get("state") == Some(&json!("running"))
      }),
      "job.joined event with running target is required for inflight join"
    );

    cleanup_runtime(&runtime);
  }

