  #[test]
  fn breakglass_session_heartbeat_renews_active_session() {
    let _phase60_63_guard = phase60_63_test_guard();
    reset_phase60_63_globals();
    let runtime = test_runtime_config("breakglass-session-heartbeat-renew");
    let events = Arc::new(SharedEvents::new(256));
    let changes = Arc::new(RwLock::new(ChangeRequestStore::default()));
    let job_store = Arc::new(RwLock::new(JobStore::default()));

    let requested = breakglass_request_impl(
      BreakglassRequestRequest {
        ns: Some(DEFAULT_NAMESPACE.to_string()),
        reason: "capture stream".to_string(),
        duration_ms: Some(20_000),
        required_approvals: Some(1),
        required_roles_json: Some(json!(["operator"])),
        scope_json: Some(json!({
          "indicator_required": true,
          "indicator_grace_ms": 10_000,
          "active_grants_json": ["grant-capture-1"],
          "cap_ceiling_json": {"allow": ["os.capture.stream"]},
        })),
      },
      DEFAULT_NAMESPACE,
      "token-requester",
      &runtime,
      &events,
    )
    .expect("create breakglass session");
    let session_id = requested
      .pointer("/session/session_id")
      .and_then(Value::as_str)
      .expect("session_id")
      .to_string();
    let approval_id = requested
      .pointer("/approval/approval_id")
      .and_then(Value::as_str)
      .expect("approval_id")
      .to_string();

    approval_vote_impl(
      ApprovalVoteRequest {
        ns: Some(DEFAULT_NAMESPACE.to_string()),
        approval_id,
        vote: "approve".to_string(),
        comment: None,
      },
      DEFAULT_NAMESPACE,
      "operator",
      &runtime,
      &events,
      &changes,
      &job_store,
    )
    .expect("approve breakglass session");

    let before_expires_ms = {
      let store = get_human_ops_global().expect("human ops");
      let guard = store.read().unwrap_or_else(|e| e.into_inner());
      guard
        .breakglass_sessions
        .get(&breakglass_session_key(
          DEFAULT_NAMESPACE,
          session_id.as_str(),
        ))
        .map(|row| row.expires_ms)
        .expect("session exists")
    };

    let heartbeat = breakglass_session_heartbeat_impl(
      BreakglassSessionHeartbeatRequest {
        ns: Some(DEFAULT_NAMESPACE.to_string()),
        session_id: session_id.clone(),
        indicator_state: Some("alive".to_string()),
        renew_ms: Some(45_000),
        active_grants_json: Some(json!(["grant-capture-1", "grant-capture-2"])),
      },
      DEFAULT_NAMESPACE,
      "indicator-agent",
      &runtime,
      &events,
    )
    .expect("heartbeat renew");
    assert_eq!(
      heartbeat.pointer("/session/status"),
      Some(&json!("active")),
      "heartbeat should keep session active"
    );
    assert_eq!(
      heartbeat.pointer("/session/indicator_state"),
      Some(&json!("alive")),
      "heartbeat should mark indicator alive"
    );
    let after_expires_ms = heartbeat
      .pointer("/session/expires_ms")
      .and_then(Value::as_u64)
      .expect("expires_ms after heartbeat") as u128;
    assert!(
      after_expires_ms > before_expires_ms,
      "heartbeat renew must extend expires_ms"
    );
    assert_eq!(
      heartbeat.pointer("/renew_denied_reason"),
      Some(&Value::Null),
      "renew should not be denied when indicator is alive"
    );

    cleanup_runtime(&runtime);
  }

  fn seed_breakglass_active_sessions(namespace: &str, count: usize) {
    let now = now_ms();
    let store = get_human_ops_global().expect("human ops");
    let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
    for idx in 0..count {
      let session_id = format!("seed-active-{}-{}", now, idx);
      let row = BreakglassSessionEntry {
        ns: namespace.to_string(),
        session_id: session_id.clone(),
        requested_by: "seed".to_string(),
        reason: "quota-seed".to_string(),
        approvals_json: json!([]),
        starts_ms: now,
        expires_ms: now.saturating_add(60 * 60 * 1000),
        status: "active".to_string(),
        indicator_required: false,
        indicator_state: "disabled".to_string(),
        last_heartbeat_ms: None,
        indicator_grace_ms: BREAKGLASS_INDICATOR_GRACE_MS_DEFAULT,
        active_grants_json: json!([]),
        cap_ceiling_json: json!([]),
        consent_compile_json: json!({"kind": "ConsentCompileGrantResult"}),
        consent_compile_cache_json: Value::Null,
        consent_audit_json: Value::Null,
      };
      guard
        .breakglass_sessions
        .insert(breakglass_session_key(namespace, session_id.as_str()), row);
    }
  }

