  #[test]
  fn breakglass_lease_accounting_and_quota_enforcer_work() {
    let now = now_ms();
    let snapshot = json!({
      "items": [
        {
          "status": "active",
          "expires_ms": now.saturating_add(30_000),
          "indicator_state": "alive",
          "active_grants_json": [
            {"grant_id": "g1", "status": "active"},
            {"grant_id": "g2", "status": "revoked"}
          ]
        },
        {
          "status": "active",
          "expires_ms": now.saturating_add(30_000),
          "indicator_state": "alive",
          "active_grants_json": [
            {"grant_id": "g3", "status": "active"}
          ]
        },
        {
          "status": "pending",
          "expires_ms": now.saturating_sub(1),
          "indicator_state": "lost",
          "active_grants_json": []
        }
      ]
    });

    let accounting = breakglass_lease_accounting_snapshot(&snapshot, now);
    assert_eq!(accounting.pointer("/totals/sessions"), Some(&json!(3)));
    assert_eq!(
      accounting.pointer("/totals/sessions_active"),
      Some(&json!(2))
    );
    assert_eq!(accounting.pointer("/totals/active_grants"), Some(&json!(2)));
    assert_eq!(
      accounting.pointer("/totals/stale_sessions"),
      Some(&json!(1))
    );
    assert_eq!(
      accounting.pointer("/totals/indicator_lost_sessions"),
      Some(&json!(1))
    );

    let ok_decision = breakglass_quota_enforcer_decision(&accounting);
    assert_eq!(ok_decision.get("decision"), Some(&json!("allow")));
    assert_eq!(ok_decision.get("reason_code"), Some(&json!("QUOTA_OK")));

    let throttle_decision = breakglass_quota_enforcer_decision(&json!({
      "totals": {
        "sessions_active": 7,
        "active_grants": 10
      }
    }));
    assert_eq!(throttle_decision.get("decision"), Some(&json!("throttle")));
    assert_eq!(
      throttle_decision.get("reason_code"),
      Some(&json!("QUOTA_NEAR_LIMIT"))
    );

    let close_decision = breakglass_quota_enforcer_decision(&json!({
      "totals": {
        "sessions_active": 9,
        "active_grants": 40
      }
    }));
    assert_eq!(close_decision.get("decision"), Some(&json!("close")));
    assert_eq!(
      close_decision.get("reason_code"),
      Some(&json!("QUOTA_EXCEEDED"))
    );
  }

