  #[test]
  fn phase64_product_edition_store_roundtrip() {
    let runtime = test_runtime_config("edition");
    let store = Arc::new(RwLock::new(ProductEditionStore::default()));
    {
      let mut guard = store.write().unwrap_or_else(|e| e.into_inner());
      let row = ProductEditionEntry {
        org: "orgA".to_string(),
        edition_id: "edn_test".to_string(),
        name: "pnix-team".to_string(),
        tier: "TEAM".to_string(),
        features_json: json!({"marketplace": true}),
        governance_json: json!({"approval_required": true}),
        status: "ACTIVE".to_string(),
        created_ms: 1,
        updated_ms: 2,
      };
      guard
        .by_key
        .insert(product_edition_key("orgA", "edn_test"), row);
    }
    save_product_edition_store(&store, &runtime).expect("save product edition store");
    let loaded = load_product_edition_store(&runtime).expect("load product edition store");
    let row = loaded
      .by_key
      .get(&product_edition_key("orgA", "edn_test"))
      .expect("roundtrip row");
    assert_eq!(row.tier, "team");
    assert_eq!(row.status, "active");
    assert_eq!(row.name, "pnix-team");
    cleanup_runtime(&runtime);
  }

  #[test]
  fn phase64_migration_playbook_and_run_roundtrip() {
    let runtime = test_runtime_config("migration");
    let playbook_store = Arc::new(RwLock::new(MigrationPlaybookStore::default()));
    {
      let mut guard = playbook_store.write().unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        migration_playbook_key("orgA", "mpb_1"),
        MigrationPlaybookEntry {
          org: "orgA".to_string(),
          playbook_id: "mpb_1".to_string(),
          name: "argo-to-pnix".to_string(),
          source_stack: "argo".to_string(),
          target_profile: "pnix-full".to_string(),
          track: "CONTROLLED_ACTIONS".to_string(),
          phases_json: json!([{"name":"overlay"}]),
          rollback_json: json!({"mode":"revert_pr"}),
          status: "ACTIVE".to_string(),
          created_ms: 10,
          updated_ms: 20,
        },
      );
    }
    save_migration_playbook_store(&playbook_store, &runtime).expect("save playbook store");
    let loaded_playbook = load_migration_playbook_store(&runtime).expect("load playbook store");
    let playbook = loaded_playbook
      .by_key
      .get(&migration_playbook_key("orgA", "mpb_1"))
      .expect("loaded playbook");
    assert_eq!(playbook.track, "controlled_actions");
    assert_eq!(playbook.status, "active");

    let run_store = Arc::new(RwLock::new(MigrationRunStore::default()));
    {
      let mut guard = run_store.write().unwrap_or_else(|e| e.into_inner());
      guard.by_key.insert(
        migration_run_key("orgA", "mrn_1"),
        MigrationRunEntry {
          org: "orgA".to_string(),
          run_id: "mrn_1".to_string(),
          playbook_id: "mpb_1".to_string(),
          project_id: "projA".to_string(),
          phase: "overlay".to_string(),
          status: "FAILED".to_string(),
          started_ms: 100,
          ended_ms: Some(200),
          summary_json: json!({"note":"test"}),
          evidence_ref_id: Some("ref:artifact:test".to_string()),
          created_by: Some("user:test".to_string()),
          created_ms: 100,
          updated_ms: 200,
        },
      );
    }
    save_migration_run_store(&run_store, &runtime).expect("save migration run store");
    let loaded_runs = load_migration_run_store(&runtime).expect("load migration run store");
    let run = loaded_runs
      .by_key
      .get(&migration_run_key("orgA", "mrn_1"))
      .expect("loaded migration run");
    assert_eq!(run.status, "failed");
    assert_eq!(run.project_id, "projA");
    cleanup_runtime(&runtime);
  }

