  #[test]
  fn runtime_call_world_request_requires_shared_request_field() {
    let _freecat_runtime_call_guard = freecat_runtime_call_test_guard();
    reset_freecat_world_host_store();
    let harness = RpcHarness::new("runtime-call-request-required");
    let auth = test_auth_context();
    let mut payload = sample_runtime_call_world_payload();
    payload
      .as_object_mut()
      .expect("runtime.call payload object")
      .remove("request");

    let response = harness.call(1, "runtime.call", payload, &auth);

    assert_eq!(response.get("status"), Some(&json!("error")));
    assert_eq!(
      response.pointer("/error/data/reason_code"),
      Some(&json!(RUNTIME_CALL_REASON_REQUEST_REQUIRED))
    );

    let (_, events, _) = harness.events.poll_since(
      0,
      256,
      Some(&remote_event_filter(&[
        "runtime.call.requested",
        "runtime.call.error",
      ])),
    );
    assert!(
      !events
        .iter()
        .any(|event| event.kind == "runtime.call.requested"),
      "runtime.call.requested must not be emitted when shared request is missing"
    );
    assert!(
      events.iter().any(|event| {
        event.kind == "runtime.call.error"
          && event.payload.get("reason_code") == Some(&json!(RUNTIME_CALL_REASON_REQUEST_REQUIRED))
      }),
      "missing runtime.call.error with request-required reason"
    );

    cleanup_runtime(&harness.runtime);
  }

