  #[test]
  fn runtime_ontology_candidates_background_syncs_meaning_db_and_namespace_lineage() {
    let _phase60_63_guard = phase60_63_test_guard();
    reset_runtime_ontology_sync_store();

    let (addr, handle) = match spawn_mock_nrepl_server_for(
      b"meaning/put",
      br#"{"ok":true,"id":"meaning/generated.runtime.root"}"#,
    ) {
      Ok(value) => value,
      Err(err) if err.kind() == std::io::ErrorKind::PermissionDenied => {
        eprintln!("skip runtime ontology sync test: local socket bind not permitted");
        return;
      }
      Err(err) => panic!("mock nrepl server: {err}"),
    };

    let previous_addr = std::env::var("PNIX_STORAGE_NREPL_ADDR").ok();
    let previous_token = std::env::var("PNIX_STORAGE_NREPL_TOKEN").ok();
    std::env::set_var("PNIX_STORAGE_NREPL_ADDR", &addr);
    std::env::remove_var("PNIX_STORAGE_NREPL_TOKEN");

    let payload = sample_runtime_ontology_sync_payload();
    let first = sync_runtime_ontology_candidates(DEFAULT_NAMESPACE, &payload);
    let second = sync_runtime_ontology_candidates(DEFAULT_NAMESPACE, &payload);

    if let Some(value) = previous_addr {
      std::env::set_var("PNIX_STORAGE_NREPL_ADDR", value);
    } else {
      std::env::remove_var("PNIX_STORAGE_NREPL_ADDR");
    }
    if let Some(value) = previous_token {
      std::env::set_var("PNIX_STORAGE_NREPL_TOKEN", value);
    } else {
      std::env::remove_var("PNIX_STORAGE_NREPL_TOKEN");
    }

    assert!(first.success(), "first sync must succeed: {first:?}");
    assert_eq!(first.candidate_count, 1);
    assert_eq!(first.contextual_fact_count, 1);
    assert_eq!(
      first.contextual_fact_predicates,
      vec!["describes-entity".to_string()]
    );
    assert_eq!(first.meaning_synced_count, 1);
    assert_eq!(first.lineage_summary_count, 1);
    assert_eq!(
      first.candidate_ids,
      vec!["meaning/generated.runtime.root".to_string()]
    );
    assert_eq!(
      first.lineage_summaries[0].meaning_entity_id,
      "meaning/generated.runtime.root"
    );
    assert!(first.lineage_summaries[0].meaning_entity_created);

    assert!(second.success(), "second sync must succeed: {second:?}");
    assert_eq!(second.candidate_count, 1);
    assert_eq!(second.meaning_synced_count, 1);
    assert_eq!(second.lineage_summary_count, 1);
    assert!(!second.lineage_summaries[0].meaning_entity_created);

    reset_runtime_ontology_sync_store();
    let _ = handle.join();
  }

  #[test]
  fn runtime_ontology_candidates_background_sync_reports_meaning_db_failure_without_blocking_lineage(
  ) {
    let _phase60_63_guard = phase60_63_test_guard();
    reset_runtime_ontology_sync_store();

    let previous_addr = std::env::var("PNIX_STORAGE_NREPL_ADDR").ok();
    let previous_token = std::env::var("PNIX_STORAGE_NREPL_TOKEN").ok();
    std::env::set_var("PNIX_STORAGE_NREPL_ADDR", "127.0.0.1:1");
    std::env::remove_var("PNIX_STORAGE_NREPL_TOKEN");

    let report =
      sync_runtime_ontology_candidates(DEFAULT_NAMESPACE, &sample_runtime_ontology_sync_payload());

    if let Some(value) = previous_addr {
      std::env::set_var("PNIX_STORAGE_NREPL_ADDR", value);
    } else {
      std::env::remove_var("PNIX_STORAGE_NREPL_ADDR");
    }
    if let Some(value) = previous_token {
      std::env::set_var("PNIX_STORAGE_NREPL_TOKEN", value);
    } else {
      std::env::remove_var("PNIX_STORAGE_NREPL_TOKEN");
    }

    assert_eq!(report.candidate_count, 1);
    assert_eq!(report.contextual_fact_count, 1);
    assert_eq!(
      report.contextual_fact_predicates,
      vec!["describes-entity".to_string()]
    );
    assert_eq!(report.meaning_synced_count, 0);
    assert!(report.meaning_sync_error.is_some());
    assert_eq!(report.lineage_summary_count, 1);
    assert!(report.lineage_sync_error.is_none());

    reset_runtime_ontology_sync_store();
  }

  #[test]
  fn runtime_call_world_request_persists_history_per_namespace() {
    let _freecat_runtime_call_guard = freecat_runtime_call_test_guard();
    reset_freecat_world_host_store();
    let harness = RpcHarness::new("runtime-call-history");
    let auth = test_auth_context();

    let upsert = harness.call(
      4,
      "runtime.call",
      sample_runtime_call_world_upsert_payload(),
      &auth,
    );
    assert_eq!(upsert.get("status"), Some(&json!("ok")));
    assert_eq!(
      upsert.pointer("/outputs/response/result/outcome/snapshot/point_binding_count"),
      Some(&json!(1))
    );

    let undo_request = VmCallRequest::new(
      "vmcall-undo",
      43,
      FREECAT_APPLY_WORLD_EDIT_METHOD,
      WorldEditEnvelope::new(WorldEditCommand::Undo)
        .with_patch_id("patch-undo")
        .with_idempotency_key("ik-undo")
        .with_committer("sequencer")
        .to_json_value(),
    )
    .with_fixed_dt_ms(16);
    let undo = harness.call(
      5,
      "runtime.call",
      undo_request.to_runtime_call_payload().to_json_value(),
      &auth,
    );
    assert_eq!(undo.get("status"), Some(&json!("ok")));
    assert_eq!(
      undo.pointer("/outputs/response/result/outcome/snapshot/point_binding_count"),
      Some(&json!(0))
    );
    assert_eq!(
      undo.pointer("/outputs/response/result/outcome/patch_ref"),
      Some(&json!("scene.patch.px:replay:undo:1"))
    );

    cleanup_runtime(&harness.runtime);
  }

  #[test]
  fn runtime_call_non_world_target_remains_fail_closed() {
    let _freecat_runtime_call_guard = freecat_runtime_call_test_guard();
    reset_freecat_world_host_store();
    let harness = RpcHarness::new("runtime-call-host-unavailable");
    let auth = test_auth_context();

    let response = harness.call(
      6,
      "runtime.call",
      json!({
        "backend": "python/default",
        "method": "tool.run",
        "args": {
          "tool": "echo"
        },
        "opts": {
          "timeout_ms": 1000
        }
      }),
      &auth,
    );

    assert_eq!(response.get("status"), Some(&json!("error")));
    assert_eq!(
      response.pointer("/error/data/reason_code"),
      Some(&json!(RUNTIME_CALL_REASON_HOST_UNAVAILABLE))
    );

    let (_, events, _) = harness.events.poll_since(
      0,
      256,
      Some(&remote_event_filter(&[
        "runtime.call.requested",
        "runtime.call.error",
      ])),
    );
    assert!(
      events
        .iter()
        .any(|event| event.kind == "runtime.call.requested"),
      "missing runtime.call.requested for non-world target"
    );
    assert!(
      events.iter().any(|event| {
        event.kind == "runtime.call.error"
          && event.payload.get("reason_code") == Some(&json!(RUNTIME_CALL_REASON_HOST_UNAVAILABLE))
      }),
      "missing runtime.call.error with host-unavailable reason"
    );

    cleanup_runtime(&harness.runtime);
  }

  #[test]
  fn remote_execute_rejects_anonymous_token_with_reason_code() {
    let harness = RpcHarness::new("remote-exec-token-required");
    let auth = test_auth_context_with_token("anonymous");

    let response = harness.call(
      1,
      "remote.execute",
      json!({
        "change_id": "chg-token-required",
        "channel": "prod",
        "capability_manifest": {
          "required_caps": ["change:execute"],
          "granted_caps": ["change:execute"],
        },
        "preflight": remote_preflight(
          DEFAULT_NAMESPACE,
          "chg-token-required",
          Some("prod"),
          true,
        ),
      }),
      &auth,
    );

    assert_eq!(response.get("status"), Some(&json!("error")));
    assert_eq!(
      response.pointer("/error/data/reason_code"),
      Some(&json!("REMOTE_TOKEN_REQUIRED"))
    );

    let (_, events, _) = harness.events.poll_since(
      0,
      256,
      Some(&remote_event_filter(&[
        "remote.execute.requested",
        "remote.execute.error",
      ])),
    );
    assert!(
      events
        .iter()
        .any(|event| event.kind == "remote.execute.requested"),
      "missing remote.execute.requested event"
    );
    assert!(
      events.iter().any(|event| {
        event.kind == "remote.execute.error"
          && event.payload.get("reason_code") == Some(&json!("REMOTE_TOKEN_REQUIRED"))
      }),
      "missing remote.execute.error with REMOTE_TOKEN_REQUIRED"
    );

    cleanup_runtime(&harness.runtime);
  }

  #[test]
  fn remote_execute_rejects_invalid_capability_manifest_entries() {
    let harness = RpcHarness::new("remote-exec-cap-manifest-invalid");
    let auth = test_auth_context();
    let change_id = "chg-capability-manifest-invalid";

    seed_change_request(
      &harness.change_requests,
      DEFAULT_NAMESPACE,
      change_id,
      "approved",
      vec![PlanStepEntry {
        step_no: 1,
        kind: "noop".to_string(),
        spec_json: json!({}),
        status: "pending".to_string(),
        started_ms: None,
        finished_ms: None,
        last_error: None,
      }],
    );

    let response = harness.call(
      2,
      "remote.execute",
      json!({
        "change_id": change_id,
        "channel": "prod",
        "capability_manifest": {
          "required_caps": ["change:execute", 42],
          "granted_caps": ["change:execute", 42],
        },
        "preflight": remote_preflight(DEFAULT_NAMESPACE, change_id, Some("prod"), true),
      }),
      &auth,
    );

    assert_eq!(response.get("status"), Some(&json!("error")));
    assert_eq!(
      response.pointer("/error/data/reason_code"),
      Some(&json!("REMOTE_CAPABILITY_MANIFEST_INVALID"))
    );
    let queued_jobs = harness
      .job_store
      .read()
      .unwrap_or_else(|e| e.into_inner())
      .by_key
      .len();
    assert_eq!(
      queued_jobs, 0,
      "remote.execute must not enqueue on malformed capability manifest"
    );

    let (_, events, _) = harness.events.poll_since(
      0,
      256,
      Some(&remote_event_filter(&[
        "remote.execute.requested",
        "remote.execute.approved",
        "remote.execute.enqueued",
        "remote.execute.error",
      ])),
    );
    assert!(
      events
        .iter()
        .any(|event| event.kind == "remote.execute.requested"),
      "missing remote.execute.requested event"
    );
    assert!(
      !events
        .iter()
        .any(|event| event.kind == "remote.execute.approved"),
      "remote.execute.approved must not be emitted on manifest invalid"
    );
    assert!(
      !events
        .iter()
        .any(|event| event.kind == "remote.execute.enqueued"),
      "remote.execute.enqueued must not be emitted on manifest invalid"
    );
    assert!(
      events.iter().any(|event| {
        event.kind == "remote.execute.error"
          && event.payload.get("reason_code") == Some(&json!("REMOTE_CAPABILITY_MANIFEST_INVALID"))
      }),
      "missing remote.execute.error with REMOTE_CAPABILITY_MANIFEST_INVALID"
    );

    cleanup_runtime(&harness.runtime);
  }

